(window.JCPA_DATA=window.JCPA_DATA||{})["banks"]={"id":"banks","name":"قانون البنوك","full":"قانون البنوك رقم (28) لسنة 2000 وتعديلاته","icon":"🏦","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون البنوك لسنة ٢٠٠٠) ويعمل به من تاريخ نشره في الجريدة الرسمية.","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون البنوك لسنة ٢٠٠٠ يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون البنوك لسنة ٢٠٠٠ اعتباراً من:","o":["تاريخ نشره في الجريدة الرسمية","مرور ثلاثين يوماً على نشره في الجريدة الرسمية","تاريخ مصادقة مجلس الوزراء عليه","بداية السنة المالية التالية لنشره"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"أ- يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها أدناه ما لم تدل القرينة على غير ذلك:\nالبنك المركزي:البنك المركزي الأردني.\nالمجلس:مجلس إدارة البنك المركزي.\nالمحافظ:محافظ البنك المركزي.\nالبنـــك:الشركة التي يرخص لها بممارسة الأعمال المصرفية وفق أحكام هذا القانون بما ذلك فرع البنك الأجنبي المرخص له بالعمل في المملكة.\nالبنـــك الإســـلامي: الشركة التي يرخص لها بممارسة الأعمال المصرفية بما يتفق مع أحكام الشريعة الإسلامية ومبادئها وأي أعمال وأنشطة أخرى وفق أحكام هذا القانون.\nالشــركة الماليــة:الشركة التي ينص عقد تأسيسها ونظامها الأساسي على أن من غاياتها ممارسة أنشطة مالية باستثناء قبول الودائع غير مشروطة التوظيف.\nالوديعة:مبلغ من النقود يسلمه شخص بأي وسيلة من وسائل الدفع إلى شخص آخر الذي يلتزم برده لدى الطلب أو وفقاً للشروط المتفق عليها ويكتسب المودع لديه ملكية النقود المودعة ويكون له الحق في التصرف فيها مع التزامه برد مثلها للمودع ويكون الرد بذات نوع العملة المودعة.\nالائتمان:دفع مبلغ من المال من البنك إلى العميل مقابل حق استرداده مع فوائده وأي مستحقات أخرى عليه وأي ضمان أو كفالة أو تعهد يصدره البنك.\nالأعمــال المصــرفية: قبول الودائع من الجمهور واستخدامها بصورة كلية أو جزئية لمنح الائتمان وأي أعمال أخرى يقرر البنك المركزي اعتبارها أعمالاً مصرفية بموجب أوامر يصدرها لهذه الغاية.\nالأعمــال المصــرفية الإســلامية: الأعمال القائمة على غير أساس الفائدة في مجال قبول الودائع والخدمات المصرفية الأخرى وفي مجال التمويل والاستثمار بما يتفق مع أحكام الشريعة الإسلامية ومبادئها.\nالأوامــر:التعليمات أو القرارات الصادرة عن البنك المركزي لتنفيذ أحكام هذا القانون.\nرأس المــال التنظيمــي:إجمالي قيمة العناصر التي يحددها البنك المركزي لأغراض رقابية تلبيةً لمتطلبات نسبة كفاية رأس المال المقررة بموجب أوامر يصدرها البنك المركزي.\nالشخـص:الشخص الطبيعي أو الاعتباري .\nالإداري:عضو مجلس إدارة البنك سواءً بصفته الشخصية أو بصفته ممثلاً لشخص اعتباري أو مدير عام البنك أو أي موظف فيه.\nالعضـــو المســـتقل:عضو مجلس إدارة البنك من غير المساهمين الرئيسيين وممن لا يكون تحت سيطرة أي منهم ومن ذوي المؤهلات أو الخبرات المالية أو المصرفية وفق الشروط والمتطلبات التي يحددها البنك المركزي.\nالسيطرة:القدرة المباشرة أو غير المباشرة على ممارسة تأثير فعال على أعمال شخص آخر وقراراته.\nالمصلحة المؤثرة :السيطرة على ما لا يقل عن (%١٠) من رأسمال شخص اعتباري.\nالمساهم الرئيسي في البنك:الشخص المسيطر على ما لا يقل عن (%٥) من رأسمال البنك.\nالحليــــف:الشخص الذي يسيطر على شخص آخر أو يسيطر عليه ذلك الشخص أو يسيطر عليهما معاً شخص آخر.\nالشركة التابعة:لشركة التي يملك فيها شخص أو مجموعة أشخاص، تجمعهم مصلحة واحدة، ما لا يقل عن (%٥٠) من رأسمالها أو يملك هذا الشخص أو هؤلاء الأشخاص مصلحة مؤثرة فيها تسمح بالسيطرة على إدارتها أو على سياستها العامة.\nذو الصـــلة:شخصان، أو أكثر، يشكلان مخاطرة مصرفية واحدة بسبب سيطرة أحدهما على الآخر أو تملك أحدهما ما لا يقل عن (%٤٠) من رأسمال الشخص الآخر أو نظراً لتبادلهما تقديم الضمانات فيما بينهما أو لأن سداد قروضهما من مصدر واحد أو لأن اقتراضهما كان لمشروع واحد أو ما شابه ذلك من الحالات، ولمقاصد هذا القانون يعتبر ذوو الصلة شخصاً واحداً.\nب- يقصد بعبارات: الأوراق المالية، المستشار المالي، أمين الاستثمار، ومدير الاستثمار حيثما وردت في هذا القانون المعاني المخصصة لها بمقتضى قانون الأوراق المالية النافذ المفعول.","title":"التعاريف","memo":"⭐ المصلحة المؤثرة: السيطرة على ما لا يقل عن (%١٠) من رأسمال شخص اعتباري\n⭐ المساهم الرئيسي: المسيطر على ما لا يقل عن (%٥) من رأسمال البنك\n⭐ الشركة التابعة: ملكية ما لا يقل عن (%٥٠) من رأسمالها أو مصلحة مؤثرة تسمح بالسيطرة\n⭐ ذو الصلة: سيطرة أو تملك ما لا يقل عن (%٤٠) من رأسمال الآخر أو تبادل الضمانات أو مصدر سداد واحد… ويعتبرون شخصاً واحداً","qs":[{"q":"وفقاً لقانون البنوك، تعني «المصلحة المؤثرة» السيطرة على ما لا يقل عن:","o":["(%١٠) من رأسمال شخص اعتباري","(%٥) من رأسمال شخص اعتباري","(%٢٠) من رأسمال شخص اعتباري","(%٤٠) من رأسمال شخص اعتباري"],"a":0},{"q":"يعتبر الشخص «مساهماً رئيسياً في البنك» إذا كان مسيطراً على ما لا يقل عن:","o":["(%٥) من رأسمال البنك","(%١٠) من رأسمال البنك","(%٢٥) من رأسمال البنك","(%٥٠) من رأسمال البنك"],"a":0},{"q":"شركتان تتبادلان تقديم الضمانات فيما بينهما، وتملك إحداهما (%٤٠) من رأسمال الأخرى. وفقاً لقانون البنوك تعتبران:","o":["ذوي صلة ويعتبران شخصاً واحداً","حليفين ويعامل كل منهما بشكل مستقل","شركة قابضة وشركة تابعة لها حكماً","مساهمين رئيسيين في بعضهما"],"a":0},{"q":"أي مما يلي لا يعد «إدارياً» في البنك وفق تعريف القانون؟","o":["المساهم الرئيسي غير العضو في مجلس الإدارة وغير الموظف","عضو مجلس الإدارة بصفته ممثلاً لشخص اعتباري","مدير عام البنك","أي موظف في البنك"],"a":0}]},{"n":"3","chapter":"أحكام عامة","notes":[],"source":"أ- تسري أحكام هذا القانون على كل من يمارس الأعمال المصرفية، إلا أنه يجوز للبنك المركزي بموجب أوامر خاصة يصدرها لهذه الغاية أن يستثني أشخاصا معينين من أي إجراءات أو متطلبات محددة فيه نظراً لطبيعة أعمالهم أو حجمها أو بسبب مصادر أموالهم أو لأي اعتبار آخر.\nب- يخضع البنك الإسلامي للأحكام الخاصة بالبنوك الإسلامية الواردة في هذا القانون، كما تسري عليه أحكام هذا القانون والقوانين الأخرى ذات العلاقة بالقدر الذي لا تتعارض فيه مع تلك الأحكام.\nج- يجوز للبنك المركزي إذا وجد ذلك ضرورياً أن يخضع أي شركة مالية لأي من أحكام هذا القانون بموجب أوامر خاصة يصدرها لهذه الغاية.","title":"نطاق سريان القانون","memo":"⭐ يسري على كل من يمارس الأعمال المصرفية، وللبنك المركزي استثناء أشخاص معينين بأوامر خاصة\n⭐ البنك الإسلامي يخضع لأحكامه الخاصة ثم لأحكام القانون بما لا يتعارض معها\n⭐ للبنك المركزي إخضاع أي شركة مالية لأي من أحكام القانون بأوامر خاصة","qs":[{"q":"الجهة المخولة باستثناء أشخاص معينين من أي إجراءات أو متطلبات في قانون البنوك نظراً لطبيعة أعمالهم أو حجمها هي:","o":["البنك المركزي بموجب أوامر خاصة","مجلس الوزراء بناءً على تنسيب المحافظ","وزير المالية","مراقب عام الشركات"],"a":0},{"q":"تسري أحكام قانون البنوك والقوانين الأخرى ذات العلاقة على البنك الإسلامي:","o":["بالقدر الذي لا تتعارض فيه مع الأحكام الخاصة بالبنوك الإسلامية","بشكل كامل وتتقدم على الأحكام الخاصة بالبنوك الإسلامية","فقط بموافقة هيئة الرقابة الشرعية","فقط في حال عدم وجود نص في نظامه الأساسي"],"a":0},{"q":"يجوز للبنك المركزي أن يخضع أي شركة مالية لأي من أحكام قانون البنوك:","o":["إذا وجد ذلك ضرورياً بموجب أوامر خاصة يصدرها","بعد موافقة الهيئة العامة للشركة المالية","بقرار من مجلس الوزراء","إذا قبلت الودائع غير مشروطة التوظيف فقط"],"a":0}]},{"n":"4","chapter":"أحكام عامة","notes":[],"source":"أ- يحظر على أي شخص أن يقوم بأي من الأعمال المصرفية إلا بعد منحه الترخيص النهائي من البنك المركزي وفق أحكام هذا القانون.\nب-يحظر على الشخص غير المرخص له بممارسة الأعمال المصرفية قبول الودائع دون موافقة خطية مسبقة من البنك المركزي.\nج- يحظر على الشركة المالية أن تمارس عملاً أو نشاطاً يتعارض مع أوامر البنك المركزي الصادرة وفق أحكام الفقرة (ج) من المادة (٣) من هذا القانون.\nد- يحظر على أي شخص أن يستعمل بأي صورة كانت كلمة بنك أو مرادفاتها سواءً باللغة العربية أو بأي لغة أجنبية أو أن يستعمل في أوراقه ووثائقه ودعاياته أي لفظة أو عبارة لها علاقة بالأعمال المصرفية أو تحمل دلالة عليها إلا في الحالات التالية:\n١- إذا كان هذا الاستعمال جائزاً بموجب أي قانون أو أي اتفاقية دولية تكون المملكة طرفاً فيها.\n٢- إذا دلّ السياق على أن الاستعمال لا يمت بصلة للأعمال المصرفية.\n٣- إذا صدر قرار من مجلس الوزراء بناءً على تنسيب المحافظ يسمح بهذا الاستعمال.\nه- يحظر على أي شخص أن يدلي بمعلومات مضللة أو يقدم للغير معلومات مغلوطة تتعلق بقبول الودائع.","title":"حظر ممارسة الأعمال المصرفية دون ترخيص","memo":"⭐ لا تمارس الأعمال المصرفية إلا بعد الترخيص النهائي من البنك المركزي\n⭐ غير المرخص لا يقبل الودائع إلا بموافقة خطية مسبقة من البنك المركزي\n⭐ استعمال كلمة «بنك» محظور إلا: بقانون أو اتفاقية دولية، أو سياق لا صلة له بالمصارف، أو قرار مجلس الوزراء بتنسيب المحافظ","qs":[{"q":"لا يجوز لأي شخص ممارسة أي من الأعمال المصرفية إلا بعد:","o":["منحه الترخيص النهائي من البنك المركزي","حصوله على الموافقة المبدئية من البنك المركزي","تسجيله لدى وزارة الصناعة والتجارة","حصوله على موافقة مجلس الوزراء"],"a":0},{"q":"يجوز استعمال كلمة «بنك» أو مرادفاتها إذا صدر قرار بذلك من:","o":["مجلس الوزراء بناءً على تنسيب المحافظ","المحافظ بناءً على تنسيب المجلس","وزير الصناعة والتجارة","مراقب عام الشركات بموافقة البنك المركزي"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي يجوز فيها استعمال كلمة «بنك» أو مرادفاتها؟","o":["إذا كان المستعمل شركة مالية مسجلة لدى مراقب الشركات","إذا كان الاستعمال جائزاً بموجب اتفاقية دولية تكون المملكة طرفاً فيها","إذا دل السياق على أن الاستعمال لا يمت بصلة للأعمال المصرفية","إذا صدر قرار من مجلس الوزراء بناءً على تنسيب المحافظ"],"a":0}]},{"n":"5","chapter":"أحكام عامة","notes":[],"source":"أ- كل من يخالف أحكام المادة (٤) من هذا القانون يعاقب بقرار من المجلس بغرامة لا تقل عن خمسمائة دينار ولا تزيد على ثلاثة آلاف دينار عن كل يوم منذ اليوم الأول لوقوع المخالفة وطوال مدة استمرارها.\nب- إذا استمرت المخالفة على الرغم من فرض العقوبة المنصوص عليها في الفقرة (أ) من هذه المادة أو إذا تكرر وقوعها بعد فرض العقوبة، يجوز للمجلس اتخاذ ما يراه لازماً من الإجراءات لمنع المخالفة بما في ذلك إصدار الأمر بإغلاق محل الشخص المخالف.","title":"عقوبة مخالفة أحكام المادة (٤)","memo":"⭐ غرامة بقرار من المجلس: لا تقل عن ٥٠٠ دينار ولا تزيد على ٣٠٠٠ دينار عن كل يوم طوال مدة استمرار المخالفة\n⭐ عند الاستمرار أو التكرار: للمجلس اتخاذ ما يلزم بما في ذلك إغلاق محل المخالف","qs":[{"q":"يعاقب من يخالف أحكام المادة (٤) من قانون البنوك بغرامة عن كل يوم:","o":["لا تقل عن خمسمائة دينار ولا تزيد على ثلاثة آلاف دينار","لا تقل عن ألف دينار ولا تزيد على خمسة آلاف دينار","لا تقل عن مائة دينار ولا تزيد على ألف دينار","لا تقل عن ثلاثة آلاف دينار ولا تزيد على عشرة آلاف دينار"],"a":0},{"q":"تفرض الغرامة على مخالفة أحكام المادة (٤) من قانون البنوك بقرار من:","o":["المجلس","المحكمة المختصة","المحافظ","وزير المالية"],"a":0},{"q":"إذا تكررت مخالفة أحكام المادة (٤) بعد فرض الغرامة، فإن للمجلس:","o":["اتخاذ ما يراه لازماً بما في ذلك إصدار الأمر بإغلاق محل المخالف","مضاعفة الغرامة فقط دون أي إجراء آخر","إحالة المخالف إلى مجلس الوزراء لإغلاق محله","الحبس مدة لا تزيد على سنة"],"a":0}]},{"n":"6","chapter":"ترخيص البنك","notes":[],"source":"أ - يشترط لترخيص البنك أن يكون شركة مساهمة عامة، ويستثنى من ذلك ما يلي:\n١- فرع البنك الأجنبي.\n٢- الشركة التابعة.\n٣- الشركة المعفاة.\nب- يتم ترخيص البنك بقرار من البنك المركزي وفقاً للمتطلبات والشروط المنصوص عليها في هذا القانون.\nج- إذا كان البنك شركة تابعة لبنك آخر، فيجري ترخيصه وفقاً للمتطلبات والشروط المنصوص عليها في هذا القانون وأي متطلبات أو شروط أخرى تحددها أوامر البنك المركزي.\nد- إذا كان البنك شركة معفاة، فيجري ترخيصه وفقاً للمتطلبات والشروط التي يحددها نظام خاص يصدر لهذه الغاية وأي متطلبات أو شروط أخرى تحددها أوامر البنك المركزي.","title":"الشكل القانوني للبنك وترخيصه","memo":"⭐ يشترط أن يكون البنك شركة مساهمة عامة باستثناء: فرع البنك الأجنبي، الشركة التابعة، الشركة المعفاة\n⭐ الترخيص بقرار من البنك المركزي\n⭐ الشركة المعفاة يرخص لها وفق نظام خاص وأوامر البنك المركزي","qs":[{"q":"يشترط لترخيص البنك أن يكون:","o":["شركة مساهمة عامة","شركة ذات مسؤولية محدودة","شركة مساهمة خاصة","شركة توصية بالأسهم"],"a":0},{"q":"أي مما يلي لا يعد من الاستثناءات على شرط أن يكون البنك شركة مساهمة عامة؟","o":["البنك الإسلامي","فرع البنك الأجنبي","الشركة التابعة","الشركة المعفاة"],"a":0},{"q":"يجري ترخيص البنك الذي يكون شركة معفاة وفقاً للمتطلبات والشروط التي يحددها:","o":["نظام خاص يصدر لهذه الغاية وأوامر البنك المركزي","قانون الشركات فقط","قرار من مجلس الوزراء","الهيئة العامة للبنك"],"a":0}]},{"n":"7","chapter":"ترخيص البنك","notes":[],"source":"أ- تقدم لجنة المؤسسين طلب ترخيص البنك على الأنموذج المعد لهذه الغاية لدى البنك المركزي مبيناً فيه ما يلي:\n١- مقدار رأسمال البنك المصرح به وما سيطرح منه للاكتتاب.\n٢- الاسم الرباعي لكل مؤسس، على أن تقدم بيانات عن المؤسس الذي يساهم بما لا يقل عن (%٥) من رأسمال البنك تشمل مكان إقامته وسيرته الذاتية مع وجوب بيان إذا كان أي من المؤسسين حليفاً لمؤسس آخر.\n٣- أي معلومات أو بيانات إضافية تتطلبها أوامر البنك المركزي أو يراها ضرورية لاتخاذ قراره في طلب الترخيص.\nب- يرفق بطلب الترخيص ما يلي:\n١- عقد تأسيس البنك ونظامه الأساسي.\n٢- الهيكل التنظيمي للبنك وخطة عمله ومجال نشاطه.\n٣- الميزانيات التقديرية المقترحة للسنوات الثلاث الأولى من عمل البنك والأسس التي تم اعتمادها في إعدادها.","title":"طلب ترخيص البنك ومرفقاته","memo":"⭐ تقدم لجنة المؤسسين الطلب لدى البنك المركزي\n⭐ بيانات تفصيلية (مكان الإقامة والسيرة الذاتية) للمؤسس المساهم بما لا يقل عن (%٥)، مع بيان التحالف بين المؤسسين\n⭐ المرفقات: عقد التأسيس والنظام الأساسي، الهيكل التنظيمي وخطة العمل، الميزانيات التقديرية للسنوات الثلاث الأولى","qs":[{"q":"يقدم طلب ترخيص البنك لدى البنك المركزي من قبل:","o":["لجنة المؤسسين","مجلس الإدارة المقترح","المدير العام المقترح","مراقب عام الشركات"],"a":0},{"q":"يجب تقديم بيانات تشمل مكان الإقامة والسيرة الذاتية للمؤسس الذي يساهم بما لا يقل عن:","o":["(%٥) من رأسمال البنك","(%١٠) من رأسمال البنك","(%٢٠) من رأسمال البنك","(%١) من رأسمال البنك"],"a":0},{"q":"يرفق بطلب ترخيص البنك ميزانيات تقديرية مقترحة لـ:","o":["السنوات الثلاث الأولى من عمل البنك","السنة الأولى من عمل البنك","السنتين الأوليين من عمل البنك","السنوات الخمس الأولى من عمل البنك"],"a":0}]},{"n":"8","chapter":"ترخيص البنك","notes":[],"source":"يحدد البنك المركزي مقدار الحد الأدنى لكل من رأس المال المصرح به للبنك ورأسماله المكتتب به، وله أن يعدل هذين الحدين من وقت لآخر للبنوك كلها أو بعضها في ضوء متطلبات سلامة العمل المصرفي وتطويره.","title":"الحد الأدنى لرأس المال","memo":"⭐ البنك المركزي يحدد الحد الأدنى لرأس المال المصرح به والمكتتب به\n⭐ له تعديلهما من وقت لآخر للبنوك كلها أو بعضها في ضوء سلامة العمل المصرفي","qs":[{"q":"الجهة التي تحدد الحد الأدنى لرأس المال المصرح به والمكتتب به للبنك هي:","o":["البنك المركزي","مجلس الوزراء","وزير المالية","الهيئة العامة للبنك"],"a":0},{"q":"وفقاً لقانون البنوك، فإن تعديل الحد الأدنى لرأس مال البنوك يكون:","o":["من وقت لآخر للبنوك كلها أو بعضها في ضوء متطلبات سلامة العمل المصرفي","مرة كل خمس سنوات لجميع البنوك بالتساوي","بتعديل القانون فقط","بقرار من الهيئة العامة لكل بنك"],"a":0}]},{"n":"9","chapter":"ترخيص البنك","notes":[],"source":"أ- يصدر البنك المركزي قراره في طلب الترخيص المقدم إليه خلال ثلاثة أشهر من تاريخ تقديمه سواء بالموافقة المبدئية على الطلب أو برفضه، ويتم إشعار طالب الترخيص بهذا القرار.\nب- إذا أصدر البنك المركزي قراره بالموافقة المبدئية على طلب الترخيص فعليه أن يحدد فيه المتطلبات والشروط اللازمة للحصول على الترخيص النهائي، بما في ذلك ما يلي:\n١- مقدار الحد الأدنى لرأسمال البنك المصرح به وما سيطرح منه للاكتتاب.\n٢- تسديد كامل رأس المال المكتتب به.\n٣- استكمال جميع إجراءات تأسيس البنك.\n٤- الأسماء المقترحة لمنصب المدير العام ومراكز الإدارة العليا في البنك.\n٥- بيان بالتجهيزات وبالمعدات وبالعقارات اللازمة لأعماله.\n٦- أي متطلبات وشروط أخرى تحددها أوامر البنك المركزي.\nج- تعتبر الموافقة المبدئية ملغاة حكماً إذا لم يستوف طالب الترخيص خلال سنة من تاريخ حصوله عليها جميع المتطلبات والشروط اللازمة للحصول على الترخيص النهائي.","title":"الموافقة المبدئية على طلب الترخيص","memo":"⭐ يصدر قرار البنك المركزي (موافقة مبدئية أو رفض) خلال ثلاثة أشهر من تقديم الطلب\n⭐ الموافقة المبدئية تحدد متطلبات الترخيص النهائي (منها تسديد كامل رأس المال المكتتب به)\n⭐ تلغى الموافقة المبدئية حكماً إذا لم تستوف المتطلبات خلال سنة من تاريخ الحصول عليها","qs":[{"q":"يصدر البنك المركزي قراره في طلب الترخيص خلال:","o":["ثلاثة أشهر من تاريخ تقديمه","شهر من تاريخ تقديمه","ستين يوماً من تاريخ تقديمه","سنة من تاريخ تقديمه"],"a":0},{"q":"تعتبر الموافقة المبدئية على طلب ترخيص البنك ملغاة حكماً إذا لم يستوف طالب الترخيص متطلبات الترخيص النهائي خلال:","o":["سنة من تاريخ حصوله عليها","ستة أشهر من تاريخ حصوله عليها","ثلاثة أشهر من تاريخ حصوله عليها","سنتين من تاريخ حصوله عليها"],"a":0},{"q":"من المتطلبات اللازمة للحصول على الترخيص النهائي للبنك وفق المادة (٩):","o":["تسديد كامل رأس المال المكتتب به","تسديد نصف رأس المال المكتتب به","تسديد ربع رأس المال المصرح به","إيداع كفالة بنكية بقيمة رأس المال"],"a":0}]},{"n":"10","chapter":"ترخيص البنك","notes":[],"source":"أ- إذا تم استكمال متطلبات وشروط الترخيص النهائي المنصوص عليها في الفقرة (ب) من المادة (٩) من هذا القانون يصدر البنك المركزي الترخيص النهائي للبنك خلال ثلاثة أشهر من تاريخ تقديم طلب جديد يؤكد فيه طالب الترخيص استكمال هذه المتطلبات.\nب يمنح البنك المركزي الترخيص النهائي لمدة غير محددة وعلى ألا يكون قابلاً للتحويل.","title":"الترخيص النهائي","memo":"⭐ يصدر الترخيص النهائي خلال ثلاثة أشهر من تقديم طلب جديد يؤكد استكمال المتطلبات\n⭐ يمنح لمدة غير محددة وغير قابل للتحويل","qs":[{"q":"يمنح البنك المركزي الترخيص النهائي للبنك:","o":["لمدة غير محددة وغير قابل للتحويل","لمدة خمس سنوات قابلة للتجديد","لمدة غير محددة وقابل للتحويل بموافقة البنك المركزي","لمدة عشر سنوات وغير قابل للتحويل"],"a":0},{"q":"يصدر البنك المركزي الترخيص النهائي خلال ثلاثة أشهر من تاريخ:","o":["تقديم طلب جديد يؤكد فيه طالب الترخيص استكمال المتطلبات","صدور الموافقة المبدئية","تقديم طلب الترخيص الأول","تسجيل البنك لدى مراقب الشركات"],"a":0}]},{"n":"11","chapter":"ترخيص البنك","notes":[],"source":"أ- يقدم البنك الأجنبي طلب ترخيص فرع له أو أكثر للعمل في المملكة على الوجه الذي تقتضيه أوامر البنك المركزي على أن تتوافر في البنك الأجنبي الشروط التالية:\n١- أن يكون مرخصا له في قبول الودائع في بلد مركزه الرئيسي.\n٢- أن يتمتع بسمعة جيدة ومركز مالي متين.\n٣- أن يكون حاصلا من الجهة المختصة في بلد مركزه الرئيسي على موافقة للعمل في المملكة.\n٤- أن يكون الإشراف عليه من قبل السلطات المختصة في بلد مركزه الرئيسي مستندا إلى أسس سليمة في رقابة الأعمال المصرفية وحدها الأدنى تطبيق معايير الرقابة المصرفية المتعارف عليها دوليا.\n٥- أن يتعهد بالتزام فرعه المرخص له بالعمل في المملكة بجميع التشريعات السارية المفعول.\nب- يصدر البنك المركزي قراره بطلب ترخيص فرع البنك الأجنبي وفق الشروط والإجراءات المتبعة في ترخيص البنك الأردني وأي متطلبات أخرى يراها ضرورية لهذه الغاية.","title":"ترخيص فرع البنك الأجنبي","memo":"⭐ شروط البنك الأجنبي: مرخص بقبول الودائع في بلده، سمعة جيدة ومركز مالي متين، موافقة الجهة المختصة في بلده، رقابة سليمة وفق المعايير الدولية، التعهد بالتزام الفرع بالتشريعات\n⭐ يصدر القرار وفق شروط وإجراءات ترخيص البنك الأردني","qs":[{"q":"أي مما يلي لا يعد من الشروط الواجب توافرها في البنك الأجنبي لترخيص فرع له في المملكة؟","o":["أن يكون شركة مساهمة عامة أردنية","أن يكون مرخصاً له في قبول الودائع في بلد مركزه الرئيسي","أن يتمتع بسمعة جيدة ومركز مالي متين","أن يتعهد بالتزام فرعه بجميع التشريعات السارية"],"a":0},{"q":"يصدر البنك المركزي قراره بطلب ترخيص فرع البنك الأجنبي وفق:","o":["الشروط والإجراءات المتبعة في ترخيص البنك الأردني وأي متطلبات أخرى يراها ضرورية","نظام خاص بالشركات المعفاة","اتفاقية ثنائية مع بلد المركز الرئيسي فقط","قرار من مجلس الوزراء بتنسيب المحافظ"],"a":0},{"q":"يشترط أن يكون البنك الأجنبي حاصلاً على موافقة للعمل في المملكة من:","o":["الجهة المختصة في بلد مركزه الرئيسي","مجلس الوزراء الأردني","وزارة الخارجية الأردنية","هيئة الأوراق المالية"],"a":0}]},{"n":"12","chapter":"ترخيص البنك","notes":[],"source":"أ- لا يجوز لفرع البنك الأجنبي أن يبدأ بممارسة أي من أعماله المصرفية إلا بعد أن يحول إلى المملكة دفعة واحدة مبلغاً يعادل نصف رأس المال المقرر للبنك الأردني، ويجوز للبنك المركزي زيادة هذا المبلغ من وقت لآخر وبحد أقصى رأسمال البنك الأردني.\nب- يعين البنك الأجنبي عند بدء عمله في المملكة سواءً من خلال فرع واحد أو أكثر مديراً إقليمياً مقيماً لفرعه أو فروعه في المملكة وذلك بمقتضى وثيقة رسمية يكون بموجبها مسؤولاً مسؤولية كاملة أمام البنك المركزي والجهات الرسمية الأخرى عن أعمال الفروع وموجوداتها وإدارتها، وتودع في البنك المركزي صورة مصدقة عن هذه الوثيقة.\nج- يلتزم فرع البنك الأجنبي بإبلاغ البنك المركزي عن أي تغيير يطرأ على جنسية ذلك البنك أو عقد تأسيسه أو نظامه الأساسي.","title":"التزامات فرع البنك الأجنبي","memo":"⭐ لا يبدأ العمل إلا بعد تحويل مبلغ يعادل نصف رأس المال المقرر للبنك الأردني دفعة واحدة\n⭐ للبنك المركزي زيادته بحد أقصى رأسمال البنك الأردني\n⭐ تعيين مدير إقليمي مقيم بوثيقة رسمية تودع صورة مصدقة عنها لدى البنك المركزي\n⭐ إبلاغ البنك المركزي عن أي تغيير في الجنسية أو عقد التأسيس أو النظام الأساسي","qs":[{"q":"لا يجوز لفرع البنك الأجنبي أن يبدأ بممارسة أعماله إلا بعد أن يحول إلى المملكة دفعة واحدة مبلغاً يعادل:","o":["نصف رأس المال المقرر للبنك الأردني","كامل رأس المال المقرر للبنك الأردني","ربع رأس المال المقرر للبنك الأردني","ثلث رأس المال المقرر للبنك الأردني"],"a":0},{"q":"يجوز للبنك المركزي زيادة المبلغ الواجب تحويله من فرع البنك الأجنبي بحد أقصى:","o":["رأسمال البنك الأردني","ضعف رأسمال البنك الأردني","نصف رأسمال البنك الأردني","رأسمال المركز الرئيسي للبنك الأجنبي"],"a":0},{"q":"يكون المسؤول مسؤولية كاملة أمام البنك المركزي عن أعمال فروع البنك الأجنبي في المملكة وموجوداتها وإدارتها:","o":["المدير الإقليمي المقيم","رئيس مجلس إدارة المركز الرئيسي","مدير كل فرع بشكل منفرد","مدقق الحسابات الخارجي"],"a":0}]},{"n":"13","chapter":"ترخيص البنك","notes":[],"source":"يستوفي البنك المركزي الرسوم المبينة أدناه على أن تحدد مقاديرها بمقتضى نظام خاص:\nأ- رسم طلب الترخيص.\nب- رسم إصدار الترخيص النهائي.\nج- رسوما سنوية على البنك وكل فرع أو مكتب له.","title":"رسوم الترخيص","memo":"⭐ رسوم يستوفيها البنك المركزي وتحدد مقاديرها بنظام خاص: رسم طلب الترخيص، رسم إصدار الترخيص النهائي، رسوم سنوية على البنك وكل فرع أو مكتب","qs":[{"q":"تحدد مقادير الرسوم التي يستوفيها البنك المركزي من البنوك بمقتضى:","o":["نظام خاص","أوامر يصدرها البنك المركزي","قرار من المحافظ","قرار من وزير المالية"],"a":0},{"q":"أي مما يلي لا يعد من الرسوم التي نصت عليها المادة (١٣) من قانون البنوك؟","o":["رسم تعديل عقد التأسيس","رسم طلب الترخيص","رسم إصدار الترخيص النهائي","رسوم سنوية على البنك وكل فرع أو مكتب له"],"a":0}]},{"n":"14","chapter":"ترخيص البنك","notes":[],"source":"يحتفظ البنك المركزي بسجل خاص لكل بنك يتضمن اسم البنك وعنوان مركزه الرئيسي وفروعه ومكاتبه، كما يحتفظ بنسخ من الوثائق المنصوص عليها في المادة (٧) من هذا القانون.","title":"سجل البنوك لدى البنك المركزي","memo":"⭐ يحتفظ البنك المركزي بسجل خاص لكل بنك: الاسم وعنوان المركز الرئيسي والفروع والمكاتب، ونسخ من وثائق طلب الترخيص (المادة ٧)","qs":[{"q":"يحتفظ البنك المركزي بسجل خاص لكل بنك يتضمن:","o":["اسم البنك وعنوان مركزه الرئيسي وفروعه ومكاتبه","أسماء عملاء البنك وأرصدتهم","أسماء جميع موظفي البنك ورواتبهم","محاضر اجتماعات الهيئة العامة للبنك"],"a":0},{"q":"يحتفظ البنك المركزي في السجل الخاص بكل بنك بنسخ من:","o":["الوثائق المرفقة بطلب الترخيص المنصوص عليها في المادة (٧)","كشوف الحسابات اليومية لعملاء البنك","تقارير لجنة التدقيق الشهرية","عقود الائتمان الممنوحة للإداريين"],"a":0}]},{"n":"15","chapter":"ترخيص البنك","notes":[],"source":"أ-على البنك الاحتفاظ في مركزه الرئيسي بما يلي:\n١- عقد تأسيسه ونظامه الأساسي وتعديلاته.\n٢- سجل بأسماء المساهمين وعدد أسهم كل منهم.\n٣- وثائق محاضر اجتماعات مجلس الإدارة وقراراته ومحاضر لجنة التدقيق.\n٤- وثائق محاضر اجتماعات الهيئة العامة للمساهمين وقراراتها.\n٥- تقاريره السنوية والبيانات الخاصة بحساباته ومركزه المالي وتقارير مدققي الحسابات الخارجيين.\n٦- أي بيانات أو وثائق تتطلبها أوامر البنك المركزي.\nب- على فرع البنك الأجنبي أن يحتفظ بالبيانات والوثائق التي تحددها أوامر البنك المركزي.\nج- على البنك أن يوثق عملياته مع عملائه وان يحتفظ بالمعلومات والبيانات المتعلقة بها بما في ذلك الحسابات الافرادية اليومية لكل منهم.","title":"الوثائق التي يحتفظ بها البنك","memo":"⭐ يحتفظ البنك في مركزه الرئيسي بـ: عقد التأسيس والنظام الأساسي، سجل المساهمين، محاضر مجلس الإدارة ولجنة التدقيق، محاضر الهيئة العامة، التقارير السنوية وتقارير المدققين الخارجيين\n⭐ فرع البنك الأجنبي يحتفظ بما تحدده أوامر البنك المركزي\n⭐ توثيق العمليات مع العملاء بما فيها الحسابات الإفرادية اليومية","qs":[{"q":"يحتفظ البنك بسجل أسماء المساهمين وعدد أسهم كل منهم وعقد تأسيسه في:","o":["مركزه الرئيسي","البنك المركزي","دائرة مراقبة الشركات","أكبر فروعه"],"a":0},{"q":"يحتفظ فرع البنك الأجنبي بالبيانات والوثائق التي تحددها:","o":["أوامر البنك المركزي","تعليمات المركز الرئيسي للبنك الأجنبي","قانون الشركات","هيئة الأوراق المالية"],"a":0},{"q":"أي مما يلي لا يعد من الوثائق التي يلزم البنك بالاحتفاظ بها في مركزه الرئيسي وفق المادة (١٥)؟","o":["سجل بأسماء مساهمي البنوك الأخرى","محاضر لجنة التدقيق","محاضر اجتماعات الهيئة العامة للمساهمين وقراراتها","تقارير مدققي الحسابات الخارجيين"],"a":0}]},{"n":"16","chapter":"ترخيص البنك","notes":[],"source":"لا يجوز للبنك إجراء أي تعديل على عقد تأسيسه أو نظامه الأساسي إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"تعديل عقد التأسيس والنظام الأساسي","memo":"⭐ لا يعدل البنك عقد تأسيسه أو نظامه الأساسي إلا بعد موافقة خطية مسبقة من البنك المركزي","qs":[{"q":"لا يجوز للبنك إجراء أي تعديل على عقد تأسيسه أو نظامه الأساسي إلا بعد الحصول على:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة لاحقة من البنك المركزي","موافقة مجلس الوزراء","إشعار البنك المركزي خلال خمسة عشر يوماً"],"a":0}]},{"n":"17","chapter":"ترخيص البنك","notes":[],"source":"أ- لا يجوز للبنك أن يتوقف عن ممارسة أعماله لأي سبب كان إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.\nب- ولا يجوز للبنك أن يفتح فرعاً أو مكتباً جديداً له داخل المملكة أو خارجها أو أن يغلقه أو ينقل مكانه دون موافقة مسبقة من البنك المركزي .","title":"التوقف عن العمل وفتح الفروع","memo":"⭐ لا يتوقف البنك عن أعماله لأي سبب إلا بموافقة خطية مسبقة من البنك المركزي\n⭐ فتح أو إغلاق أو نقل فرع أو مكتب داخل المملكة أو خارجها يحتاج موافقة مسبقة من البنك المركزي","qs":[{"q":"أراد بنك أردني فتح فرع جديد له خارج المملكة. وفقاً لقانون البنوك فإنه يحتاج إلى:","o":["موافقة مسبقة من البنك المركزي","إشعار البنك المركزي بعد الافتتاح فقط","موافقة مجلس الوزراء","موافقة الهيئة العامة فقط ولا يحتاج لموافقة البنك المركزي"],"a":0},{"q":"لا يجوز للبنك أن يتوقف عن ممارسة أعماله إلا بعد:","o":["الحصول على موافقة خطية مسبقة من البنك المركزي","قرار من الهيئة العامة غير العادية فقط","إعلان ذلك في صحيفتين محليتين","مرور ستين يوماً على إشعار البنك المركزي"],"a":0}]},{"n":"18","chapter":"ترخيص البنك","notes":[],"source":"للبنك المركزي أن يصدر قراراً بإلغاء ترخيص البنك وذلك في أي من الحالات التالية:\nأ- إذا منح الترخيص النهائي بناءً على معلومات غير صحيحة وردت في طلب الترخيص أو الوثائق المرفقة به، وخاصة ما يتعلق بالمؤسسين من ذوي المصالح المؤثرة أو الإداريين المقترحين للعمل في البنك.\nب- إذا لم يبدأ البنك بممارسة أعماله خلال إثنى عشر شهرا من تاريخ حصوله على الترخيص النهائي أو توقف عن قبول الودائع بعد البدء بممارسة أعماله المصرفية.\nج- إذا امتنع البنك عن تنفيذ أي من الإجراءات التي يتخذها البنك المركزي بموجب أحكام المادة (٨٨) من هذا القانون.\nد- إذا قدم البنك طلباً لإلغاء ترخيصه، وعلى البنك المركزي اتخاذ القرار الذي يراه مناسباً بشأن الطلب خلال ستين يوماً من تاريخ تقديمه.\nه- إذا تم إلغاء ترخيص بنك آخر له مصلحة مؤثرة في البنك.\nو- إذا تم دمج البنك في بنك آخر أو تم بيع كل موجوداته أو معظمها.","title":"إلغاء ترخيص البنك","memo":"⭐ حالات الإلغاء: معلومات غير صحيحة، عدم البدء خلال ١٢ شهراً من الترخيص النهائي أو التوقف عن قبول الودائع، الامتناع عن تنفيذ إجراءات المادة (٨٨)، طلب البنك، إلغاء ترخيص بنك آخر له مصلحة مؤثرة فيه، الدمج أو بيع كل الموجودات أو معظمها\n⭐ طلب البنك إلغاء ترخيصه: يقرر البنك المركزي خلال ستين يوماً","qs":[{"q":"للبنك المركزي إلغاء ترخيص البنك إذا لم يبدأ بممارسة أعماله خلال:","o":["اثني عشر شهراً من تاريخ حصوله على الترخيص النهائي","ستة أشهر من تاريخ حصوله على الترخيص النهائي","ثلاثة أشهر من تاريخ حصوله على الترخيص النهائي","سنتين من تاريخ حصوله على الموافقة المبدئية"],"a":0},{"q":"إذا قدم البنك طلباً لإلغاء ترخيصه، فعلى البنك المركزي اتخاذ القرار المناسب بشأنه خلال:","o":["ستين يوماً من تاريخ تقديمه","ثلاثين يوماً من تاريخ تقديمه","ثلاثة أشهر من تاريخ تقديمه","سبعة أيام من تاريخ تقديمه"],"a":0},{"q":"أي مما يلي لا يعد من حالات إلغاء ترخيص البنك وفق المادة (١٨)؟","o":["تحقيق البنك خسائر في سنة مالية واحدة","دمج البنك في بنك آخر","إلغاء ترخيص بنك آخر له مصلحة مؤثرة في البنك","توقف البنك عن قبول الودائع بعد البدء بممارسة أعماله"],"a":0}]},{"n":"19","chapter":"ترخيص البنك","notes":[],"source":"للبنك المركزي على وجه الخصوص إلغاء ترخيص فرع البنك الأجنبي في أي من الحالات التالية:\nأ- إذا توقف البنك الأجنبي في مركزه الرئيسي عن ممارسة أعمال قبول الودائع.\nب- إذا طرأ أي تغيير على جنسية البنك الأجنبي أو على ملكيته أو على عقد تأسيسه أو نظامه الأساسي.\nج- إذا حصل ضعف في المركز المالي للبنك الأجنبي.\nد- إذا طرأ أي تغيير يرى البنك المركزي انه يؤثر سلباً في نشاط فرع البنك الأجنبي في المملكة وحسن سير أعماله.\nه- إذا ثبت أن السلطات المختصة في بلد مركزه الرئيسي لم تطبق الأسس السليمة في رقابة الأعمال المصرفية.","title":"إلغاء ترخيص فرع البنك الأجنبي","memo":"⭐ حالات خاصة: توقف المركز الرئيسي عن قبول الودائع، تغيير الجنسية أو الملكية أو عقد التأسيس أو النظام الأساسي، ضعف المركز المالي، تغيير يؤثر سلباً في نشاط الفرع، عدم تطبيق سلطات بلد المركز الرئيسي أسس الرقابة السليمة","qs":[{"q":"للبنك المركزي إلغاء ترخيص فرع البنك الأجنبي إذا:","o":["طرأ أي تغيير على جنسية البنك الأجنبي أو ملكيته","افتتح البنك الأجنبي فرعاً في دولة أخرى","عين مديراً إقليمياً جديداً لفروعه","انخفضت أرباح الفرع عن السنة السابقة"],"a":0},{"q":"أي مما يلي لا يعد من حالات إلغاء ترخيص فرع البنك الأجنبي وفق المادة (١٩)؟","o":["زيادة عدد فروع البنك الأجنبي في المملكة بموافقة البنك المركزي","توقف البنك الأجنبي في مركزه الرئيسي عن قبول الودائع","حصول ضعف في المركز المالي للبنك الأجنبي","ثبوت عدم تطبيق سلطات بلد المركز الرئيسي للأسس السليمة في الرقابة"],"a":0}]},{"n":"20","chapter":"ترخيص البنك","notes":[],"source":"يبلغ البنك المركزي البنك بإلغاء ترخيصه وينشر قرار الإلغاء خلال سبعة أيام من تاريخ صدوره في صحيفتين محليتين يوميتين على الأقل كما يتم نشره في الجريدة الرسمية.","title":"نشر قرار إلغاء الترخيص","memo":"⭐ يبلغ البنك بالإلغاء وينشر القرار خلال سبعة أيام من صدوره في صحيفتين محليتين يوميتين على الأقل وفي الجريدة الرسمية","qs":[{"q":"ينشر قرار إلغاء ترخيص البنك خلال:","o":["سبعة أيام من تاريخ صدوره في صحيفتين محليتين يوميتين على الأقل","ثلاثين يوماً من تاريخ صدوره في صحيفة محلية واحدة","خمسة عشر يوماً من تاريخ صدوره في ثلاث صحف محلية","ستين يوماً من تاريخ صدوره في الجريدة الرسمية فقط"],"a":0},{"q":"بالإضافة إلى الصحف المحلية اليومية، ينشر قرار إلغاء ترخيص البنك في:","o":["الجريدة الرسمية","الموقع الإلكتروني للبنك الملغى ترخيصه فقط","نشرة جمعية البنوك","سجل مراقبة الشركات فقط"],"a":0}]},{"n":"21","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"يكون مجلس إدارة البنك مسؤولاً عن وضع السياسات العامة للبنك وقواعد الحوكمة فيه وتطبيقها والإشراف عليه ويتمتع بالصلاحيات المنصوص عليها في قانون الشركات النافذ المفعول، ويتولى بشكل خاص المهام والصلاحيات التالية:\nأ- تحديد الأهداف واعتماد الخطط التي تلتزم الإدارة التنفيذية في البنك بالعمل بمقتضاها.\nب- اختيار الإدارة التنفيذية القادرة على إدارة شؤون البنك بكفاءة وفعالية.\nج- اعتماد سياسة ائتمانية واستثمارية مكتوبة تحدد أسس وشروط منح التسهيلات الائتمانية وأسس الاستثمار، على أن يتم تزويد البنك المركزي بنسخة منها وبأي تعديلات تطرأ عليها.\nد- مراقبة تنفيذ سياسات البنك والتأكد من صحة الإجراءات المتبعة لتحقيق ذلك.\nه- التأكد من عدم تحقيق أي عضو في مجلس إدارة البنك أو أي موظف في إدارته العليا أي منفعة ذاتية على حساب مصالح البنك.\nو- اتخاذ الخطوات الكفيلة لتأمين دقة المعلومات التي يزود بها البنك المركزي بمقتضى قانونه وبموجب أحكام هذا القانون والأنظمة والأوامر الصادرة بمقتضاه.\nز- تشكيل لجنة أو أكثر من بين أعضائه وتحديد مهامها وإجراءات عملها.\nح- وضع أسس صرف أي مكافآت أو بدلات لأعضاء مجلس إدارة البنك ولأي لجنة تتشكل من أعضائه وفق التعليمات التي يصدرها البنك المركزي.\nط- اتخاذ جميع الإجراءات الكفيلة بالتقيد بأحكام هذا القانون وأي تشريعات أخرى ذات علاقة بأعمال البنك وأنشطته.\nي- وضع الأنظمة والتعليمات الداخلية للبنك التي تحدد مهام أجهزته المختلفة وصلاحياتها التي تكفل تحقيق الرقابة الإدارية والمالية على أعماله.","title":"مهام مجلس إدارة البنك","memo":"⭐ المجلس مسؤول عن السياسات العامة وقواعد الحوكمة والإشراف، ويتمتع بصلاحيات قانون الشركات\n⭐ يعتمد سياسة ائتمانية واستثمارية مكتوبة ويزود البنك المركزي بنسخة منها وبتعديلاتها\n⭐ يضع أسس صرف المكافآت والبدلات للأعضاء وفق تعليمات البنك المركزي ويشكل لجاناً من بين أعضائه","qs":[{"q":"يعتمد مجلس إدارة البنك سياسة ائتمانية واستثمارية مكتوبة، على أن يزود بنسخة منها وبأي تعديلات عليها:","o":["البنك المركزي","الهيئة العامة للمساهمين","مراقب عام الشركات","هيئة الأوراق المالية"],"a":0},{"q":"توضع أسس صرف المكافآت والبدلات لأعضاء مجلس إدارة البنك ولجانه من قبل مجلس الإدارة وفق:","o":["التعليمات التي يصدرها البنك المركزي","قرار الهيئة العامة غير العادية","نظام يصدره مجلس الوزراء","توصية المدير العام"],"a":0},{"q":"أي مما يلي لا يعد من مهام مجلس إدارة البنك وفق المادة (٢١)؟","o":["منح الترخيص لفروع البنك الجديدة","اختيار الإدارة التنفيذية القادرة على إدارة شؤون البنك","تشكيل لجنة أو أكثر من بين أعضائه","التأكد من عدم تحقيق أي عضو منفعة ذاتية على حساب مصالح البنك"],"a":0}]},{"n":"22","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- على الرغم مما ورد في قانون الشركات يحدد البنك المركزي عدد أعضاء مجلس إدارة البنك بما لا يقل عن سبعة أعضاء وعدد الأعضاء المستقلين منهم على أن لا يزيد عددهم عن نصف عدد أعضاء مجلس الإدارة.\nب- يجب أن تتوافر فيمن يشغل رئاسة أو عضوية مجلس إدارة البنك – إضافة إلى ما هو منصوص عليه في قانون الشركات – الشروط الخاصة التالية:\n١- أن لا يقل عمره عن خمس وعشرين سنة .\n٢- أن يكون حسن السيرة والسمعة.\n٣- أن لا يكون عضواً في مجلس إدارة أي بنك آخر أو مديراً عاماً له أو مديراً إقليمياً أو موظفاً فيه ما لم يكن البنك الآخر تابعاً لذلك البنك.\n٤-إضافة إلى ما ورد في الفقرة (أ) يجوز للبنك المركزي أن يحدد المؤهلات والخبرات والشروط الواجب توافرها في الرئيس أو عضو مجلس إدارة البنك ومدى ملاءمة الأعضاء لهذه الشروط.\nج- لا يجوز لرئيس أو عضو مجلس إدارة البنك الجمع بين منصبه وأي موقع إداري أو تنفيذي أو استشاري في البنك.","title":"تشكيل مجلس إدارة البنك وشروط العضوية","memo":"⭐ البنك المركزي يحدد عدد الأعضاء بما لا يقل عن سبعة، والمستقلين بما لا يزيد عن النصف\n⭐ العمر لا يقل عن ٢٥ سنة، حسن السيرة، ألا يكون عضواً أو مديراً أو موظفاً في بنك آخر ما لم يكن تابعاً\n⭐ لا يجمع الرئيس أو العضو بين منصبه وأي موقع إداري أو تنفيذي أو استشاري في البنك","qs":[{"q":"لا يجوز أن يقل عدد أعضاء مجلس إدارة البنك عن:","o":["سبعة أعضاء","خمسة أعضاء","تسعة أعضاء","ثلاثة أعضاء"],"a":0},{"q":"يشترط فيمن يشغل رئاسة أو عضوية مجلس إدارة البنك ألا يقل عمره عن:","o":["خمس وعشرين سنة","ثماني عشرة سنة","ثلاثين سنة","إحدى وعشرين سنة"],"a":0},{"q":"يحدد عدد الأعضاء المستقلين في مجلس إدارة البنك على ألا يزيد عددهم عن:","o":["نصف عدد أعضاء مجلس الإدارة","ثلث عدد أعضاء مجلس الإدارة","ربع عدد أعضاء مجلس الإدارة","ثلثي عدد أعضاء مجلس الإدارة"],"a":0},{"q":"عضو في مجلس إدارة بنك (أ) يرغب أن يكون عضواً في مجلس إدارة بنك (ب). وفقاً لقانون البنوك يجوز له ذلك إذا:","o":["كان البنك (ب) تابعاً للبنك (أ)","حصل على موافقة الهيئة العامة للبنك (ب)","كان عضواً مستقلاً في البنك (أ)","لم يتجاوز عمره خمساً وعشرين سنة"],"a":0}]},{"n":"23","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"يفقد عضو مجلس إدارة البنك عضويته بقرار يتخذه البنك المركزي وذلك في أي من الحالات التالية:\nأ- إذا فقد أي شرط من الشروط الواجب توافرها في عضويته وفقا لأحكام قانون الشركات النافذ المفعول وأحكام هذا القانون.\nب- إذا طلب المجلس تنحية رئيس أو أي من أعضاء مجلس إدارة البنك إذا توفر أسباب مبررة لذلك تستدعيها مصلحة المودعين أو المساهمين.","title":"فقدان عضوية مجلس إدارة البنك","memo":"⭐ يفقد العضو عضويته بقرار من البنك المركزي إذا: فقد أي شرط من شروط العضوية، أو طلب المجلس تنحيته لأسباب مبررة تستدعيها مصلحة المودعين أو المساهمين","qs":[{"q":"يفقد عضو مجلس إدارة البنك عضويته في الحالات المحددة بالمادة (٢٣) بقرار من:","o":["البنك المركزي","الهيئة العامة للبنك","مجلس إدارة البنك نفسه","المحكمة المختصة"],"a":0},{"q":"يجوز للمجلس طلب تنحية رئيس أو أي من أعضاء مجلس إدارة البنك إذا توفرت أسباب مبررة تستدعيها:","o":["مصلحة المودعين أو المساهمين","مصلحة الإدارة التنفيذية","مصلحة الحليف","مصلحة المدقق الخارجي"],"a":0}]},{"n":"24","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"لا يجوز لمن فقد عضويته في مجلس إدارة البنك لأي سبب من الأسباب الواردة في المادة (٢٣) من هذا القانون أن يكون عضواً في مجلس إدارة أي بنك أو أن يعمل فيه دون الحصول على موافقة خطية مسبقة من المجلس.","title":"حظر عمل من فقد العضوية","memo":"⭐ من فقد عضويته وفق المادة (٢٣) لا يكون عضواً في مجلس إدارة أي بنك أو يعمل فيه إلا بموافقة خطية مسبقة من المجلس","qs":[{"q":"لا يجوز لمن فقد عضويته في مجلس إدارة البنك وفق المادة (٢٣) أن يعمل في أي بنك دون الحصول على:","o":["موافقة خطية مسبقة من المجلس","موافقة الهيئة العامة للبنك الجديد","قرار من المحكمة المختصة","موافقة المدير العام للبنك الجديد"],"a":0},{"q":"عضو فقد عضويته في مجلس إدارة بنك لفقده أحد شروط العضوية، ثم رُشّح لعضوية مجلس إدارة بنك آخر. وفقاً لقانون البنوك:","o":["لا يجوز له ذلك دون موافقة خطية مسبقة من المجلس","يجوز له ذلك دون أي قيد","يحظر عليه ذلك نهائياً","يجوز له ذلك بموافقة الهيئة العامة للبنك الآخر فقط"],"a":0}]},{"n":"25","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- يشترط فيمن يعين مديراً عاماً للبنك أو يعين في أحد مراكزه العليا التي يحددها البنك المركزي طيلة مدة عمله ما يلي:\n١- أن يكون حسن السيرة والسمعة.\n٢- أن لا يكون عضواً في مجلس إدارة أي بنك آخر إلا إذا كان البنك الآخر تابعاً للبنك الذي يعين فيه.\n٣- أن يكون متفرغاً لإدارة أعمال البنك.\n٤- أن يتمتع بالكفاءة والخبرة المصرفية التي تتطلبها أعمال البنك.\n٥- أن لا يشكل تعيينه تضارب مصالح ناشئاً عن صلة مع رئيس مجلس الإدارة او أي عضو فيه أو أي مساهم رئيسي بما في ذلك صلة القرابة حتى الدرجة الثالثة في حالة المدير العام وحتى الدرجة الأولى في حالة شاغلي المراكز العليا.\nب- للبنك المركزي أن يعترض على أي من التعيينات المشار إليها في الفقرة (أ) من هذه المادة إذا وجد أنها لم تحقق أياً من شروط التعيين الواردة فيها.","title":"شروط تعيين المدير العام وشاغلي المراكز العليا","memo":"⭐ حسن السيرة، عدم العضوية في مجلس بنك آخر إلا إذا كان تابعاً، التفرغ، الكفاءة والخبرة المصرفية\n⭐ عدم تضارب المصالح: صلة القرابة حتى الدرجة الثالثة للمدير العام، وحتى الدرجة الأولى لشاغلي المراكز العليا\n⭐ للبنك المركزي الاعتراض على التعيين","qs":[{"q":"يشترط ألا يشكل تعيين المدير العام تضارب مصالح ناشئاً عن صلة قرابة مع رئيس مجلس الإدارة أو أي عضو فيه أو أي مساهم رئيسي حتى:","o":["الدرجة الثالثة","الدرجة الأولى","الدرجة الثانية","الدرجة الرابعة"],"a":0},{"q":"بالنسبة لشاغلي المراكز العليا في البنك، يمتد شرط عدم وجود صلة قرابة مع رئيس أو أعضاء مجلس الإدارة أو المساهم الرئيسي حتى:","o":["الدرجة الأولى","الدرجة الثالثة","الدرجة الثانية","الدرجة الرابعة"],"a":0},{"q":"الجهة التي لها أن تعترض على تعيين المدير العام للبنك إذا لم تتحقق شروط التعيين هي:","o":["البنك المركزي","الهيئة العامة للبنك","مراقب عام الشركات","وزير المالية"],"a":0}]},{"n":"26","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"يلتزم مدير عام البنك بما يلي:\nأ- تحقيق الرقابة الداخلية على سير العمل في البنك وتقيده بالقوانين والأنظمة والتعليمات المعمول بها.\nب- تزويد مجلس إدارة البنك بشكل دوري بتقرير عن أوضاع البنك والتأكد من أن جميع أعماله تسير طبقا للسياسة التي يضعها مجلس الإدارة والتوصية له بأي مقترحات يراها ضرورية لتطوير عمل البنك.\nج- تزويد البنك المركزي بالمعلومات والبيانات التي يطلبها طبقا لأحكام هذا القانون والأنظمة والأوامر الصادرة بمقتضاه.","title":"التزامات مدير عام البنك","memo":"⭐ تحقيق الرقابة الداخلية والتقيد بالقوانين\n⭐ تزويد مجلس الإدارة دورياً بتقرير عن أوضاع البنك والتوصية بمقترحات التطوير\n⭐ تزويد البنك المركزي بالمعلومات والبيانات التي يطلبها","qs":[{"q":"يلتزم مدير عام البنك بتزويد مجلس إدارة البنك:","o":["بشكل دوري بتقرير عن أوضاع البنك","بتقرير سنوي واحد فقط","بتقرير عند طلب البنك المركزي فقط","بتقرير كل خمس سنوات"],"a":0},{"q":"أي مما يلي لا يعد من التزامات مدير عام البنك وفق المادة (٢٦)؟","o":["تعيين أعضاء لجنة التدقيق","تحقيق الرقابة الداخلية على سير العمل في البنك","تزويد البنك المركزي بالمعلومات والبيانات التي يطلبها","التوصية لمجلس الإدارة بالمقترحات اللازمة لتطوير عمل البنك"],"a":0}]},{"n":"27","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"إذا صدر قرار بإلغاء ترخيص بنك أو تصفية أعماله لا يجوز لمن كان عضواً في مجلس إدارته أو مديراً عاماً له أن يعمل في بنك آخر دون موافقة خطية مسبقة من المجلس.","title":"عمل الإداريين بعد إلغاء الترخيص أو التصفية","memo":"⭐ عند إلغاء ترخيص بنك أو تصفيته: لا يعمل عضو مجلس إدارته أو مديره العام في بنك آخر إلا بموافقة خطية مسبقة من المجلس","qs":[{"q":"إذا صدر قرار بإلغاء ترخيص بنك، فلا يجوز لمن كان مديراً عاماً له أن يعمل في بنك آخر دون:","o":["موافقة خطية مسبقة من المجلس","مرور سنتين على قرار الإلغاء","موافقة الهيئة العامة للبنك الآخر","حكم قضائي ببراءة ذمته"],"a":0},{"q":"يسري حظر العمل في بنك آخر دون موافقة المجلس وفق المادة (٢٧) على:","o":["أعضاء مجلس الإدارة والمدير العام للبنك الملغى ترخيصه أو المصفى","جميع موظفي البنك الملغى ترخيصه","مساهمي البنك الملغى ترخيصه","مدققي حسابات البنك الملغى ترخيصه"],"a":0}]},{"n":"28","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"مع مراعاة أحكام تشريعات العمل، يتعين على البنك أن يحصل على موافقة البنك المركزي على استخدام أي موظف غير أردني، وللبنك المركزي تحديد عدد الموظفين غير الأردنيين أو نسبتهم لمجموع عدد موظفي البنك.","title":"استخدام الموظفين غير الأردنيين","memo":"⭐ مع مراعاة تشريعات العمل: موافقة البنك المركزي على استخدام أي موظف غير أردني\n⭐ للبنك المركزي تحديد عدد غير الأردنيين أو نسبتهم","qs":[{"q":"يتعين على البنك أن يحصل على موافقة من أجل استخدام أي موظف غير أردني من:","o":["البنك المركزي","مجلس الوزراء","المجلس بناءً على تنسيب المدير العام","الهيئة العامة للبنك"],"a":0},{"q":"الجهة التي تحدد عدد الموظفين غير الأردنيين أو نسبتهم لمجموع موظفي البنك هي:","o":["البنك المركزي","وزير الداخلية","مجلس إدارة البنك","الهيئة العامة للبنك"],"a":0}]},{"n":"29","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"لا يجوز للبنك أن يستخدم شخصا كان موظفاً في البنك المركزي خلال السنتين التاليتين لتاريخ انتهاء خدمته إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"استخدام موظفي البنك المركزي السابقين","memo":"⭐ لا يستخدم البنك موظفاً سابقاً في البنك المركزي خلال السنتين التاليتين لانتهاء خدمته إلا بموافقة خطية مسبقة من البنك المركزي","qs":[{"q":"لا يجوز للبنك أن يستخدم شخصاً كان موظفاً في البنك المركزي دون موافقة خطية مسبقة من البنك المركزي خلال:","o":["السنتين التاليتين لتاريخ انتهاء خدمته","السنة التالية لتاريخ انتهاء خدمته","الأشهر الستة التالية لانتهاء خدمته","السنوات الخمس التالية لانتهاء خدمته"],"a":0},{"q":"موظف انتهت خدمته في البنك المركزي قبل ثمانية عشر شهراً، ويرغب بنك تجاري بتعيينه. وفقاً لقانون البنوك:","o":["يلزم الحصول على موافقة خطية مسبقة من البنك المركزي","يجوز تعيينه دون أي موافقة","يحظر تعيينه نهائياً","يلزم الحصول على موافقة مجلس الوزراء"],"a":0}]},{"n":"30","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- يفقد حكما أي إداري في البنك مركزه أو وظيفته إذا حكم عليه من محكمة مختصة بجناية أو بجنحة مخلة بالشرف أو الأمانة أو إذا أصدر شيكاً بدون رصيد.\nب- يفقد حكما عضو مجلس إدارة البنك أو مديره العام أو المدير مركزه أو وظيفته إذا لم يتمكن من الوفاء بالديون المستحقة عليه للبنك.\nج-لا يجوز لمن فقد مركزه أو وظيفته لأي سبب من الأسباب الواردة في الفقرة (أ) من هذه المادة أن يعمل في أي بنك أو أن يكون عضواً في مجلس إدارته.\nد- يجوز لمن فقد مركزه أو وظيفته لأي سبب من الأسباب الواردة في الفقرة (ب) من هذه المادة أن يعمل في أي بنك أو أن يكون عضواً في مجلس إدارته شريطة الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"فقدان الإداري لمركزه حكماً","memo":"⭐ يفقد الإداري مركزه حكماً إذا حكم عليه بجناية أو جنحة مخلة بالشرف أو الأمانة أو أصدر شيكاً بدون رصيد ← لا يعمل في أي بنك نهائياً\n⭐ عضو المجلس أو المدير العام أو المدير يفقد مركزه إذا لم يتمكن من الوفاء بديونه للبنك ← يجوز عمله بموافقة خطية مسبقة من البنك المركزي","qs":[{"q":"يفقد الإداري في البنك مركزه أو وظيفته حكماً إذا:","o":["أصدر شيكاً بدون رصيد","تأخر في تقديم تقريره الدوري","تجاوز سن الستين","رفض التصويت في اجتماع مجلس الإدارة"],"a":0},{"q":"مدير عام بنك فقد وظيفته لعدم تمكنه من الوفاء بالديون المستحقة عليه للبنك. وفقاً لقانون البنوك فإنه:","o":["يجوز له العمل في أي بنك بشرط الحصول على موافقة خطية مسبقة من البنك المركزي","لا يجوز له العمل في أي بنك مطلقاً","يجوز له العمل في أي بنك دون أي موافقة","يجوز له العمل بعد مرور سنتين فقط دون موافقة"],"a":0},{"q":"من فقد وظيفته في البنك بسبب الحكم عليه بجنحة مخلة بالأمانة:","o":["لا يجوز له أن يعمل في أي بنك أو أن يكون عضواً في مجلس إدارته","يجوز له العمل في بنك آخر بموافقة البنك المركزي","يجوز له العمل في بنك آخر بموافقة المجلس","يجوز له العمل في فرع بنك أجنبي فقط"],"a":0}]},{"n":"31","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- إذا كان للإداري في البنك أو لزوجه أو لقريب له حتى الدرجة الثالثة مصلحة شخصية في أي تعامل أو تعاقد يكون البنك طرفا فيه أو إذا كان لأي منهم مصلحة مؤثرة في شركة يتعلق بها ذلك التعامل أو التعاقد، فعلى هذا الإداري أن يفصح عن هذه المصلحة خطيا وان لا يشارك في أي اجتماع يتم فيه بحث ذلك التعامل أو التعاقد.\nب- إذا لم يفصح الإداري في البنك خطيا عن مصلحته خلافا لأحكام الفقرة (أ) من هذه المادة، فعلى البنك أن يلجأ إلى المحكمة المختصة بمبادرة منه أو بناء على طلب البنك المركزي للطعن في صحة ذلك العقد إذا تضمن شروطا تضر بمصلحة البنك، وللمحكمة المختصة أن تفسخ العقد أو أن تعدل الشروط الواردة فيه بما يكفل تحقيق مصلحة البنك، كما يحق للبنك المركزي إصدار أمر خطي للبنك بإنهاء خدمته أو علاقته بالبنك.","title":"الإفصاح عن المصلحة الشخصية للإداري","memo":"⭐ إذا كان للإداري أو زوجه أو قريبه حتى الدرجة الثالثة مصلحة في تعامل مع البنك: يفصح خطياً ولا يشارك في الاجتماع\n⭐ عند عدم الإفصاح: يلجأ البنك للمحكمة (بمبادرته أو بطلب البنك المركزي) وللمحكمة فسخ العقد أو تعديل شروطه\n⭐ للبنك المركزي إصدار أمر خطي بإنهاء خدمة الإداري","qs":[{"q":"يلتزم الإداري بالإفصاح خطياً عن المصلحة الشخصية في تعامل يكون البنك طرفاً فيه إذا كانت هذه المصلحة له أو لزوجه أو لقريب له حتى:","o":["الدرجة الثالثة","الدرجة الأولى","الدرجة الثانية","الدرجة الرابعة"],"a":0},{"q":"إذا لم يفصح الإداري خطياً عن مصلحته في عقد تضمن شروطاً تضر بمصلحة البنك، فإن للمحكمة المختصة:","o":["فسخ العقد أو تعديل الشروط الواردة فيه بما يكفل مصلحة البنك","إلغاء ترخيص البنك","فرض غرامة على البنك فقط مع إبقاء العقد","الحكم بحبس الإداري وجوباً"],"a":0},{"q":"الجهة التي يحق لها إصدار أمر خطي للبنك بإنهاء خدمة الإداري الذي لم يفصح عن مصلحته هي:","o":["البنك المركزي","المحكمة المختصة","الهيئة العامة للبنك","مراقب عام الشركات"],"a":0}]},{"n":"32","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- تؤلف في كل بنك بقرار من مجلس إدارته لجنة تدقيق من رئيس وعضوين على الأقل على أن يكون الرئيس وعضو آخر على الأقل من الأعضاء المستقلين.\nب- لا يجوز أن يكون رئيس مجلس إدارة البنك رئيسا للجنة التدقيق المشار إليها في الفقرة (أ) من هذه المادة أو عضواً فيها.\nج- تستمر لجنة التدقيق في عملها باستمرار عضوية مجلس الإدارة.\nد- تعمل لجنة التدقيق بإشراف مجلس الإدارة وترفع إليه تقاريرها وتوصياتها بنتائج عملها.\nه-تتولى لجنة التدقيق ممارسة المهام والصلاحيات التالية:\n١- رقابة مدى شمولية التدقيق الخارجي لأعمال البنك والتحقق من وجود التنسيق بين أعمال مدققي الحسابات الخارجيين في حال وجود اكثر من مدقق.\n٢- مراجعة الملاحظات الواردة في تقارير البنك المركزي وتقارير المدقق الخارجي ومتابعة الإجراءات المتخذة بشأنها.\n٣- دراسة خطة التدقيق الداخلي السنوية ومراجعة الملاحظات الواردة في تقارير التفتيش وتقارير التدقيق الداخلي ومتابعة الإجراءات المتخذة بشأنها.\n٤- مراجعة البيانات المالية للبنك قبل عرضها على مجلس الإدارة بما في ذلك التحقق من أوامر البنك المركزي المتعلقة بكفاية المخصصات المأخوذة لمقابلة الديون المشكوك في تحصيلها ومخصصات محافظ الأوراق المالية وأي مخصصات لازمة وإبداء الرأي في ديون البنك غير العاملة، أو المقترح اعتبارها ديوناً هالكة.\n٥- التأكد من دقة الإجراءات المحاسبية والرقابية وسلامتها ومدى التقيد بها.\n٦- التأكد من التقيد بالقوانين والأنظمة والأوامر التي تخضع لها أعمال البنك.\n٧- دراسة أي مسألة تعرض عليها من مجلس إدارة البنك أو أي مسألة ترى اللجنة بحثها وإبداء الرأي بشأنها.","title":"لجنة التدقيق: تشكيلها ومهامها","memo":"⭐ تؤلف بقرار من مجلس الإدارة من رئيس وعضوين على الأقل، الرئيس وعضو آخر على الأقل مستقلان\n⭐ لا يجوز أن يكون رئيس مجلس الإدارة رئيساً لها أو عضواً فيها\n⭐ تعمل بإشراف مجلس الإدارة وتستمر باستمرار عضويته\n⭐ من مهامها مراجعة البيانات المالية قبل عرضها على المجلس ودراسة خطة التدقيق الداخلي السنوية","qs":[{"q":"تتألف لجنة التدقيق في البنك من:","o":["رئيس وعضوين على الأقل يكون الرئيس وعضو آخر على الأقل منهم مستقلين","رئيس وعضو واحد على الأقل من المستقلين","خمسة أعضاء جميعهم من المستقلين","رئيس مجلس الإدارة وعضوين مستقلين"],"a":0},{"q":"أي مما يلي لا يجوز أن يكون رئيساً للجنة التدقيق أو عضواً فيها؟","o":["رئيس مجلس إدارة البنك","عضو مستقل في مجلس إدارة البنك","عضو مجلس إدارة غير مستقل","عضو مجلس إدارة يمثل شخصاً اعتبارياً"],"a":0},{"q":"تعمل لجنة التدقيق في البنك بإشراف:","o":["مجلس إدارة البنك","البنك المركزي","المدير العام","الهيئة العامة للمساهمين"],"a":0},{"q":"من مهام لجنة التدقيق وفق المادة (٣٢):","o":["مراجعة البيانات المالية للبنك قبل عرضها على مجلس الإدارة","اختيار الإدارة التنفيذية للبنك","اعتماد السياسة الائتمانية والاستثمارية للبنك","منح الائتمان للإداريين"],"a":0}]},{"n":"33","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- تجتمع لجنة التدقيق مرة كل ثلاثة أشهر على الأقل وكلما دعت الحاجة بدعوة من رئيسها، ويكون اجتماعها قانونياً بحضور أغلبية أعضائها، وتتخذ توصياتها بأغلبية أصوات أعضائها.\nب- يتولى أمين سر مجلس إدارة البنك أمانة سر اللجنة.\nج- يدعى مدير دائرة التدقيق الداخلي في البنك لحضور اجتماعات اللجنة ولها أن تدعو أي شخص للاستئناس برأيه بخصوص مسألة معينة.\nد- لغايات هذه المادة، يصدر البنك المركزي أوامر خاصة لتنظيم أعمال لجنة التدقيق في البنك الأجنبي أو أي ممثلين لها وبما يمكنها من ممارسة الأعمال والصلاحيات المشار إليها في الفقرة (أ) من المادة (٣٢) من هذا القانون على فرعها أو فروعها العاملة في المملكة.","title":"اجتماعات لجنة التدقيق","memo":"⭐ تجتمع مرة كل ثلاثة أشهر على الأقل بدعوة من رئيسها\n⭐ النصاب: أغلبية الأعضاء، والتوصيات بأغلبية أصوات الأعضاء\n⭐ أمين سر مجلس الإدارة يتولى أمانة سرها، ويدعى مدير دائرة التدقيق الداخلي لحضور اجتماعاتها","qs":[{"q":"تجتمع لجنة التدقيق في البنك على الأقل مرة كل:","o":["ثلاثة أشهر","شهر","ستة أشهر","سنة"],"a":0},{"q":"يتولى أمانة سر لجنة التدقيق في البنك:","o":["أمين سر مجلس إدارة البنك","مدير دائرة التدقيق الداخلي","المدير المالي للبنك","مندوب البنك المركزي"],"a":0},{"q":"يدعى لحضور اجتماعات لجنة التدقيق بحكم القانون:","o":["مدير دائرة التدقيق الداخلي في البنك","المدقق الخارجي للبنك","رئيس مجلس إدارة البنك","مندوب عن المساهمين الرئيسيين"],"a":0}]},{"n":"34","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- لا يجوز دون موافقة خطية مسبقة من البنك المركزي إجراء أي تغيير في ملكية البنك أو تحويل في أسهمه سواء تم ذلك بعملية واحدة أو بعمليات عدة وبشكل مباشر أو غير مباشر إذا أدى هذا التحويل إلى ملكية شخص لمصلحة مؤثرة في رأسمال البنك أو أدى إلى زيادة نسبة هذه المصلحة.\nب- يسري حكم الفقرة (أ) من هذه المادة إذا كان تحويل الأسهم أو التغيير في الملكية عائداً لمجموعة أشخاص من ذوي الصلة أو بينهم صلة قرابة حتى الدرجة الثالثة.\nج- إذا جرى اتفاق أو تعهد بتحويل أسهم بنك أو بإجراء تغيير في ملكيته خلافاً لأحكام الفقرة (أ) من هذه المادة فلا يجوز تنفيذ هذا الاتفاق أو التعهد لدى السلطات المختصة أو قيده في سجلاتها.\nد- إذا تم فعلاً تحويل الأسهم أو التغيير في الملكية خلافاً لأحكام الفقرات السابقة من هذه المادة فيراعى ما يلي:\n١- لا يحق لمالك الأسهم أو لمن جرى التغيير في الملكية لمصلحته أن يقبض أي أرباح أو تتأتى له أي منافع نتيجة لهذه المساهمة أو التغيير في الملكية، كما لا يحق له التصويت سواء أصالة أو وكالة في اجتماعات الهيئة العامة للبنك أو الترشح لعضوية مجلس إدارة البنك بأي صورة كانت.\n٢- لا يحق لمالك الأسهم أو لمن جرى التغيير في الملكية لمصلحته التصرف في تلك الأسهم أو الملكية أو في جزء منها سواء كان ذلك بيعاً او رهناً او خلافه دون الحصول على موافقة خطية مسبقة من البنك المركزي وللبنك المركزي وضع قيد منع التصرف في الملكية أو الأسهم.\nه- للبنك المركزي أن يصدر ولأسباب مبررة موافقة لاحقة على تحويل الأسهم أو تغيير الملكية الذي تم خلافاً لأحكام الفقرة (أ) من هذه المادة.","title":"تغيير ملكية البنك وتحويل أسهمه","memo":"⭐ موافقة خطية مسبقة من البنك المركزي لأي تحويل يؤدي لملكية مصلحة مؤثرة أو زيادة نسبتها (مباشرة أو غير مباشرة، بعملية أو عدة عمليات)\n⭐ يسري على ذوي الصلة أو الأقارب حتى الدرجة الثالثة\n⭐ عند المخالفة: لا أرباح ولا تصويت ولا ترشح ولا تصرف دون موافقة؛ وللبنك المركزي إصدار موافقة لاحقة لأسباب مبررة","qs":[{"q":"يحتاج تحويل أسهم البنك إلى موافقة خطية مسبقة من البنك المركزي إذا أدى إلى:","o":["ملكية شخص لمصلحة مؤثرة في رأسمال البنك أو زيادة نسبتها","ملكية شخص لأي عدد من أسهم البنك","انخفاض ملكية المساهم الرئيسي","ملكية شخص لما لا يقل عن (%١) من رأسمال البنك"],"a":0},{"q":"شخص تملّك مصلحة مؤثرة في رأسمال بنك دون موافقة البنك المركزي. أي مما يلي يترتب على ذلك؟","o":["لا يحق له قبض أي أرباح أو التصويت في اجتماعات الهيئة العامة","يعتبر التملك باطلاً بطلاناً مطلقاً ولا يجوز تصحيحه","يحق له الترشح لعضوية مجلس الإدارة دون التصويت","تفرض عليه غرامة ويبقى له حق قبض الأرباح"],"a":0},{"q":"يجوز للبنك المركزي بشأن تحويل الأسهم الذي تم خلافاً لأحكام المادة (٣٤):","o":["أن يصدر ولأسباب مبررة موافقة لاحقة عليه","أن يلغي ترخيص البنك حكماً","أن يصادر الأسهم لصالح الخزينة","أن يبيع الأسهم في السوق دون الرجوع للمالك"],"a":0}]},{"n":"35","chapter":"إدارة البنك وتنظيمه","notes":[],"source":"أ- يحدد المحافظ، بعد الاستئناس برأي البنوك العاملة في المملكة، أيام العطل الأسبوعية وساعات الدوام اليومية.\nب- للمحافظ في الحالات الطارئة والمناسبات الخاصة أن يعلن تعطيل البنوك بجميع فروعها أو أي منها للمدة التي يحددها.","title":"أيام العطل وساعات الدوام","memo":"⭐ المحافظ يحدد أيام العطل الأسبوعية وساعات الدوام بعد الاستئناس برأي البنوك\n⭐ للمحافظ في الحالات الطارئة والمناسبات الخاصة إعلان تعطيل البنوك للمدة التي يحددها","qs":[{"q":"يحدد أيام العطل الأسبوعية وساعات الدوام اليومية للبنوك:","o":["المحافظ بعد الاستئناس برأي البنوك العاملة في المملكة","مجلس الوزراء بتنسيب المحافظ","جمعية البنوك","مجلس إدارة كل بنك"],"a":0},{"q":"في الحالات الطارئة والمناسبات الخاصة، الجهة التي لها إعلان تعطيل البنوك بجميع فروعها أو أي منها هي:","o":["المحافظ","رئيس الوزراء","المجلس","وزير المالية"],"a":0}]},{"n":"36","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- يجب أن يحتفظ البنك بشكل دائم بالحد الأدنى لرأس المال التنظيمي الذي يحدده البنك المركزي من وقت لآخر .\nب- على البنك أن يحتفظ بسيولة كافية لتلبية متطلبات عمله، وان يراعي تنوع موجوداته من اجل تقليل مخاطره وأن يمارس أعماله وفق أساليب الإدارة والمحاسبة السليمة وبما ينسجم مع متطلبات هذا القانون والأنظمة والأوامر الصادرة بمقتضاه. .","title":"رأس المال التنظيمي والسيولة","memo":"⭐ يحتفظ البنك بشكل دائم بالحد الأدنى لرأس المال التنظيمي الذي يحدده البنك المركزي\n⭐ سيولة كافية، تنوع الموجودات لتقليل المخاطر، أساليب إدارة ومحاسبة سليمة","qs":[{"q":"يحدد الحد الأدنى لرأس المال التنظيمي الذي يجب أن يحتفظ به البنك بشكل دائم من قبل:","o":["البنك المركزي من وقت لآخر","الهيئة العامة للبنك","مجلس الوزراء","قانون الشركات"],"a":0},{"q":"يلزم البنك بمراعاة تنوع موجوداته من أجل:","o":["تقليل مخاطره","زيادة رأسماله المصرح به","تخفيض الضرائب المستحقة عليه","زيادة عدد فروعه"],"a":0}]},{"n":"37","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- يمارس البنك وفقا لترخيصه من البنك المركزي الأنشطة المالية التالية:-\n١- قبول الودائع بمختلف أشكالها.\n٢- منح الائتمان بجميع أنواعه بما في ذلك تمويل العمليات التجارية.\n٣- تقديم خدمات الدفع والتحصيل.\n٤- إصدار أدوات الدفع بما في ذلك السحوبات البنكية وبطاقات الدفع والائتمان والشيكات السياحية وإدارتها.\n٥- التعامل بأدوات السوق النقدي وبأدوات سوق رأس المال بيعاً وشراءً سواءً لحسابه أو لحساب عملائه.\n٦- شراء الديون وبيعها سواء بحق الرجوع أو بدونه.\n٧- التمويل بطريقة التأجير.\n٨- التعامل بالعملات الأجنبية في أسواق الصرف الآنية والآجلة.\n٩- إدارة إصدارات الأوراق المالية أو التعهد بتغطيتها وتوزيعها والتعامل بها.\n١٠- تقديم الخدمات الإدارية والاستشارية للمحافظ الاستثمارية وتقديم خدمات أمين الاستثمار، ويشمل ذلك إدارة الأموال واستثمارها لحساب الغير.\n١١- عمليات الإدارة والحفظ الأمين للأوراق المالية والأشياء الثمينة.\n١٢- تقديم خدمات الوكيل او المستشار المالي.\n١٣- أي أنشطة أخرى تتعلق بأعمال البنوك يوافق عليها البنك المركزي بموجب أوامر خاصة يصدرها لهذه الغاية.\nب- يجوز أن يكون للبنك شركة أو شركات تابعة له تتولى ممارسة أي من الأنشطة المالية غير المصرفية وذلك بموافقة خطية من البنك المركزي.","title":"الأنشطة المالية المسموح بها للبنك","memo":"⭐ من الأنشطة: قبول الودائع، منح الائتمان، خدمات الدفع والتحصيل، إصدار أدوات الدفع، شراء الديون وبيعها بحق الرجوع أو بدونه، التأجير التمويلي، العملات الأجنبية الآنية والآجلة، إدارة الإصدارات، أمين الاستثمار، الحفظ الأمين\n⭐ للبنك شركات تابعة لأنشطة مالية غير مصرفية بموافقة خطية من البنك المركزي","qs":[{"q":"يجوز للبنك شراء الديون وبيعها:","o":["سواء بحق الرجوع أو بدونه","بحق الرجوع فقط","بدون حق الرجوع فقط","بموافقة مجلس الوزراء فقط"],"a":0},{"q":"يجوز أن يكون للبنك شركات تابعة تتولى ممارسة أنشطة مالية غير مصرفية بشرط:","o":["موافقة خطية من البنك المركزي","موافقة هيئة الأوراق المالية فقط","ألا تتجاوز ملكيته فيها (%١٠)","موافقة مجلس الوزراء"],"a":0},{"q":"أي مما يلي لا يعد من الأنشطة المالية التي يمارسها البنك وفقاً لترخيصه بموجب المادة (٣٧)؟","o":["ممارسة التجارة في السلع","التمويل بطريقة التأجير","التعامل بالعملات الأجنبية في أسواق الصرف الآنية والآجلة","عمليات الحفظ الأمين للأوراق المالية والأشياء الثمينة"],"a":0}]},{"n":"38","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- يحظر على البنك سواء وحده أو بالاتفاق مع غيره، وبشكل مباشر أو غير مباشر ما يلي:-\n١- أن تزيد ملكيته في أي شركة من الشركات التي ليس من غاياتها قبول الودائع على النسبة التي يقررها البنك المركزي على أن لا تتجاوز في أي حال (%١٠) من رأسمالها المكتتب به، وللبنك المركزي الموافقة على أن تصل هذه النسبة إلى (%٢٠) حداً أعلى من رأس المال المكتتب به في الأنشطة التي يحددها البنك المركزي بموجب أوامر خاصة تصدر لهذه الغاية.\n٢- أن يملك أسهماً دون موافقة خطية مسبقة من البنك المركزي في أي بنك آخر أو شركة تقبل الودائع على أن لا تتجاوز هذه الملكية في أي حال (%١٠) من رأسماله المكتتب به أومن رأس المال المكتتب به للبنك أو الشركة التي يملك أسهماً في أي منهما، ولا ينطبق هذا الحظر على الأسهم نفسها التي تملكها البنوك زيادة على تلك النسبة عند نفاذ هذا القانون.\n٣- أ) أن يتجاوز مجموع ملكية البنك في رأسمال جميع الشركات النسبة التي يقررها البنك المركزي شريطة أن لا تتجاوز هذه النسبة في جميع الأحوال (%٥٠) من رأسماله المكتتب به ويمنح البنك المتجاوز لهذه النسبة مدة خمس سنوات من تاريخ نفاذ أحكام هذا القانون لتصحيح أوضاعه.\nب) اذا بلغت مساهمة أي بنك في رأسمال جميع الشركات نسبة (%٥٠) من رأسماله المكتتب به يجوز لمحافظ البنك المركزي السماح لذلك البنك بزيادة مساهمته في رأسمال الشركات إلى نسبة لا تتجاوز في جميع الأحوال (%٥٠) من رأس المال التنظيمي للبنك.\nب- لا يدخل في احتساب النسب المشار إليها في الفقرة (أ) من هذه المادة ما يلي:\n١-ما يمتلكه البنك من أسهم وحصص سداداً لدين له على أن يتخلص من هذا التملك خلال سنتين من تاريخ اكتسابه الملكية وللبنك المركزي في حالات استثنائية أن يمدد هذه المدة لسنتين متتاليتين حدا أقصى.\n٢-ما يسجل باسم البنك من أوراق مالية إذا كانت ملكيتها عائدة لعميل أو اكثر من عملائه وذلك مع مراعاة أي أوامر يصدرها البنك المركزي بهذا الخصوص، ولا تعتبر هذه الأوراق من موجودات البنك.\n٣-ما يمتلكه البنك، وفق أحكام هذا القانون، من أسهم وحصص في رأسمال أي شركة تابعة له إذا كانت بنكا أو شركة مالية.","title":"قيود ملكية البنك في الشركات","memo":"⭐ الشركات التي لا تقبل الودائع: لا تتجاوز (%١٠) من رأسمالها المكتتب به، ويجوز حتى (%٢٠) بموافقة البنك المركزي\n⭐ أسهم بنك آخر أو شركة تقبل الودائع: بموافقة خطية مسبقة ولا تتجاوز (%١٠)\n⭐ مجموع الملكية في جميع الشركات لا يتجاوز (%٥٠) من رأسماله المكتتب به؛ وللمحافظ السماح حتى (%٥٠) من رأس المال التنظيمي\n⭐ الأسهم المتملكة سداداً لدين: التخلص خلال سنتين، ويجوز التمديد لسنتين متتاليتين حداً أقصى","qs":[{"q":"لا يجوز أن تتجاوز ملكية البنك في أي شركة ليس من غاياتها قبول الودائع في أي حال نسبة (كأصل عام):","o":["(%١٠) من رأسمالها المكتتب به","(%٥) من رأسمالها المكتتب به","(%٢٠) من رأسمالها المكتتب به","(%٥٠) من رأسمالها المكتتب به"],"a":0},{"q":"للبنك المركزي الموافقة على أن تصل ملكية البنك في شركة لا تقبل الودائع، في الأنشطة التي يحددها، إلى حد أعلى قدره:","o":["(%٢٠) من رأس المال المكتتب به","(%١٥) من رأس المال المكتتب به","(%٢٥) من رأس المال المكتتب به","(%٤٠) من رأس المال المكتتب به"],"a":0},{"q":"لا يجوز أن يتجاوز مجموع ملكية البنك في رأسمال جميع الشركات في جميع الأحوال (كأصل عام):","o":["(%٥٠) من رأسماله المكتتب به","(%٢٠) من رأسماله المكتتب به","(%٢٥) من رأسماله المكتتب به","(%١٠٠) من رأسماله المكتتب به"],"a":0},{"q":"تملك بنك أسهماً في شركة سداداً لدين له. وفقاً للمادة (٣٨) فإن هذه الأسهم:","o":["لا تدخل في احتساب النسب على أن يتخلص منها خلال سنتين قابلة للتمديد لسنتين متتاليتين حداً أقصى","تدخل في احتساب النسب ويجب التخلص منها فوراً","لا تدخل في احتساب النسب ويجوز الاحتفاظ بها دون قيد زمني","لا تدخل في احتساب النسب على أن يتخلص منها خلال خمس سنوات"],"a":0}]},{"n":"39","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"مع مراعاة أحكام المادة (٣٨) من هذا القانون، يلتزم كل بنك يمتلك نسبة لا تقل عن (%٥) من الأسهم والحصص في رأسمال أي شركة بإخطار البنك المركزي عن هذا التملك خلال خمسة عشر يوما من تاريخ اكتسابه.","title":"الإخطار عن تملك الأسهم","memo":"⭐ البنك الذي يمتلك ما لا يقل عن (%٥) من أسهم أو حصص أي شركة يخطر البنك المركزي خلال خمسة عشر يوماً من تاريخ الاكتساب","qs":[{"q":"يلتزم البنك بإخطار البنك المركزي عن تملكه نسبة لا تقل عن (%٥) من رأسمال أي شركة خلال:","o":["خمسة عشر يوماً من تاريخ اكتسابه","سبعة أيام من تاريخ اكتسابه","ثلاثين يوماً من تاريخ اكتسابه","ستين يوماً من تاريخ اكتسابه"],"a":0},{"q":"تنشأ على البنك إلزامية إخطار البنك المركزي عن تملك أسهم أو حصص في رأسمال أي شركة إذا بلغت النسبة ما لا يقل عن:","o":["(%٥)","(%١٠)","(%٢٠)","(%٤٠)"],"a":0}]},{"n":"40","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- يحظر على البنك أي من الممارسات التالية:-\n١- الاشتراك مع آخرين بقصد تحقيق سيطرة في الأسواق المالية أو النقدية أو أسواق العملات الأجنبية.\n٢- ممارسة الصناعة أو التجارة أو الخدمات فيما عدا الأنشطة المالية.\n٣- الطلب من أي شخص التعاقد مع حليف له كشرط للحصول منه على خدمات مالية من أي نوع كانت.\n٤- منح ائتمان إلى أي شخص يزيد عن الحد المقرر من البنك المركزي أو ترتيب تمويل لهذا الشخص من طرف ثالث بقصد تمكين هذا الشخص من دفع التزاماته إلى حليف للبنك\n٥- التعهد بتغطية أوراق مالية أو طرحها بقصد تمكين شخص من تسديد التزاماته إلى حليف للبنك.\n٦- منح ائتمان إلى أي شخص بقصد تمكين ذلك الشخص من دفع قيمة أوراقه المالية أو أي فوائد أو عوائد مترتبة عليها إذا تم التعهد بتغطية تلك الأوراق المالية أو طرحها من البنك أو حليف له.\n٧- القيام بصفته مدير استثمار أو مستشاراً مالياً بشراء أوراق مالية أو التوصية بشرائها خلال ستين يوماً من تاريخ الاكتتاب بها إذا تم التعهد بتغطية تلك الاوراق المالية أو طرحها أو توزيعها من البنك أو حليف له.\n٨- منح ائتمان إلى شخص أو زيادة مقدار الائتمان الممنوح له أصلا لتمكينه من شراء أوراق مالية تم التعهد بتغطيتها أو طرحها أو توزيعها من البنك أو حليف له.\n٩- منح قروض لإنشاء العقارات أو شرائها إذا كانت تزيد في مجموعها على (%٢٠) من إجمالي ودائع البنك بالدينار الأردني.\n١٠- منح أي ائتمان إلى عميل له بضمان أسهمه في البنك.\nب- يمتنع على البنك دون موافقة خطية مسبقة من البنك المركزي أن يشتري من حليف له ما يلي:\n١- أياً من موجودات الحليف.\n٢- أي أوراق مالية سيتم تغطيتها أو طرحها أو توزيعها من الحليف.\n٣- أي أوراق مالية سبق تغطيتها أو طرحها أو توزيعها من الحليف خلال الاثني عشر شهرا السابقة لذلك.","title":"الممارسات المحظورة على البنك","memo":"⭐ يحظر: الاشتراك للسيطرة على الأسواق، ممارسة الصناعة أو التجارة أو الخدمات غير المالية، اشتراط التعاقد مع حليف، منح ائتمان بضمان أسهم العميل في البنك\n⭐ قروض إنشاء العقارات أو شرائها لا تزيد في مجموعها على (%٢٠) من إجمالي الودائع بالدينار\n⭐ حظر شراء أوراق مالية أو التوصية بها خلال ستين يوماً من الاكتتاب إذا غطاها البنك أو حليفه\n⭐ الشراء من الحليف (موجودات أو أوراق مالية غطاها خلال الـ١٢ شهراً السابقة) يحتاج موافقة خطية مسبقة","qs":[{"q":"يحظر على البنك منح قروض لإنشاء العقارات أو شرائها إذا كانت تزيد في مجموعها على:","o":["(%٢٠) من إجمالي ودائع البنك بالدينار الأردني","(%١٠) من إجمالي ودائع البنك بالدينار الأردني","(%٥٠) من رأسمال البنك المكتتب به","(%٢٠) من رأس المال التنظيمي للبنك"],"a":0},{"q":"تقدم عميل لبنك بطلب ائتمان وعرض أن يقدم أسهمه في البنك ذاته ضماناً له. وفقاً لقانون البنوك:","o":["يحظر على البنك منح هذا الائتمان","يجوز ذلك بموافقة خطية مسبقة من البنك المركزي","يجوز ذلك إذا كانت قيمة الأسهم تغطي الائتمان","يجوز ذلك إذا لم يكن العميل مساهماً رئيسياً"],"a":0},{"q":"يحظر على البنك بصفته مدير استثمار شراء أوراق مالية أو التوصية بشرائها إذا تعهد بتغطيتها البنك أو حليف له، وذلك خلال:","o":["ستين يوماً من تاريخ الاكتتاب بها","ثلاثين يوماً من تاريخ الاكتتاب بها","اثني عشر شهراً من تاريخ الاكتتاب بها","تسعين يوماً من تاريخ الاكتتاب بها"],"a":0},{"q":"يمتنع على البنك دون موافقة خطية مسبقة من البنك المركزي أن يشتري من حليف له أوراقاً مالية سبق تغطيتها أو طرحها من الحليف خلال:","o":["الاثني عشر شهراً السابقة","الستة أشهر السابقة","الستين يوماً السابقة","السنتين السابقتين"],"a":0}]},{"n":"41","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"على البنك التقيد بالحدود التي يقررها البنك المركزي المتعلقة بما يلي:-\nأ- نسب المخاطر الخاصة بموجوداته وبالموجودات المرجحة بالمخاطر وكذلك بعناصر رأس المال وبالاحتياطيات وبالحسابات النظامية.\nب- نسبة إجمالي الائتمان إلى رأس المال التنظيمي المسموح للبنك منحها لمصلحة شخص وحلفائه أو لمصلحة ذوي صلة.\nج- نسبة إجمالي الائتمان المباشر الممنوح لأكبر عشرة أشخاص من عملاء البنك إلى المبلغ الإجمالي للائتمان المباشر الممنوح من البنك.\nد- النسب والمعايير التي يقررها البنك المركزي بمقتضى أوامر يصدرها لهذه الغاية اللازمة للتحقق من قيام البنوك بالعمليات المصرفية بصورة آمنة وسليمة.","title":"الحدود والنسب الرقابية","memo":"⭐ يتقيد البنك بحدود البنك المركزي لـ: نسب المخاطر والموجودات المرجحة بالمخاطر، نسبة الائتمان إلى رأس المال التنظيمي لشخص وحلفائه أو ذوي الصلة، نسبة الائتمان المباشر لأكبر عشرة عملاء إلى إجمالي الائتمان المباشر","qs":[{"q":"يحدد البنك المركزي نسبة إجمالي الائتمان المباشر الممنوح لأكبر ... من عملاء البنك إلى المبلغ الإجمالي للائتمان المباشر:","o":["عشرة أشخاص","خمسة أشخاص","عشرين شخصاً","خمسين شخصاً"],"a":0},{"q":"تنسب الحدود التي يقررها البنك المركزي لإجمالي الائتمان الممنوح لمصلحة شخص وحلفائه أو لمصلحة ذوي صلة إلى:","o":["رأس المال التنظيمي","رأس المال المصرح به","إجمالي الودائع بالدينار","إجمالي الموجودات السائلة"],"a":0}]},{"n":"42","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- على البنك التقيد بأوامر البنك المركزي المتعلقة بما يلي:\n١- الحد الأدنى لإجمالي الموجودات السائلة التي يحددها البنك المركزي أو لأنواع محددة من هذه الموجودات منسوبة إلى إجمالي موجودات البنك بما فيها الكفالات والضمانات القائمة لصالح البنك أو أنواع محددة منها أو منسوبة إلى إجمالي مطلوباته أو أنواع محددة منها.\n٢- المتطلبات المتعلقة بتصنيف الموجودات وتقييمها والمخصصات الواجب الاحتفاظ بها على أساس هذا التصنيف والتقييم.\n٣- المدة التي يحددها البنك المركزي لاعتبار الدخل على القروض غير متحقق، وذلك بقصد عدم احتسابه دخلا للبنك إلا بعد تحققه نقدا.\nب- يفرض البنك المركزي على البنك الذي لا يحتفظ بالحد الأدنى من الموجودات السائلة، وفقا لنص البند(١) من الفقرة (أ) من هذه المادة، غرامة نقدية تحتسب على مقدار النقص عن كل يوم تبدأ من اليوم الأول لوقوع المخالفة وطوال مدة استمرارها على أساس سعر إعادة الخصم مضافا إليه هامش يقرره البنك المركزي بموجب أوامر خاصة يصدرها لهذه الغاية، كما يجوز للبنك المركزي تطبيق أي من الإجراءات أو العقوبات المنصوص عليها في المادة (٨٨) من هذا القانون إذا استمر وقوع المخالفة لمدة تزيد على سبعة أيام أو إذا تكرر وقوعها لأكثر من مرة في السنة الواحدة.","title":"السيولة وتصنيف الموجودات وغرامة النقص","memo":"⭐ يتقيد البنك بأوامر البنك المركزي بشأن الحد الأدنى للموجودات السائلة، تصنيف الموجودات والمخصصات، ومدة اعتبار دخل القروض غير متحقق\n⭐ غرامة على النقص في الموجودات السائلة عن كل يوم على أساس سعر إعادة الخصم مضافاً إليه هامش\n⭐ تطبق إجراءات المادة (٨٨) إذا استمرت المخالفة أكثر من سبعة أيام أو تكررت أكثر من مرة في السنة","qs":[{"q":"تحتسب الغرامة على البنك الذي لا يحتفظ بالحد الأدنى من الموجودات السائلة على مقدار النقص عن كل يوم على أساس:","o":["سعر إعادة الخصم مضافاً إليه هامش يقرره البنك المركزي","مبلغ مقطوع لا يقل عن خمسمائة دينار","ضعف سعر الفائدة على الودائع","نسبة (%١٠) من مقدار النقص"],"a":0},{"q":"يجوز للبنك المركزي تطبيق إجراءات المادة (٨٨) على البنك الذي لا يحتفظ بالحد الأدنى من الموجودات السائلة إذا استمرت المخالفة لمدة تزيد على:","o":["سبعة أيام","ثلاثين يوماً","خمسة عشر يوماً","ثلاثة أيام"],"a":0},{"q":"الغاية من تحديد البنك المركزي مدة لاعتبار الدخل على القروض غير متحقق هي:","o":["عدم احتسابه دخلاً للبنك إلا بعد تحققه نقداً","إعفاؤه من الضريبة نهائياً","توزيعه على المساهمين","إضافته إلى رأس المال التنظيمي"],"a":0}]},{"n":"43","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"على الرغم مما ورد في أي تشريع آخر، ينزل من الدخل الخاضع للضريبة المخصصات التي يرصدها البنك مقابل الائتمان غير العامل على أن يوافق البنك المركزي على رصدها.","title":"تنزيل مخصصات الائتمان غير العامل من الدخل الخاضع للضريبة","memo":"⭐ على الرغم من أي تشريع آخر: تنزل من الدخل الخاضع للضريبة المخصصات التي يرصدها البنك مقابل الائتمان غير العامل بشرط موافقة البنك المركزي على رصدها","qs":[{"q":"ينزل من الدخل الخاضع للضريبة للبنك المخصصات التي يرصدها مقابل الائتمان غير العامل بشرط:","o":["موافقة البنك المركزي على رصدها","موافقة دائرة ضريبة الدخل والمبيعات مسبقاً","ألا تتجاوز (%١٠) من الأرباح","موافقة الهيئة العامة للبنك"],"a":0},{"q":"المخصصات التي يجيز قانون البنوك تنزيلها من الدخل الخاضع للضريبة هي المخصصات المرصودة مقابل:","o":["الائتمان غير العامل","تعويضات نهاية الخدمة للموظفين","الاستثمار في الأوراق المالية","الالتزامات الضريبية المحتملة"],"a":0}]},{"n":"44","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- على البنك أن يعلن بشكل واضح وفي مكان بارز في مركزه الرئيسي وفي فروعه ومكاتبه نسب الفوائد على ودائع عملائه وكذلك أنواع الفوائد والعمولات ونسبها على الائتمان الذي يمنحه لهم بما في ذلك نسب الفوائد لأفضل العملاء.\nب- وعلى البنك أن يزود عميله بنسخ من العقود الموقعة معه وبأي إشعارات أو بيانات أو كشوفات متعلقة بحساباته لدى البنك.","title":"الإعلان عن الفوائد وتزويد العميل بالعقود","memo":"⭐ يعلن البنك بشكل واضح وفي مكان بارز في مركزه وفروعه نسب الفوائد على الودائع وأنواع الفوائد والعمولات على الائتمان بما فيها فوائد أفضل العملاء\n⭐ يزود العميل بنسخ من العقود الموقعة والإشعارات والكشوفات","qs":[{"q":"يلتزم البنك بأن يعلن بشكل واضح وفي مكان بارز في مركزه الرئيسي وفروعه:","o":["نسب الفوائد على الودائع والعمولات على الائتمان بما فيها نسب الفوائد لأفضل العملاء","أسماء العملاء المتعثرين","أسماء المساهمين الرئيسيين ونسب ملكيتهم","رواتب الإدارة العليا"],"a":0},{"q":"يلتزم البنك تجاه عميله بأن يزوده بـ:","o":["نسخ من العقود الموقعة معه والإشعارات والكشوفات المتعلقة بحساباته","نسخ من محاضر مجلس إدارة البنك","نسخة من السياسة الائتمانية للبنك","تقارير التفتيش الصادرة عن البنك المركزي"],"a":0}]},{"n":"45","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"يخضع الائتمان الممنوح من البنك لأي شركة مالية لها علاقة معه للشروط والقيود المحددة بأوامر البنك المركزي، وتعتبر العلاقة بين البنك وهذه الشركة المالية متحققة حكما إذا كان لأي منهما مصلحة مؤثرة في الآخر بشكل مباشر أو غير مباشر.","title":"الائتمان الممنوح لشركة مالية ذات علاقة","memo":"⭐ يخضع الائتمان الممنوح لشركة مالية ذات علاقة لشروط وقيود أوامر البنك المركزي\n⭐ العلاقة متحققة حكماً إذا كان لأي منهما مصلحة مؤثرة في الآخر مباشرة أو غير مباشرة","qs":[{"q":"تعتبر العلاقة بين البنك والشركة المالية متحققة حكماً إذا:","o":["كان لأي منهما مصلحة مؤثرة في الآخر بشكل مباشر أو غير مباشر","كانت الشركة المالية من عملاء البنك","كان للبنك أي عدد من الأسهم في الشركة المالية","تعامل البنك مع الشركة المالية أكثر من مرة في السنة"],"a":0},{"q":"يخضع الائتمان الممنوح من البنك لأي شركة مالية لها علاقة معه للشروط والقيود المحددة بـ:","o":["أوامر البنك المركزي","قرارات مجلس إدارة البنك","قانون الشركات","تعليمات هيئة الأوراق المالية"],"a":0}]},{"n":"46","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- لا يجوز للبنك التعامل مع شخص له علاقة معه إذا كان بإمكان البنك التعامل بشروط افضل لمصلحته مع شخص آخر ليس له علاقة معه، ويعتبر الشخص حكما على علاقة مع البنك في أي من الحالات التالية:\n١- إذا كان الشخص إدارياً في البنك أو له مصلحة عمل مشتركة مع إداري فيه.\n٢- إذا كان زوجاً لإداري في البنك أو قريباً لذلك الإداري أو زوجه حتى الدرجة الثالثة أو كانت له مصلحة عمل مشتركة مع أي منهم.\nب- على الرغم مما ورد في الفقرة (أ) من هذه المادة، لا يجوز للبنك أن يمنح قرضاً لمصلحة شخص أو أشخاص على علاقة مع البنك إذا تجاوزت المبالغ الإجمالية لمختلف أنواع الائتمان التي منحها البنك إلى أشخاص على علاقة معه ما يحدده البنك المركزي بموجب أوامر خاصة يصدرها لهذه الغاية.","title":"التعامل مع الأشخاص ذوي العلاقة بالبنك","memo":"⭐ لا يتعامل البنك مع شخص ذي علاقة إذا أمكنه التعامل بشروط أفضل مع غيره\n⭐ ذو العلاقة حكماً: الإداري أو شريكه في مصلحة عمل، زوج الإداري أو قريبه أو قريب زوجه حتى الدرجة الثالثة\n⭐ مجموع الائتمان للأشخاص ذوي العلاقة لا يتجاوز ما يحدده البنك المركزي بأوامر خاصة","qs":[{"q":"يعتبر الشخص حكماً على علاقة مع البنك إذا كان قريباً للإداري في البنك أو لزوجه حتى:","o":["الدرجة الثالثة","الدرجة الأولى","الدرجة الثانية","الدرجة الرابعة"],"a":0},{"q":"لا يجوز للبنك التعامل مع شخص له علاقة معه إذا:","o":["كان بإمكان البنك التعامل بشروط أفضل لمصلحته مع شخص آخر ليس له علاقة معه","كان الشخص من العملاء القدامى للبنك","كان التعامل بالعملة الأجنبية","لم يكن الشخص مساهماً في البنك"],"a":0},{"q":"الحد الأقصى للمبالغ الإجمالية للائتمان الذي يمنحه البنك للأشخاص ذوي العلاقة معه يحدده:","o":["البنك المركزي بموجب أوامر خاصة","مجلس إدارة البنك","الهيئة العامة للبنك","لجنة التدقيق"],"a":0}]},{"n":"47","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"لا يجوز للبنك دون موافقة خطية مسبقة من البنك المركزي أن يمنح ائتماناً أو مساعدة مالية تزيد على الحدود والنسب المقررة في أوامر البنك المركزي لأي إداري فيه أو في أي شركة تابعة له.","title":"الائتمان الممنوح للإداريين","memo":"⭐ لا يمنح البنك ائتماناً أو مساعدة مالية تزيد على الحدود والنسب المقررة لأي إداري فيه أو في شركة تابعة له إلا بموافقة خطية مسبقة من البنك المركزي","qs":[{"q":"لا يجوز للبنك أن يمنح ائتماناً لأي إداري فيه يزيد على الحدود والنسب المقررة في أوامر البنك المركزي إلا بعد:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة لجنة التدقيق","موافقة الهيئة العامة للبنك","إشعار البنك المركزي خلال خمسة عشر يوماً"],"a":0},{"q":"يسري قيد منح الائتمان الوارد في المادة (٤٧) على الإداري في:","o":["البنك أو في أي شركة تابعة له","البنك فقط دون شركاته التابعة","البنوك الأخرى فقط","البنك المركزي"],"a":0}]},{"n":"48","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"أ- لا يجوز للبنك أن يمتلك عقاراً إلا بما يحتاج إليه لإدارة أعماله أو لإسكان موظفيه وخدمتهم، ولا يحول ذلك دون تأجير جزء من عقاره بموافقة خطية مسبقة من البنك المركزي.\nب-يستثنى من أحكام الفقرة (أ) من هذه المادة ما يمتلكه البنك من عقارات سداداً لدين له على أن يتخلص من هذا التملك خلال سنتين من تاريخ اكتسابه الملكية، وللبنك المركزي في حالات خاصة أن يمدد تلك المدة لسنتين متتاليتين حداً أقصى.","title":"تملك البنك للعقارات","memo":"⭐ لا يمتلك البنك عقاراً إلا لإدارة أعماله أو لإسكان موظفيه وخدمتهم\n⭐ تأجير جزء من عقاره بموافقة خطية مسبقة من البنك المركزي\n⭐ العقار المتملك سداداً لدين: التخلص خلال سنتين، ويجوز التمديد لسنتين متتاليتين حداً أقصى","qs":[{"q":"يجوز للبنك أن يمتلك عقاراً في حدود:","o":["ما يحتاج إليه لإدارة أعماله أو لإسكان موظفيه وخدمتهم","أي عقار بغرض الاستثمار دون قيد","ما لا يتجاوز (%٢٠) من إجمالي ودائعه","ما يوافق عليه مجلس إدارة البنك"],"a":0},{"q":"تملك بنك عقاراً سداداً لدين له. يجب عليه التخلص من هذا التملك خلال:","o":["سنتين من تاريخ اكتسابه الملكية قابلة للتمديد لسنتين متتاليتين حداً أقصى","سنة من تاريخ اكتسابه الملكية غير قابلة للتمديد","خمس سنوات من تاريخ اكتسابه الملكية","ستة أشهر من تاريخ اكتسابه الملكية"],"a":0},{"q":"تأجير البنك جزءاً من عقاره المخصص لإدارة أعماله يتطلب:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة مجلس الوزراء","قراراً من الهيئة العامة غير العادية","لا يجوز ذلك مطلقاً"],"a":0}]},{"n":"49","chapter":"متطلبات عمل البنك وشروطه","notes":[],"source":"على مدير عام البنك أو من يفوضه بذلك أن يبعث بكتاب خطي إلى دوائر التسجيل يطلب فيه رفع إشارة التامين عن أموال المقترض وكفلائه فور تسديد كامل المبالغ المؤمنة بها.","title":"رفع إشارة التأمين عن أموال المقترض","memo":"⭐ المدير العام أو من يفوضه يبعث كتاباً خطياً لدوائر التسجيل لرفع إشارة التأمين عن أموال المقترض وكفلائه فور تسديد كامل المبالغ المؤمنة","qs":[{"q":"يقع واجب مخاطبة دوائر التسجيل لرفع إشارة التأمين عن أموال المقترض وكفلائه على:","o":["مدير عام البنك أو من يفوضه بذلك","المقترض نفسه","البنك المركزي","رئيس مجلس إدارة البنك حصراً"],"a":0},{"q":"يجب طلب رفع إشارة التأمين عن أموال المقترض وكفلائه:","o":["فور تسديد كامل المبالغ المؤمنة بها","بعد مرور ثلاثين يوماً على السداد","عند تسديد نصف المبالغ المؤمنة","بعد موافقة البنك المركزي على ذلك"],"a":0}]},{"n":"50","chapter":"البنك الإسلامي","notes":[],"source":"أ- يهدف البنك الإسلامي إلى ما يلي:\n١- تقديم الخدمات المصرفية وممارسة أعمال التمويل والاستثمار القائمة على غير أساس الفائدة أخذا و/أو إعطاء في جميع الصور والأحوال.\n٢- تطوير وسائل اجتذاب الأموال والمدخرات وتوجيهها نحو المشاركة في الاستثمار بالأسلوب المصرفي القائم على غير أساس الفائدة.\n٣- تقديم الخدمات الهادفة لإحياء صور التكافل الاجتماعي المنظم على أساس المنفعة المشتركة.\nب- يجب أن يكون عقد تأسيس البنك الإسلامي ونظامه الأساسي متفقاً مع جميع الأحكام الخاصة بالبنوك الإسلامية الواردة في هذا القانون.","title":"أهداف البنك الإسلامي","memo":"⭐ تقديم الخدمات المصرفية والتمويل والاستثمار على غير أساس الفائدة أخذاً و/أو إعطاءً\n⭐ تطوير وسائل اجتذاب الأموال نحو الاستثمار غير الربوي\n⭐ إحياء صور التكافل الاجتماعي على أساس المنفعة المشتركة\n⭐ يجب أن يتفق عقد تأسيسه ونظامه الأساسي مع أحكام البنوك الإسلامية في القانون","qs":[{"q":"يهدف البنك الإسلامي إلى تقديم الخدمات المصرفية وممارسة أعمال التمويل والاستثمار القائمة على:","o":["غير أساس الفائدة أخذاً و/أو إعطاءً","أساس الفائدة الثابتة","أساس الفائدة المتغيرة","أساس العمولة فقط"],"a":0},{"q":"أي مما يلي لا يعد من أهداف البنك الإسلامي وفق المادة (٥٠)؟","o":["منح الائتمان مقابل فوائد محددة مسبقاً","تطوير وسائل اجتذاب الأموال والمدخرات نحو المشاركة في الاستثمار","تقديم الخدمات الهادفة لإحياء صور التكافل الاجتماعي","تقديم الخدمات المصرفية القائمة على غير أساس الفائدة"],"a":0},{"q":"يجب أن يكون عقد تأسيس البنك الإسلامي ونظامه الأساسي متفقاً مع:","o":["جميع الأحكام الخاصة بالبنوك الإسلامية الواردة في قانون البنوك","أنظمة البنوك الإسلامية في الدول الأخرى","تعليمات مراقب عام الشركات فقط","قرارات الهيئة العامة للبنك فقط"],"a":0}]},{"n":"51","chapter":"البنك الإسلامي","notes":[],"source":"يجوز للبنك المركزي دون إخلال بالأحكام الخاصة بالبنوك الإسلامية ، أن يصدر الأوامر التي يراها ضرورية لوضع ضوابط قيود ونسب خاصة يلتزم البنك الإسلامي بمراعاتها عند ممارسة أعماله وأنشطته وفق أحكام هذا القانون.","title":"أوامر البنك المركزي للبنوك الإسلامية","memo":"⭐ للبنك المركزي دون إخلال بالأحكام الخاصة بالبنوك الإسلامية إصدار أوامر لوضع ضوابط وقيود ونسب خاصة يلتزم بها البنك الإسلامي","qs":[{"q":"الجهة التي يجوز لها إصدار أوامر لوضع ضوابط وقيود ونسب خاصة يلتزم البنك الإسلامي بمراعاتها هي:","o":["البنك المركزي","هيئة الرقابة الشرعية للبنك","مجلس الوزراء","دائرة الإفتاء العام"],"a":0},{"q":"يصدر البنك المركزي الأوامر الخاصة بالبنوك الإسلامية:","o":["دون إخلال بالأحكام الخاصة بالبنوك الإسلامية","بما يلغي الأحكام الخاصة بالبنوك الإسلامية","بعد موافقة مجلس الأمة","بموافقة الهيئة العامة لكل بنك إسلامي"],"a":0}]},{"n":"52","chapter":"البنك الإسلامي","notes":[],"source":"تشمل الأعمال المصرفية الإسلامية التي يجوز للبنك الإسلامي ممارستها ما يلي:\nأ- قبول الودائع النقدية في حسابات مختلفة سواءً في حسابات ائتمان أو حسابات استثمار مشترك أو حسابات استثمار مخصص.\nب-إصدار صكوك التمويل الإسلامي أو إنشاء محافظ استثمارية أو صناديق استثمارية.\nج- أعمال التمويل والاستثمار القائمة على غير أساس الفائدة، وذلك من خلال الوسائل التالية:\n١- تقديم التمويل اللازم، كلياً أو جزئياً، للعمليات القابلة للتصفية الذاتية في مختلف المجالات، بما في ذلك صيغ التمويل بالمضاربة والمشاركة المتناقصة وبيع المرابحة للآمر بالشراء وغيرها من صيغ التمويل التي توافق عليها هيئة الرقابة الشرعية ولا يعترض عليها البنك المركزي.\n٢- توظيف الأموال التي يرغب أصحابها في استثمارها المشترك مع سائر الموارد المتاحة لدى البنك الإسلامي وذلك وفق نظام المضاربة المشتركة، ويجوز للبنك الإسلامي في حالات معينة أن يقوم بالتوظيف المحدد حسب الاتفاق الخاص بذلك.\n٣- استثمار الأموال في مختلف المشاريع.","title":"الأعمال المصرفية الإسلامية","memo":"⭐ تشمل: قبول الودائع في حسابات ائتمان أو استثمار مشترك أو استثمار مخصص\n⭐ إصدار صكوك التمويل الإسلامي وإنشاء محافظ أو صناديق استثمارية\n⭐ صيغ التمويل (مضاربة، مشاركة متناقصة، مرابحة للآمر بالشراء) توافق عليها هيئة الرقابة الشرعية ولا يعترض عليها البنك المركزي\n⭐ توظيف أموال الاستثمار المشترك وفق نظام المضاربة المشتركة","qs":[{"q":"وفقاً لقانون البنوك، تقبل البنوك الإسلامية الودائع النقدية في أي من الحسابات التالية:","o":["حسابات ائتمان أو استثمار مشترك أو استثمار مخصص","حسابات جارية وحسابات توفير بفائدة فقط","حسابات استثمار مشترك فقط","حسابات ائتمان فقط دون حسابات الاستثمار"],"a":0},{"q":"صيغ التمويل الإسلامي غير المنصوص عليها صراحة يشترط لاعتمادها أن:","o":["توافق عليها هيئة الرقابة الشرعية ولا يعترض عليها البنك المركزي","يوافق عليها وزير المالية","توافق عليها الهيئة العامة للمساهمين","يوافق عليها مجلس إدارة البنك الإسلامي فقط"],"a":0},{"q":"يتم توظيف الأموال التي يرغب أصحابها في استثمارها المشترك لدى البنك الإسلامي وفق نظام:","o":["المضاربة المشتركة","المرابحة للآمر بالشراء","المشاركة المتناقصة","الوكالة بأجر"],"a":0},{"q":"أي مما يلي لا يعد من الأعمال المصرفية الإسلامية الواردة في القانون؟","o":["منح القروض بفائدة محددة مسبقاً","إصدار صكوك التمويل الإسلامي","إنشاء صناديق استثمارية","استثمار الأموال في مختلف المشاريع"],"a":0}]},{"n":"53","chapter":"البنك الإسلامي","notes":[],"source":"على البنك الإسلامي مراعاة الشروط والقيود التالية:\nأ- أن تكون أعماله وأنشطته متفقة مع الآراء الفقهية المعتمدة، ويقصد بها الأحكام الفقهية التي يلتزم بها البنك الإسلامي على أساس الاختيار من بين سائر المذاهب الإسلامية وفقا للمصلحة الراجحة ودون التقيد بمذهب معين ووفقا لما تعتمده هيئة الرقابة الشرعية في البنك لهذه الغاية.\nب- أن تكون أعماله وأنشطته قائمة على غير أساس الفائدة بنوعيها التاليين:\n١- فائدة الديون التي تقبض أو تدفع في جميع حالات الإقراض والاقتراض، بما في ذلك أي اجر يدفعه المقترض دون ارتباطه بجهد تقابله منفعة معتبرة حسب الآراء الفقهية المعتمدة.\n٢- فائدة البيوع في إطار العمل المصرفي في حالات الصرف للعملات المختلفة الجنس إذا داخلها الأجل.","title":"شروط وقيود عمل البنك الإسلامي","memo":"⭐ أعماله متفقة مع الآراء الفقهية المعتمدة: اختيار من سائر المذاهب وفق المصلحة الراجحة دون التقيد بمذهب معين، وفق ما تعتمده هيئة الرقابة الشرعية\n⭐ أعماله قائمة على غير أساس الفائدة بنوعيها: فائدة الديون (إقراض واقتراض) وفائدة البيوع (صرف العملات المختلفة الجنس إذا داخلها الأجل)","qs":[{"q":"يقصد بالآراء الفقهية المعتمدة التي يلتزم بها البنك الإسلامي الأحكام الفقهية التي يختارها:","o":["من بين سائر المذاهب الإسلامية وفق المصلحة الراجحة دون التقيد بمذهب معين","وفق مذهب فقهي واحد يحدده البنك المركزي","وفق ما يقرره مجلس إدارة البنك دون الرجوع لأي هيئة","وفق المذهب المعتمد في دائرة الإفتاء فقط"],"a":0},{"q":"الجهة التي تعتمد الآراء الفقهية التي يلتزم بها البنك الإسلامي هي:","o":["هيئة الرقابة الشرعية في البنك","البنك المركزي","الهيئة العامة للمساهمين","مجلس إدارة جمعية البنوك"],"a":0},{"q":"تعد فائدة البيوع المحظورة على البنك الإسلامي متحققة في حالات:","o":["الصرف للعملات المختلفة الجنس إذا داخلها الأجل","بيع المرابحة للآمر بالشراء","المشاركة المتناقصة","الصرف الفوري للعملات المختلفة الجنس"],"a":0}]},{"n":"54","chapter":"البنك الإسلامي","notes":[],"source":"مع مراعاة أي أوامر يصدرها البنك المركزي، يجوز للبنك الإسلامي، في سبيل تحقيق أهدافه، أن يقوم بأي من الأعمال والأنشطة التالية:\nأ- ممارسة الأعمال المصرفية الأخرى القائمة على غير أساس الفائدة بجميع أوجهها المعروفة أو المستحدثة سواء لحسابه أو لحساب غيره في داخل المملكة وخارجها شريطة التزامه بما تتقيد به البنوك الأخرى في هذا الخصوص.\nب- القيام بدور الوصي المختار لإدارة التركات وتنفيذ الوصايا وفقا للأحكام الشرعية والقوانين المرعية وبالتعاون المشترك مع الجهة الدينية ذات الاختصاص.\nج- القيام بدور الوكيل الأمين في مجال الخدمات الاجتماعية الهادفة إلى توثيق أواصر الترابط والتراحم بين الجماعات والأفراد، بما في ذلك تقديم القروض الحسنة لغايات إنتاجية في أي مجال وإنشاء وإدارة الصناديق المخصصة للغايات الاجتماعية المعتبرة.\nد- أي أعمال وأنشطة تمكنه من تحقيق غاياته وبوجه خاص ما يلي:\n١- تأسيس الشركات في مختلف المجالات وبخاصة المكملة منها لأوجه نشاط البنك الإسلامي.\n٢- تملك الأموال المنقولة وغير المنقولة وبيعها واستثمارها وتأجيرها واستئجارها بما في ذلك استصلاح الأراضي المملوكة أو المستأجرة وإعدادها للزراعة والصناعة والسياحة والإسكان، وذلك دون الحاجة لاستصدار أي موافقة يتطلبها قانون تصرف الأشخاص المعنويين في الأموال غير المنقولة النافذ المفعول.\n٣- إنشاء صناديق التأمين الذاتي والتامين التبادلي لصالح البنك الإسلامي أو المتعاملين معه في مختلف المجالات.\n٤- إدارة الممتلكات وغيرها من الموجودات القابلة للإدارة المصرفية على أساس الوكالة بأجر.","title":"الأعمال الأخرى للبنك الإسلامي","memo":"⭐ مع مراعاة أوامر البنك المركزي، يجوز له دور الوصي المختار لإدارة التركات وتنفيذ الوصايا بالتعاون مع الجهة الدينية المختصة\n⭐ دور الوكيل الأمين في الخدمات الاجتماعية بما فيها القروض الحسنة لغايات إنتاجية\n⭐ تملك الأموال غير المنقولة دون الحاجة لموافقة يتطلبها قانون تصرف الأشخاص المعنويين في الأموال غير المنقولة\n⭐ إنشاء صناديق التأمين الذاتي والتبادلي، وإدارة الممتلكات على أساس الوكالة بأجر","qs":[{"q":"يقوم البنك الإسلامي بدور الوصي المختار لإدارة التركات وتنفيذ الوصايا بالتعاون المشترك مع:","o":["الجهة الدينية ذات الاختصاص","البنك المركزي","المحكمة الإدارية","مراقب الشركات"],"a":0},{"q":"تقديم القروض الحسنة لغايات إنتاجية من قبل البنك الإسلامي يندرج ضمن دوره بصفته:","o":["الوكيل الأمين في مجال الخدمات الاجتماعية","الوصي المختار","المضارب في الاستثمار المشترك","مدير المحافظ الاستثمارية"],"a":0},{"q":"حالة عملية: أراد بنك إسلامي تملك أرض واستصلاحها للزراعة. وفق القانون فإن ذلك:","o":["يجوز دون الحاجة لاستصدار موافقة يتطلبها قانون تصرف الأشخاص المعنويين في الأموال غير المنقولة","لا يجوز إلا بموافقة مجلس الوزراء","يجوز بشرط موافقة وزير الزراعة","محظور على البنوك الإسلامية"],"a":0},{"q":"يدير البنك الإسلامي الممتلكات وغيرها من الموجودات القابلة للإدارة المصرفية على أساس:","o":["الوكالة بأجر","المضاربة المشتركة","القرض الحسن","المشاركة المتناقصة"],"a":0}]},{"n":"55","chapter":"البنك الإسلامي","notes":[],"source":"يجوز للبنك الإسلامي بموجب أوامر خاصة يصدرها البنك المركزي:\nأ- تكوين احتياطي معدل الأرباح.\nب-التنازل عن حصته من كامل الأرباح أو جزء منها لدعم أرباح حصة أصحاب حسابات الاستثمار المشترك.\nج-تحمل كامل خسائر أصحاب حسابات الاستثمار المشترك أو جزء منها.","title":"صلاحيات البنك الإسلامي بأوامر خاصة","memo":"⭐ بموجب أوامر خاصة من البنك المركزي يجوز: تكوين احتياطي معدل الأرباح\n⭐ التنازل عن حصته من الأرباح كلياً أو جزئياً لدعم أرباح أصحاب حسابات الاستثمار المشترك\n⭐ تحمل كامل خسائر أصحاب حسابات الاستثمار المشترك أو جزء منها","qs":[{"q":"يجوز للبنك الإسلامي تكوين احتياطي معدل الأرباح بموجب:","o":["أوامر خاصة يصدرها البنك المركزي","قرار من هيئة الرقابة الشرعية فقط","قرار من الهيئة العامة للمساهمين","نظام يصدره مجلس الوزراء"],"a":0},{"q":"يجوز للبنك الإسلامي بموجب أوامر خاصة من البنك المركزي تحمل خسائر أصحاب:","o":["حسابات الاستثمار المشترك كلياً أو جزئياً","حسابات الائتمان فقط","حسابات الاستثمار المخصص كلياً","الصكوك الإسلامية فقط"],"a":0}]},{"n":"56","chapter":"البنك الإسلامي","notes":[],"source":"أ- مع مراعاة أحكام الفقرة (ج) من المادة (١٠١) من هذا القانون، إذا قرر البنك المركزي تصفية بنك إسلامي وفق أحكام هذا القانون، تتولى مؤسسة ضمان الودائع إجراء هذه التصفية وفق أحكام تصفية البنوك المنصوص عليها في قانون المؤسسة وذلك بالقدر الذي لا تتعارض فيه تلك الأحكام مع الأحكام الخاصة بالبنوك الإسلامية الواردة في هذا القانون.\nب-على الرغم من أحكام أي تشريع آخر، يتم تسديد الالتزامات والديون المستحقة على البنك الإسلامي تحت التصفية وفق الأسس التالية:\n١- تؤدى حقوق المودعين في حسابات الاستثمار المشترك وفقا للشروط الخاصة بها، وتؤدى حقوق مالكي الصكوك الإسلامية أو المحافظ الاستثمارية أو الصناديق الاستثمارية حسب الشروط الخاصة بكل إصدار منها، وعلى أن يسبق ذلك تحميل هذه الحقوق ما يخصها من مصاريف ومن نفقات للمصفي ومن ثم تحميلها ما يخصها من التزامات مرتبطة بها.\n٢- ترتبط حقوق المودعين في حسابات الاستثمار المخصص وكذلك حقوق مالكي سندات المقارضة المخصصة بالمشاريع المحددة لكل منها على حدة، وتتحمل نتائجها على أساس الغرم بالغنم، وذلك بعد أن يقتطع منها ما يخصها من مصاريف ومن نفقات للمصفي.\n٣- دون الإخلال بأحكام البندين (١و٢) من هذه الفقرة، يتم الوفاء بالالتزامات والديون المترتبة على البنك الإسلامي، تحت التصفية، وذلك وفق الترتيب التالي:\nأ- باقي المصاريف والنفقات التي تكبدها المصفي في أعمال التصفية.\nب- حقوق موظفي البنك الإسلامي ومستخدميه من رواتب ومكافآت وأي تعويضات عمالية أخرى يقتضيها قانون العمل.\nج- أي ضرائب ورسوم مستحقة للحكومة.\nد- حقوق المودعين في حسابات الائتمان.\nه- حقوق الدائنين وأي أموال أخرى مودعة من قبل أصحابها لدى البنك لغير غايات الاستثمار والمشاركة في الأرباح الناجمة عنه.\nو- حقوق المودعين في حسابات الاستثمار المشترك.","title":"تصفية البنك الإسلامي وترتيب الديون","memo":"⭐ تتولى مؤسسة ضمان الودائع التصفية إذا قررها البنك المركزي (مع مراعاة م101/ج)\n⭐ حقوق الاستثمار المخصص وسندات المقارضة المخصصة ترتبط بمشاريعها على أساس الغرم بالغنم\n⭐ الترتيب: باقي نفقات المصفي ← حقوق الموظفين ← الضرائب والرسوم ← حسابات الائتمان ← الدائنون والأموال المودعة لغير الاستثمار ← حسابات الاستثمار المشترك","qs":[{"q":"إذا قرر البنك المركزي تصفية بنك إسلامي فإن الجهة التي تتولى إجراء التصفية هي:","o":["مؤسسة ضمان الودائع","وزارة الصناعة والتجارة","هيئة الرقابة الشرعية","المحكمة المختصة"],"a":0},{"q":"تتحمل حقوق المودعين في حسابات الاستثمار المخصص نتائج المشاريع المحددة لها على أساس:","o":["الغرم بالغنم","الأولوية على سائر الدائنين","الضمان الكامل من البنك","الفائدة الثابتة"],"a":0},{"q":"وفق ترتيب الوفاء بالتزامات البنك الإسلامي تحت التصفية، تأتي الضرائب والرسوم المستحقة للحكومة:","o":["بعد حقوق الموظفين وقبل حقوق المودعين في حسابات الائتمان","قبل جميع نفقات المصفي","بعد حقوق المودعين في حسابات الائتمان","في المرتبة الأخيرة بعد حسابات الاستثمار المشترك"],"a":0},{"q":"أول ما يتم الوفاء به وفق الترتيب الوارد في البند (٣) من الفقرة (ب) هو:","o":["باقي المصاريف والنفقات التي تكبدها المصفي","حقوق موظفي البنك ومستخدميه","حقوق المودعين في حسابات الائتمان","الضرائب والرسوم المستحقة للحكومة"],"a":0}]},{"n":"57","chapter":"البنك الإسلامي","notes":[],"source":"بعد مراعاة أحكام المادة (٥٦) من هذا القانون، تتم تصفية حقوق المساهمين في البنك الإسلامي تحت التصفية على أساس اقتسام ما يتبقى من أموال بنسبة الأسهم المملوكة لكل واحد منهم.","title":"تصفية حقوق مساهمي البنك الإسلامي","memo":"⭐ بعد مراعاة م56 تصفى حقوق المساهمين باقتسام ما يتبقى من أموال بنسبة الأسهم المملوكة لكل منهم","qs":[{"q":"تتم تصفية حقوق المساهمين في البنك الإسلامي تحت التصفية على أساس اقتسام ما يتبقى من أموال:","o":["بنسبة الأسهم المملوكة لكل واحد منهم","بالتساوي بين المساهمين","حسب أقدمية المساهمة","وفق ما تقرره هيئة الرقابة الشرعية"],"a":0},{"q":"تتم تصفية حقوق المساهمين في البنك الإسلامي تحت التصفية:","o":["بعد مراعاة ترتيب الوفاء بالالتزامات والديون الوارد في المادة (٥٦)","قبل الوفاء بحقوق المودعين في حسابات الائتمان","قبل حقوق موظفي البنك","بالتزامن مع حقوق أصحاب حسابات الاستثمار المشترك"],"a":0}]},{"n":"58","chapter":"البنك الإسلامي","notes":[],"source":"أ- تنفيذاً لالتزام البنك الإسلامي بمقتضى عقد تأسيسه ونظامه الأساسي بوجوب تقيده بأحكام الشريعة الإسلامية، يعين البنك بقرار من الهيئة العامة للمساهمين هيئة تسمى (هيئة الرقابة الشرعية) لا يقل عدد أفرادها عن ثلاثة أشخاص يكون رأيها ملزما للبنك الإسلامي، وتتولى هذه الهيئة المهام التالية:\n١- مراقبة أعمال البنك الإسلامي وأنشطته من حيث التزامها بالأحكام الشرعية.\n٢- إبداء الرأي في صيغ العقود اللازمة لأعماله وأنشطته.\n٣- النظر في أي أمور تكلف بها وفقا لأوامر البنك المركزي الصادرة لهذه الغاية.\nب- تعين هيئة الرقابة الشرعية أحد أعضائها رئيساً لها، وتجتمع بدعوة من رئيسها أو بناءً على قرار من مجلس إدارة البنك الإسلامي أو بناء على طلب اثنين من أعضائها، ويكون اجتماعها قانونياً بحضور عضوين على الأقل إذا كان عدد أعضائها ثلاثة أشخاص وبحضور أغلبية عدد أعضائها إذا زاد عددهم على ثلاثة أشخاص، وتتخذ قراراتها في أي حال بالإجماع أو بأغلبية عدد أعضائها.\nج- لا يجوز عزل هيئة الرقابة الشرعية المعينة أو أي عضو فيها إلا إذا صدر قرار معلل من مجلس إدارة البنك الإسلامي بأغلبية ثلثي أعضائه على أن يقترن هذا القرار بموافقة الهيئة العامة لمساهمي البنك.\nد- على البنك الإسلامي إعلام البنك المركزي بقرار تعيين هيئة الرقابة الشرعية أو عزلها.\nه- للبنك المركزي التأكد من مواءمة أعضاء هيئة الرقابة الشرعية للخبرات والشروط الواجب توافرها فيهم.","title":"هيئة الرقابة الشرعية","memo":"⭐ تعين بقرار من الهيئة العامة للمساهمين، لا يقل عدد أعضائها عن ثلاثة، ورأيها ملزم للبنك\n⭐ النصاب: عضوان على الأقل إذا كانوا ثلاثة، والأغلبية إذا زادوا على ثلاثة؛ القرارات بالإجماع أو بالأغلبية\n⭐ تجتمع بدعوة رئيسها أو بقرار مجلس الإدارة أو بطلب اثنين من أعضائها\n⭐ العزل بقرار معلل من مجلس الإدارة بأغلبية الثلثين مقترناً بموافقة الهيئة العامة؛ ويعلم البنك المركزي بالتعيين والعزل","qs":[{"q":"تعين هيئة الرقابة الشرعية في البنك الإسلامي بقرار من:","o":["الهيئة العامة للمساهمين","مجلس إدارة البنك الإسلامي","البنك المركزي","دائرة الإفتاء العام"],"a":0},{"q":"الحد الأدنى لعدد أعضاء هيئة الرقابة الشرعية هو:","o":["ثلاثة أشخاص","شخصان","خمسة أشخاص","سبعة أشخاص"],"a":0},{"q":"حالة عملية: هيئة رقابة شرعية مكونة من ثلاثة أعضاء، يكون اجتماعها قانونياً بحضور:","o":["عضوين على الأقل","الأعضاء الثلاثة جميعهم","عضو واحد مع الرئيس","أغلبية ثلثي الأعضاء"],"a":0},{"q":"لا يجوز عزل هيئة الرقابة الشرعية أو أي عضو فيها إلا بقرار معلل من مجلس إدارة البنك بأغلبية:","o":["ثلثي أعضائه مقترناً بموافقة الهيئة العامة للمساهمين","الأغلبية المطلقة لأعضائه فقط","ثلاثة أرباع أعضائه مقترناً بموافقة البنك المركزي","ثلثي أعضائه مقترناً بموافقة المحافظ"],"a":0}]},{"n":"59","chapter":"الحسابات والبيانات المالية","notes":[],"source":"أ- يصدر البنك المركزي أوامر خاصة يحدد فيها الشروط الواجب توافرها في مدقق الحسابات الخارجي لأعمال البنوك، وعلى البنك أن يعين وفق هذه الأوامر مدققاً لحساباته للسنة المالية ليقوم بما يلي:\n١. مساعدة البنك على الاحتفاظ بالسجلات والحسابات الصحيحة وفق أحكام المادة (٦٠) من هذا القانون.\n٢. مراجعة كفاية أعمال التدقيق الداخلي وإجراءات الرقابة الداخلية ووضع توصياته بشأنها.\n٣. تقديم تقرير سنوي عن نتائج تدقيقه لحسابات البنك مبيناً فيه الأوضاع المالية الحقيقية للبنك، ورأيه في هذه الحسابات وتزويد البنك بنسخ منه.\n٤. تزويد البنك المركزي بشهادة تبيّن رأيه في مخصصات الديون المشكوك في تحصيلها أو أي نقص في المخصصات التي تتطلبها موجودات البنك وفقاً للأوامر التي يصدرها البنك المركزي لهذه الغاية.\n٥. تزويد البنك المركزي بأي معلومات أو بيانات إضافية عن أوضاع البنك.\n٦. إعلام البنك المركزي خطياً وفوراً عن أي أمور لها أثر سلبي في أوضاع البنك المالية أو الإدارية .\n٧. إعلام البنك المركزي فوراً عن أي مخالفات قانونية يرتكبها مجلس إدارة البنك أو مجلس إدارة أي شركة تابعة له وأي إداري في أي منهما أو أي عمليات غير مشروعة في أي منهما أو أي عمليات يتوقع أن تلحق خسارة بالبنك أو بالشركة.\n٨. تزويد البنك المركزي بأي نسخ من أي تقارير أو شهادات يقدمها لأي بنك.\nب- للبنك المركزي الاعتراض على مدقق الحسابات الخارجي، إذا لم تتحقق فيه الشروط الواردة في الأوامر المنصوص عليها في الفقرة (أ) من هذه المادة.\nج- إذا لم يعين البنك لأي سبب مدقق حسابات قانوني لتدقيق حسابات البنك وفقاً لأحكام الفقرة (أ) من هذه المادة خلال مدة لا تزيد على أربعة أشهر من بداية السنة المالية فللبنك المركزي تعيين مدقق حسابات قانوني وتحديد أتعابه على نفقة البنك لتدقيق حساباته.\nد- للبنك المركزي، أن يعين مدقق حسابات قانوني لمراجعة حسابات البنك وتدقيقها إذا رأى ذلك ضرورياً إضافة إلى المدقق الذي يتم تعيينه وفق أحكام الفقرة (أ) أو الفقرة (ج) من هذه المادة، ويحدد البنك المركزي المهمة الموكلة لهذا المدقق ومدة عمله وأتعابه على نفقة البنك.","title":"مدقق الحسابات الخارجي للبنك","memo":"⭐ البنك المركزي يحدد بأوامر خاصة شروط المدقق الخارجي، ويعين البنك مدققاً للسنة المالية\n⭐ إذا لم يعين البنك مدققاً خلال مدة لا تزيد على أربعة أشهر من بداية السنة المالية، يعينه البنك المركزي ويحدد أتعابه على نفقة البنك\n⭐ للبنك المركزي الاعتراض على المدقق غير المستوفي للشروط، وتعيين مدقق إضافي يحدد مهمته ومدته وأتعابه على نفقة البنك\n⭐ المدقق يعلم البنك المركزي خطياً وفوراً عن الأمور ذات الأثر السلبي، وفوراً عن المخالفات القانونية","qs":[{"q":"إذا لم يعين البنك مدقق حسابات قانونياً، فللبنك المركزي تعيينه إذا انقضت مدة:","o":["أربعة أشهر من بداية السنة المالية","شهرين من بداية السنة المالية","ستة أشهر من بداية السنة المالية","ثلاثة أشهر من نهاية السنة المالية"],"a":0},{"q":"أتعاب مدقق الحسابات الذي يعينه البنك المركزي إضافة إلى مدقق البنك تكون:","o":["على نفقة البنك","على نفقة البنك المركزي","مناصفة بين البنك والبنك المركزي","على نفقة مؤسسة ضمان الودائع"],"a":0},{"q":"أي مما يلي لا يعد من مهام مدقق الحسابات الخارجي للبنك وفق القانون؟","o":["تولي إدارة البنك عند تعثره","مراجعة كفاية أعمال التدقيق الداخلي وإجراءات الرقابة الداخلية","تزويد البنك المركزي بشهادة تبين رأيه في مخصصات الديون المشكوك في تحصيلها","إعلام البنك المركزي فوراً عن أي مخالفات قانونية يرتكبها مجلس الإدارة"],"a":0},{"q":"يحق للبنك المركزي الاعتراض على مدقق الحسابات الخارجي للبنك في حال:","o":["عدم تحقق الشروط الواردة في أوامر البنك المركزي فيه","عدم موافقة الهيئة العامة عليه","تجاوز أتعابه حداً معيناً","كونه مدققاً لبنك آخر"],"a":0}]},{"n":"60","chapter":"الحسابات والبيانات المالية","notes":[],"source":"أ- على البنك التقيد بأوامر البنك المركزي المتعلقة بما يلي:\n١- الاحتفاظ بالسجلات اللازمة لأعماله منظمة حسب الأصول.\n٢- تنظيم حساباته وفق الأصول المحاسبية المتعارف عليها وإعداد بياناته المالية وبشكل وافٍ يعكس حقيقة الأوضاع المالية للبنك وفروعه والشركات التابعة له مع وجوب الالتزام بأي متطلبات خاصة يحددها البنك المركزي بهذا الشأن.\nب- للبنك المركزي أن ينشر، كلياً أو جزئياً البيانات والمعلومات التي تزوده بها البنوك وذلك في الأوقات التي يقررها شريطة أن لا يكون في نشرها كشف لأعمال البنك إلا إذا حصل البنك المركزي على موافقة خطية مسبقة من ذلك البنك.","title":"السجلات والحسابات ونشر البيانات","memo":"⭐ يلتزم البنك بأوامر البنك المركزي بالاحتفاظ بالسجلات وتنظيم الحسابات وفق الأصول المحاسبية المتعارف عليها\n⭐ للبنك المركزي نشر البيانات كلياً أو جزئياً، ولا يجوز أن يكشف نشرها أعمال البنك إلا بموافقة خطية مسبقة منه","qs":[{"q":"للبنك المركزي أن ينشر البيانات التي تزوده بها البنوك، شريطة أن لا يكون في نشرها كشف لأعمال البنك إلا بعد:","o":["الحصول على موافقة خطية مسبقة من ذلك البنك","موافقة مجلس الوزراء","موافقة جمعية البنوك","قرار من المحكمة المختصة"],"a":0},{"q":"ينظم البنك حساباته ويعد بياناته المالية وفق:","o":["الأصول المحاسبية المتعارف عليها مع الالتزام بالمتطلبات الخاصة التي يحددها البنك المركزي","ما تقرره الهيئة العامة للمساهمين فقط","تعليمات مراقب الشركات حصراً","ما يقرره مدقق الحسابات الخارجي"],"a":0}]},{"n":"61","chapter":"الحسابات والبيانات المالية","notes":[],"source":"أ- للبنك المركزي بناءً على مبررات ضرورية وعلى نفقة البنك أن يعين جهة استشارية مختصة وتمتلك خبرة كافية تتولى تقييم أي جوانب تتعلق بأنشطة البنك.\nب-يحدد البنك المركزي المهمة الموكلة للجهة الاستشارية المنصوص عليها في الفقرة (أ) من هذه المادة ومدة عملها.","title":"تعيين جهة استشارية لتقييم البنك","memo":"⭐ للبنك المركزي، بناءً على مبررات ضرورية وعلى نفقة البنك، تعيين جهة استشارية مختصة ذات خبرة لتقييم أي جوانب من أنشطة البنك\n⭐ البنك المركزي يحدد مهمتها ومدة عملها","qs":[{"q":"نفقة الجهة الاستشارية التي يعينها البنك المركزي لتقييم جوانب أنشطة البنك تكون على:","o":["البنك المعني","البنك المركزي","مؤسسة ضمان الودائع","الخزينة العامة"],"a":0},{"q":"الجهة التي تحدد مهمة الجهة الاستشارية ومدة عملها هي:","o":["البنك المركزي","مجلس إدارة البنك","الهيئة العامة للبنك","مدقق الحسابات الخارجي"],"a":0}]},{"n":"62","chapter":"الحسابات والبيانات المالية","notes":[],"source":"أ- على البنك أن يقتطع سنويا لحساب الاحتياطي القانوني ما نسبته (%١٠) من أرباحه الصافية في المملكة، وأن يستمر في الاقتطاع حتى يبلغ هذا الاحتياطي ما يعادل رأسمال البنك المكتتب به، ويقابل هذا الاقتطاع الاحتياطي الإجباري المنصوص عليه في قانون الشركات.\nت-لا يجوز للبنك أن يوزع أرباحاً على المساهمين قبل تغطية كامل المصاريف التأسيسية والمصاريف التي لا تقابلها موجودات حقيقية وإطفاء أي خسائر لحقت به مهما كان نوعها، ويجوز تغطية هذه أي من تلك المصاريف دون الخسائر بموافقة البنك المركزي خلال مدة أقصاها خمس سنوات.","title":"الاحتياطي القانوني وتوزيع الأرباح","memo":"⭐ يقتطع البنك سنوياً (١٠%) من أرباحه الصافية في المملكة للاحتياطي القانوني حتى يعادل رأسماله المكتتب به\n⭐ لا توزيع أرباح قبل تغطية المصاريف التأسيسية والمصاريف غير المقابلة لموجودات حقيقية وإطفاء الخسائر\n⭐ يجوز تغطية المصاريف (دون الخسائر) بموافقة البنك المركزي خلال مدة أقصاها خمس سنوات","qs":[{"q":"النسبة التي يقتطعها البنك سنوياً من أرباحه الصافية في المملكة لحساب الاحتياطي القانوني هي:","o":["١٠%","٥%","١٥%","٢٠%"],"a":0},{"q":"يستمر البنك في الاقتطاع لحساب الاحتياطي القانوني حتى يبلغ هذا الاحتياطي ما يعادل:","o":["رأسمال البنك المكتتب به","نصف رأسمال البنك المكتتب به","ربع رأسمال البنك المصرح به","ضعف رأسمال البنك المدفوع"],"a":0},{"q":"يجوز بموافقة البنك المركزي تغطية المصاريف التأسيسية والمصاريف التي لا تقابلها موجودات حقيقية دون الخسائر خلال مدة أقصاها:","o":["خمس سنوات","ثلاث سنوات","سنتان","عشر سنوات"],"a":0}]},{"n":"63","chapter":"الحسابات والبيانات المالية","notes":[],"source":"على الرغم من أحكام أي تشريع آخر، يلتزم مجلس إدارة البنك بتقديم حساباته الختامية المصدقة من المدقق القانوني لحساباته إلى البنك المركزي خلال مدة لا تتجاوز الشهرين من نهاية السنة المالية، كما يلتزم مجلس الإدارة تحت طائلة المسؤولية القانونية بالحصول على موافقة خطية مسبقة من البنك المركزي على أي مما يلي:\nأ- الحسابات الختامية المصدق عليها من مدقق حساباته القانوني وذلك قبل عرضها على الهيئة العامة للمساهمين.\nب- إعلان هذه الحسابات ونشرها بأي وسيلة كانت.","title":"تقديم الحسابات الختامية للبنك المركزي","memo":"⭐ يقدم مجلس الإدارة الحسابات الختامية المصدقة من المدقق إلى البنك المركزي خلال مدة لا تتجاوز الشهرين من نهاية السنة المالية\n⭐ موافقة خطية مسبقة من البنك المركزي على الحسابات الختامية قبل عرضها على الهيئة العامة، وعلى إعلانها ونشرها","qs":[{"q":"يلتزم مجلس إدارة البنك بتقديم حساباته الختامية المصدقة إلى البنك المركزي خلال مدة لا تتجاوز:","o":["شهرين من نهاية السنة المالية","أربعة أشهر من نهاية السنة المالية","ستة أشهر من نهاية السنة المالية","شهر واحد من نهاية السنة المالية"],"a":0},{"q":"يجب الحصول على موافقة خطية مسبقة من البنك المركزي على الحسابات الختامية للبنك:","o":["قبل عرضها على الهيئة العامة للمساهمين","بعد مصادقة الهيئة العامة عليها","بعد نشرها في الصحف","قبل تصديقها من مدقق الحسابات"],"a":0},{"q":"إعلان الحسابات الختامية للبنك ونشرها بأي وسيلة يتطلب:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة مراقب الشركات","موافقة هيئة الأوراق المالية فقط","إشعار لاحق للبنك المركزي"],"a":0}]},{"n":"64","chapter":"الحسابات والبيانات المالية","notes":[],"source":"يحظر على البنك توزيع أي أرباح على المساهمين من عناصر رأس المال التنظيمي إذا كان من شأن هذا التوزيع أن يؤدي إلى عدم التقيد بالحد الأدنى المطلوب لرأس المال التنظيمي.","title":"حظر التوزيع من رأس المال التنظيمي","memo":"⭐ يحظر توزيع أرباح من عناصر رأس المال التنظيمي إذا أدى ذلك إلى عدم التقيد بالحد الأدنى المطلوب لرأس المال التنظيمي","qs":[{"q":"يحظر على البنك توزيع أي أرباح على المساهمين من عناصر رأس المال التنظيمي إذا:","o":["أدى التوزيع إلى عدم التقيد بالحد الأدنى المطلوب لرأس المال التنظيمي","لم يمض على تأسيس البنك خمس سنوات","تجاوزت الأرباح ١٠% من رأس المال","لم توافق عليه هيئة الأوراق المالية"],"a":0},{"q":"الأرباح التي يحظر على البنك توزيعها على المساهمين وفق هذه المادة هي الأرباح الموزعة من:","o":["عناصر رأس المال التنظيمي إذا أخل التوزيع بالحد الأدنى المطلوب له","الأرباح الصافية للسنة الجارية بعد اقتطاع الاحتياطي القانوني","الأرباح المدورة من سنوات سابقة إذا وافق البنك المركزي","الاحتياطيات الاختيارية بقرار من الهيئة العامة"],"a":0}]},{"n":"65","chapter":"الحسابات والبيانات المالية","notes":[],"source":"على الرغم من أحكام أي تشريع آخر، لا يجوز للهيئة العامة لمساهمي البنك أن تقرر توزيع أي أرباح على المساهمين تزيد على ما وافق عليه البنك المركزي.","title":"سقف توزيع الأرباح","memo":"⭐ لا يجوز للهيئة العامة لمساهمي البنك توزيع أرباح تزيد على ما وافق عليه البنك المركزي، على الرغم من أي تشريع آخر","qs":[{"q":"حالة عملية: وافق البنك المركزي على توزيع أرباح بنسبة ٨%، وقررت الهيئة العامة للبنك توزيع ١٠%. وفق القانون:","o":["لا يجوز للهيئة العامة توزيع أرباح تزيد على ما وافق عليه البنك المركزي","يجوز ذلك لأن الهيئة العامة صاحبة القرار النهائي","يجوز بموافقة مراقب الشركات","يجوز إذا وافق مدقق الحسابات"],"a":0},{"q":"الجهة التي لا يجوز لها أن تقرر توزيع أرباح تزيد على ما وافق عليه البنك المركزي هي:","o":["الهيئة العامة لمساهمي البنك","مؤسسة ضمان الودائع","مدقق الحسابات الخارجي","هيئة الأوراق المالية"],"a":0}]},{"n":"66","chapter":"الحسابات والبيانات المالية","notes":[],"source":"مع مراعاة أحكام المادة (٦٣) من هذا القانون، يلتزم البنك بعد مصادقة الهيئة العامة لمساهميه على حساباته الختامية عن السنة المالية المنتهية بما يلي:\nأ- نشر حساباته الختامية وتقرير مدقق حساباته في صحيفتين يوميتين محليتين خلال مدة أقصاها ستة أشهر من انتهاء تلك السنة المالية، وكذلك نشر حساباته الختامية الإجمالية وفق ما تقدم إلى جانب حساباته الختامية في المملكة إذا كان له فروع خارجها.\nب-عرض حساباته الختامية المنصوص عليها في الفقرة (أ) من هذه المادة مع قائمة بأسماء أعضاء مجلس إدارته في مكان بارز في مكاتبه وفروعه لمدة ثلاثة أشهر على الأقل خلال السنة المالية التالية للسنة المالية المنتهية.","title":"نشر الحسابات الختامية وعرضها","memo":"⭐ بعد مصادقة الهيئة العامة: نشر الحسابات الختامية وتقرير المدقق في صحيفتين يوميتين محليتين خلال مدة أقصاها ستة أشهر من انتهاء السنة المالية\n⭐ إذا كان له فروع خارج المملكة ينشر الحسابات الإجمالية إلى جانب حساباته في المملكة\n⭐ عرض الحسابات مع أسماء أعضاء مجلس الإدارة في مكان بارز في مكاتبه وفروعه مدة ثلاثة أشهر على الأقل","qs":[{"q":"ينشر البنك حساباته الختامية وتقرير مدقق حساباته في:","o":["صحيفتين يوميتين محليتين","الجريدة الرسمية فقط","صحيفة يومية واحدة","ثلاث صحف يومية"],"a":0},{"q":"المدة القصوى لنشر البنك حساباته الختامية من انتهاء السنة المالية هي:","o":["ستة أشهر","شهران","أربعة أشهر","ثلاثة أشهر"],"a":0},{"q":"يعرض البنك حساباته الختامية مع قائمة بأسماء أعضاء مجلس إدارته في مكان بارز في مكاتبه وفروعه لمدة لا تقل عن:","o":["ثلاثة أشهر","شهر واحد","ستة أشهر","سنة كاملة"],"a":0}]},{"n":"67","chapter":"الحسابات والبيانات المالية","notes":[],"source":"على فرع البنك الأجنبي أن ينشر الحسابات الختامية الإجمالية للشركة الأم وفروعها خارج المملكة، وذلك إلى جانب حساباته الختامية الخاصة به داخل المملكة.","title":"نشر حسابات فرع البنك الأجنبي","memo":"⭐ فرع البنك الأجنبي ينشر الحسابات الختامية الإجمالية للشركة الأم وفروعها خارج المملكة إلى جانب حساباته الخاصة داخل المملكة","qs":[{"q":"يلتزم فرع البنك الأجنبي بأن ينشر إلى جانب حساباته الختامية الخاصة به داخل المملكة:","o":["الحسابات الختامية الإجمالية للشركة الأم وفروعها خارج المملكة","تقرير البنك المركزي في دولة المقر","قائمة بأسماء مساهمي الشركة الأم","حسابات فروع البنوك الأجنبية الأخرى في المملكة"],"a":0}]},{"n":"68","chapter":"الحسابات والبيانات المالية","notes":[],"source":"على البنك أن يزود البنك المركزي بنسخة من تقريره السنوي المتضمن ما يلي:\nأ- البيانات التي يقتضيها قانون الشركات وقانون الأوراق المالية والتعليمات الصادرة بموجبهما.\nب- مقدار المساهمات في رأس المال العائد لكل من رئيس وأعضاء مجلس إدارة البنك وأقربائهم حتى الدرجة الثالثة.","title":"التقرير السنوي للبنك","memo":"⭐ يزود البنك المركزي بنسخة من تقريره السنوي متضمناً بيانات قانون الشركات وقانون الأوراق المالية\n⭐ ومقدار مساهمات رئيس وأعضاء مجلس الإدارة وأقربائهم حتى الدرجة الثالثة في رأس المال","qs":[{"q":"يتضمن التقرير السنوي للبنك مقدار المساهمات في رأس المال العائد لرئيس وأعضاء مجلس الإدارة وأقربائهم حتى:","o":["الدرجة الثالثة","الدرجة الثانية","الدرجة الرابعة","الدرجة الأولى"],"a":0},{"q":"يتضمن التقرير السنوي الذي يزود به البنك المركزي البيانات التي يقتضيها:","o":["قانون الشركات وقانون الأوراق المالية والتعليمات الصادرة بموجبهما","قانون التجارة وقانون الضريبة","قانون العمل وقانون الضمان الاجتماعي","قانون المعاملات الإلكترونية فقط"],"a":0}]},{"n":"69","chapter":"الحسابات والبيانات المالية","notes":[],"source":"على البنك التقيد بأوامر البنك المركزي المتعلقة بتزويده بما يلي:\nأ- بيان عن الوضع المالي للبنك ومقدار السيولة لديه وملاءته وأرباحه وعملياته وأوضاعه الإدارية بما في ذلك مكافآت أعضاء مجلس الإدارة وكبار الإداريين الذين يحددهم البنك المركزي.\nب-بيانات الحسابات الختامية للشركات التابعة له وتقارير عن أوضاعها المالية.","title":"البيانات الدورية للبنك المركزي","memo":"⭐ يلتزم البنك بأوامر البنك المركزي بتزويده ببيان عن الوضع المالي والسيولة والملاءة والأرباح والأوضاع الإدارية بما فيها مكافآت أعضاء المجلس وكبار الإداريين\n⭐ وبيانات الحسابات الختامية للشركات التابعة وتقارير عن أوضاعها المالية","qs":[{"q":"يشمل البيان الذي يزود به البنك البنك المركزي عن أوضاعه الإدارية مكافآت:","o":["أعضاء مجلس الإدارة وكبار الإداريين الذين يحددهم البنك المركزي","جميع موظفي البنك دون استثناء","المساهمين الرئيسيين","مدققي الحسابات الخارجيين"],"a":0},{"q":"يلتزم البنك بتزويد البنك المركزي، بخصوص الشركات التابعة له، بـ:","o":["بيانات حساباتها الختامية وتقارير عن أوضاعها المالية","قوائم بأسماء موظفيها فقط","محاضر هيئاتها العامة فقط","خطط تسويقها السنوية"],"a":0}]},{"n":"70","chapter":"التفتيش والتدقيق","notes":[],"source":"أ- يخضع البنك وأي شركة تابعة له للتفتيش من قبل البنك المركزي أو مدققي الحسابات الذين يعينهم البنك المركزي لهذه الغاية على نفقة ذلك البنك، ويلتزم البنك والشركات التابعة له بالتعاون معهم بما يمكنهم من القيام بأعمالهم بشكل كامل.\nب- إذا كان البنك المراد تفتيشه فرعاً لبنك أجنبي أو شركة تابعة لبنك أجنبي، فانه يخضع أيضاً لتفتيش الجهات المسؤولة عن رقابته والإشراف عليه في بلد مقره الرئيسي أو الإقليمي وذلك إضافة إلى تفتيش البنك المركزي له.\nج- يحق للبنك المركزي والمدققين المعينين من قبله أثناء تفتيشهم للبنك وأي شركة تابعة له القيام بما يلي:\n١- فحص أي حسابات وسجلات ووثائق بما في ذلك محاضر اجتماعات وقرارات مجلس الإدارة ولجنة التدقيق والحصول على صور عنها.\n٢- التأكد من أن البيانات الحسابية لفرع البنك الأجنبي العامل في المملكة تتضمن الميزانية المجمعة والحسابات الختامية وبيان الدخل للشركة الأم وفروعها في الدول الأخرى .\n٣- الطلب من إداريي ووكلاء البنك وشركاته التابعة تزويدهم بأي معلومات يراها البنك المركزي أو المدققون المعينون لازمة لهذه الغاية.","title":"التفتيش على البنوك","memo":"⭐ يخضع البنك وشركاته التابعة لتفتيش البنك المركزي أو المدققين الذين يعينهم على نفقة البنك\n⭐ فرع البنك الأجنبي يخضع أيضاً لتفتيش الجهات الرقابية في بلد مقره الرئيسي أو الإقليمي\n⭐ للمفتشين فحص الحسابات والسجلات ومحاضر مجلس الإدارة ولجنة التدقيق والحصول على صور عنها","qs":[{"q":"نفقة التفتيش الذي يجريه مدققو الحسابات المعينون من البنك المركزي على البنك تكون على:","o":["البنك الخاضع للتفتيش","البنك المركزي","مؤسسة ضمان الودائع","جمعية البنوك"],"a":0},{"q":"يخضع فرع البنك الأجنبي العامل في المملكة للتفتيش من قبل:","o":["البنك المركزي إضافة إلى الجهات المسؤولة عن رقابته في بلد مقره الرئيسي أو الإقليمي","البنك المركزي فقط","الجهات الرقابية في بلد المقر فقط","مراقب الشركات فقط"],"a":0},{"q":"يتأكد المفتشون من أن البيانات الحسابية لفرع البنك الأجنبي العامل في المملكة تتضمن:","o":["الميزانية المجمعة والحسابات الختامية وبيان الدخل للشركة الأم وفروعها في الدول الأخرى","حسابات الفرع داخل المملكة فقط","قائمة مساهمي الشركة الأم فقط","تقارير التدقيق الداخلي للفرع فقط"],"a":0}]},{"n":"71","chapter":"التفتيش والتدقيق","notes":[],"source":"للبنك المركزي أن يصدر الأوامر التي تمكن مفتشيه ومندوبيه من زيارة مكاتب الشركات المالية وفحص حساباتها وسجلاتها ووثائقها واتخاذ الإجراءات التي يراها ضرورية للتحقق من أن أعمالها وأنشطتها لا تتعارض مع أحكام هذا القانون.","title":"التفتيش على الشركات المالية","memo":"⭐ للبنك المركزي إصدار أوامر تمكن مفتشيه من زيارة مكاتب الشركات المالية وفحص حساباتها للتحقق من عدم تعارض أعمالها مع القانون","qs":[{"q":"الغاية من صلاحية البنك المركزي في زيارة مكاتب الشركات المالية وفحص حساباتها هي التحقق من:","o":["أن أعمالها وأنشطتها لا تتعارض مع أحكام قانون البنوك","تحقيقها أرباحاً كافية","التزامها بقانون العمل","صحة إقراراتها الضريبية"],"a":0},{"q":"تمارس صلاحية زيارة مكاتب الشركات المالية وفحص سجلاتها بموجب أوامر يصدرها:","o":["البنك المركزي","مراقب الشركات","وزير الصناعة والتجارة","جمعية البنوك"],"a":0}]},{"n":"72","chapter":"السرية المصرفية","notes":[],"source":"على البنك مراعاة السرية التامة لجميع حسابات العملاء وودائعهم وأماناتهم وخزائنهم لديه ويحظر إعطاء أي بيانات عنها بطريق مباشر أو غير مباشر إلا بموافقة خطية من صاحب الحساب أو الوديعة أو الأمانة أو الخزانة أو من أحد ورثته أو بقرار من جهة قضائية مختصة في خصومة قضائية قائمة أو بسبب إحدى الحالات المسموح بها بمقتضى أحكام هذا القانون، ويظل الحظر قائماً حتى ولو انتهت العلاقة بين العميل والبنك لأي سبب من الأسباب.","title":"السرية المصرفية على البنك","memo":"⭐ سرية تامة لحسابات العملاء وودائعهم وأماناتهم وخزائنهم\n⭐ الاستثناء: موافقة خطية من صاحب الحساب أو أحد ورثته، أو قرار جهة قضائية مختصة في خصومة قضائية قائمة، أو حالة مسموح بها قانوناً\n⭐ يظل الحظر قائماً ولو انتهت العلاقة بين العميل والبنك","qs":[{"q":"يجوز للبنك إعطاء بيانات عن حساب عميل بموافقة خطية من:","o":["صاحب الحساب أو أحد ورثته","مدير فرع البنك","أي دائن للعميل","أي جهة حكومية"],"a":0},{"q":"يجوز للبنك الكشف عن بيانات حساب العميل بقرار من جهة قضائية مختصة بشرط أن يكون ذلك في:","o":["خصومة قضائية قائمة","أي تحقيق إداري","أي نزاع محتمل مستقبلاً","طلب من النيابة الإدارية"],"a":0},{"q":"حالة عملية: أغلق عميل حسابه لدى البنك منذ سنتين، وطلب شخص آخر معلومات عن ذلك الحساب. وفق القانون:","o":["يظل حظر الإفصاح قائماً رغم انتهاء العلاقة","يزول الحظر بانتهاء العلاقة بين العميل والبنك","يزول الحظر بعد مرور سنة على إغلاق الحساب","يجوز الإفصاح بموافقة مدير البنك"],"a":0}]},{"n":"73","chapter":"السرية المصرفية","notes":[],"source":"يحظر على أي من إداريي البنك الحاليين أو السابقين إعطاء أي معلومات أو بيانات عن العملاء أو حساباتهم أو ودائعهم أو الأمانات أو الخزائن الخاصة بهم أو أي من معاملاتهم أو كشفها أو تمكين الغير من الاطلاع عليها في غير الحالات المسموح بها بمقتضى أحكام هذا القانون، ويسري هذا الحظر على كل من يطلع بحكم مهنته أو وظيفته أو عمله بطريق مباشر أو غير مباشر على تلك البيانات والمعلومات بما في ذلك موظفي البنك المركزي ومدققي الحسابات.","title":"حظر إفشاء الأسرار على الإداريين","memo":"⭐ يحظر على إداريي البنك الحاليين أو السابقين إفشاء معلومات العملاء في غير الحالات المسموح بها\n⭐ يسري الحظر على كل من يطلع عليها بحكم مهنته أو وظيفته بما في ذلك موظفو البنك المركزي ومدققو الحسابات","qs":[{"q":"يسري حظر إفشاء المعلومات الخاصة بالعملاء على إداريي البنك:","o":["الحاليين والسابقين","الحاليين فقط","السابقين خلال سنة من تركهم العمل فقط","أعضاء مجلس الإدارة فقط"],"a":0},{"q":"أي مما يلي يسري عليه حظر إفشاء معلومات عملاء البنك؟","o":["موظفو البنك المركزي ومدققو الحسابات الذين يطلعون عليها بحكم عملهم","العملاء أنفسهم بخصوص حساباتهم","الورثة بخصوص حسابات مورثهم بعد موافقتهم","لا يسري على أي شخص من خارج البنك"],"a":0}]},{"n":"74","chapter":"السرية المصرفية","notes":[],"source":"يستثنى من أحكام المادتين (٧٢) و(٧٣) من هذا القانون أي من الحالات التالية:\nأ- الواجبات المنوط أداؤها قانونا بمدققي الحسابات الذين تعينهم الهيئة العامة للبنك أو البنك المركزي وفق أحكام هذا القانون.\nب- الأعمال والإجراءات التي يقوم بها البنك المركزي بموجب أحكام هذا القانون أو قانون البنك المركزي.\nج- إصدار شهادة أو بيان بأسباب رفض صرف أي شيك بناءً على طلب صاحب الحق.\nد- تبادل المعلومات المتعلقة بالعملاء سواءً بخصوص مديونياتهم لتوفير البيانات اللازمة لسلامة منح الائتمان أو بخصوص الشيكات المرتجعة بدون تسديد أو أي أعمال أخرى يراها البنك المركزي لازمة لتعلقها بسلامة العمل المصرفي وذلك فيما بين البنوك والبنك المركزي وأي شركات أو جهات أخرى يوافق عليها البنك المركزي لتسهيل تبادل هذه المعلومات.\nه- كشف البنك عن كل أو بعض البيانات الخاصة بمعاملات العميل اللازمة لإثبات حقه في نزاع قضائي نشأ بينه وبين عميله بشأن هذه المعاملات.","title":"استثناءات السرية المصرفية","memo":"⭐ يستثنى: واجبات المدققين المعينين من الهيئة العامة أو البنك المركزي، وأعمال البنك المركزي بموجب القانون\n⭐ إصدار شهادة بأسباب رفض صرف شيك بطلب صاحب الحق\n⭐ تبادل المعلومات بين البنوك والبنك المركزي والجهات التي يوافق عليها حول المديونيات والشيكات المرتجعة\n⭐ كشف البنك ما يلزم لإثبات حقه في نزاع قضائي بينه وبين عميله","qs":[{"q":"يستثنى من أحكام السرية المصرفية إصدار شهادة أو بيان بأسباب رفض صرف أي شيك بناءً على طلب:","o":["صاحب الحق","الساحب فقط","أي جهة إعلامية","أي بنك آخر"],"a":0},{"q":"أي مما يلي لا يعد من الحالات المستثناة من السرية المصرفية؟","o":["تزويد شركة تسويق بقوائم العملاء دون موافقتهم","تبادل المعلومات بين البنوك والبنك المركزي حول الشيكات المرتجعة","كشف البنك بيانات العميل اللازمة لإثبات حقه في نزاع قضائي معه","الأعمال التي يقوم بها البنك المركزي بموجب قانون البنك المركزي"],"a":0},{"q":"تبادل المعلومات المتعلقة بمديونيات العملاء يكون بين البنوك والبنك المركزي وأي جهات أخرى:","o":["يوافق عليها البنك المركزي","تعينها جمعية البنوك","يختارها البنك المعني","يحددها وزير المالية"],"a":0}]},{"n":"75","chapter":"السرية المصرفية","notes":[],"source":"يعاقب كل من يخالف أحكام أي من المادتين (٧٢) و (٧٣) من هذا القانون بالحبس مدة لا تقل عن ستة أشهر أو بغرامة مالية لا تقل عن عشرة آلاف دينار ولا تزيد على خمسين ألف دينار أو بكلتا العقوبتين.","title":"عقوبة إفشاء السرية المصرفية","memo":"⭐ الحبس مدة لا تقل عن ستة أشهر أو غرامة لا تقل عن (١٠٠٠٠) دينار ولا تزيد على (٥٠٠٠٠) دينار أو بكلتا العقوبتين","qs":[{"q":"الحد الأدنى لعقوبة الحبس لمن يخالف أحكام السرية المصرفية هو:","o":["ستة أشهر","ثلاثة أشهر","سنة واحدة","شهر واحد"],"a":0},{"q":"الغرامة المقررة على مخالفة أحكام السرية المصرفية هي:","o":["لا تقل عن عشرة آلاف دينار ولا تزيد على خمسين ألف دينار","لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار","لا تقل عن خمسين ألف دينار ولا تزيد على مائة ألف دينار","لا تزيد على خمسمائة ألف دينار"],"a":0}]},{"n":"76","chapter":"اندماج البنوك","notes":[],"source":"أ- يسري على اندماج البنوك الأحكام المتعلقة باندماج الشركات الواردة في قانون الشركات الساري المفعول وذلك فيما لم يرد عليه نص خاص في هذا الفصل.\nب- لا يجوز للبنك أن يشرع في أي إجراء تنفيذي من إجراءات الاندماج قبل الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"أحكام اندماج البنوك","memo":"⭐ يسري على اندماج البنوك أحكام اندماج الشركات في قانون الشركات فيما لم يرد عليه نص خاص\n⭐ لا يجوز الشروع في أي إجراء تنفيذي للاندماج قبل موافقة خطية مسبقة من البنك المركزي","qs":[{"q":"يسري على اندماج البنوك فيما لم يرد عليه نص خاص في قانون البنوك أحكام:","o":["قانون الشركات الساري المفعول","قانون التجارة","قانون البنك المركزي","قانون الأوراق المالية"],"a":0},{"q":"لا يجوز للبنك أن يشرع في أي إجراء تنفيذي من إجراءات الاندماج قبل الحصول على:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة مجلس الوزراء","موافقة جمعية البنوك","موافقة مؤسسة ضمان الودائع"],"a":0}]},{"n":"77","chapter":"اندماج البنوك","notes":[],"source":"إذا وافقت الهيئة العامة للبنك على الاندماج وفقاً لأحكام قانون الشركات، يعتبر هذا القرار ملزماً لجميع المساهمين، ويقتصر حق المتضرر على المطالبة بالتعويض.","title":"إلزامية قرار الاندماج","memo":"⭐ قرار الهيئة العامة بالموافقة على الاندماج ملزم لجميع المساهمين، ويقتصر حق المتضرر على المطالبة بالتعويض","qs":[{"q":"حالة عملية: اعترض مساهم على قرار الهيئة العامة للبنك بالموافقة على الاندماج. وفق القانون فإن حقه يقتصر على:","o":["المطالبة بالتعويض","إبطال قرار الاندماج","وقف إجراءات الاندماج","استرداد قيمة أسهمه من البنك المركزي"],"a":0}]},{"n":"78","chapter":"اندماج البنوك","notes":[],"source":"يعين البنك المركزي الخبراء والمختصين الذي سيشتركون في لجنة التقدير التي يشكلها وزير الصناعة والتجارة بمقتضى قانون الشركات لإتمام الاندماج.","title":"لجنة تقدير الاندماج","memo":"⭐ البنك المركزي يعين الخبراء والمختصين المشاركين في لجنة التقدير التي يشكلها وزير الصناعة والتجارة بمقتضى قانون الشركات","qs":[{"q":"لجنة التقدير اللازمة لإتمام اندماج البنوك يشكلها:","o":["وزير الصناعة والتجارة ويعين البنك المركزي الخبراء المشاركين فيها","البنك المركزي منفرداً","مجلس إدارة البنك الدامج","المحكمة المختصة"],"a":0}]},{"n":"79","chapter":"اندماج البنوك","notes":[],"source":"أ- مع مراعاة أحكام قانون الشركات، ينتقل حكماً إلى البنك الدامج أو الناتج من الاندماج ما يلي:\n١- جميع الحسابات والودائع ومختلف أنواع التسهيلات المصرفية القائمة لدى البنك المندمج وجميع تأميناتها الشخصية والعينية، وذلك دون حاجة للحصول على موافقة أي عميل أو كفيل أو راهن أو مستفيد أو أي شخص آخر.\n٢- جميع حقوق والتزامات البنك المندمج سواءً بموجب عقود إيجار أو عقود عمل أو أي عقود أخرى مهما كانت.\nب- يحل البنك الدامج أو الناتج من الاندماج محل البنك المندمج في جميع الأمور والإجراءات بما في ذلك الدعاوى والإجراءات القضائية المقامة من قبله أو ضده.","title":"آثار الاندماج","memo":"⭐ تنتقل حكماً للبنك الدامج جميع الحسابات والودائع والتسهيلات وتأميناتها دون حاجة لموافقة أي عميل أو كفيل أو راهن\n⭐ تنتقل جميع حقوق والتزامات البنك المندمج بموجب عقود الإيجار والعمل وغيرها\n⭐ يحل البنك الدامج محل المندمج في جميع الأمور والإجراءات بما فيها الدعاوى","qs":[{"q":"تنتقل الحسابات والودائع والتسهيلات المصرفية القائمة لدى البنك المندمج إلى البنك الدامج:","o":["حكماً دون حاجة للحصول على موافقة أي عميل أو كفيل أو راهن","بشرط موافقة كل عميل خطياً","بعد موافقة الكفلاء والراهنين فقط","بقرار من المحكمة المختصة"],"a":0},{"q":"الدعاوى القضائية المقامة من البنك المندمج أو ضده بعد الاندماج:","o":["يحل فيها البنك الدامج أو الناتج من الاندماج محل البنك المندمج","تسقط بحكم القانون","يجب إعادة رفعها من جديد","تبقى مقصورة على مساهمي البنك المندمج"],"a":0}]},{"n":"80","chapter":"اندماج البنوك","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، للمجلس في حال تعرض بنك لمشاكل ذات أثر جوهري في مركزه المالي أن يتخذ إجراء أو أكثر من الإجراءات التالية:\n١- حل مجلس إدارة البنك وتولي إدارته لمدة لا تزيد على اثني عشر شهراً، وتكون قابلة للتمديد لمرة واحدة.\n٢- إعادة هيكلة رأسمال البنك بتخفيض رأسماله المكتتب به وزيادته بالاكتتاب بأسهم جديدة أو باستعمال احتياطاته الاختيارية أو أرباحه المدورة أو بأي وسيلة أخرى يراها مناسبة.\n٣- استعمال أي من عناصر رأس المال التنظيمي لتقوية المركز المالي للبنك بما في ذلك زيادة رأسماله أو أطفاء خسائره.\n٤- ادماج البنك في بنك آخر بموافقة البنك الذي يتم الاندماج فيه.\n٥- إحالة جميع أو بعض موجودات البنك وحقوقه ومطلوباته والتزاماته إلى شخص ثالث بالبدل وبالشروط التي يراها البنك المركزي مناسبة دون الحصول على موافقة المدين أو العميل أو الراهن أو الكفيل أو أي شخص ذي علاقة.\nب- مع مراعاة ما ورد في قانون مؤسسة ضمان الودائع إذا تبين للمؤسسة أن كلفة تصفية البنك قد تزيد على كلفة أي من الإجراءات الواردة في البندين (٤) و (٥) من الفقرة (أ) من هذه المادة فلها أن تقوم بموافقة البنك المركزي وبالشروط التي يحددها باتخاذ أحد الإجراءين التاليين أو كليهما:\n١- تحمل الكلفة المالية المترتبة على اتخاذ أي من الإجراءات المشار إليها في البندين (٤) و (٥) من الفقرة (أ) من هذه المادة.\n٢- الاكتتاب في أي أسهم جديدة يتم طرحها لزيادة رأسمال البنك.\nج- لمؤسسة ضمان الودائع الطلب من البنك المركزي ترخيص بنك تجسيري يحال له ما ورد في البند (٥) من الفقرة (أ) من هذه المادة مع مراعاة ما يلي:\n١- يحدد المجلس إجراءات وشروط ترخيص البنك التجسيري واستثنائه من أي من الأحكام الواردة في المواد من (٦) إلى (٢٠) من هذا القانون.\n٢- يمارس البنك التجسيري الأعمال المصرفية لمدة لا تزيد على ستة وثلاثين شهراً لتنفيذ أي مما يلي:\nأ- بيع رأسمال البنك التجسيري إلى مساهمين جدد، وفي هذه الحالة يتعين مراعاة الشروط والأحكام الواجبة التطبيق على البنوك العاملة في المملكة بما في ذلك أحكام ترخيصها وإداراتها وتنظيمها.\nب- بيع جميع أو بعض موجودات البنك التجسيري وحقوقه ومطلوباته والتزاماته وفق أحكام المادة (٨٢) من هذا القانون.\n٣- تستعمل حصيلة البيع الناتج من تطبيق أحكام البند (٢) من هذه الفقرة لتغطية أي كلف مالية تحملها البنك المركزي ومؤسسة ضمان الودائع نتيجة للإجراءات المتخذة وفق أحكام هذه المادة، ويؤول ما يزيد على ذلك إلى موجودات البنك الذي تعرض لمشاكل جوهرية.\nد- تكون القرارات والموافقات التي يصدرها البنك المركزي وفق أحكام الفقرتين (أ) و (ب) من هذه المادة بمثابة القرارات اللازم صدورها بمقتضى أحكام التشريعات النافذة عن مجلس إدارة البنك وهيئته العامة العادية وهيئته العامة غير العادية لغايات تنفيذ الإجراءات المنصوص عليها في هاتين الفقرتين.\nه - ١- تكون القرارات المتخذة وفق أحكام هذه المادة قابلة للطعن لدى المحكة الإدارية وفق الشروط المنصوص عليها في المادة (٨٦) من هذا القانون.\n٢- لا يترتب على الطعن في القرارات المشار إليها في البند (١) من هذه الفقرة وقف تنفيذها.\nو- يشكل البنك المركزي لجنة خاصة أو أكثر تقتضيها أحكام التشريعات النافذة لتنفيذ الإجراءات المنصوص عليها في الفقرتين (أ) و (ب) من هذه المادة، ويكون البنك المركزي الجهة المختصة بمتابعة أعمال تلك اللجنة واعتماد نتائج أعمالها.\nز- ١- على الرغم مما ورد في أي تشريع آخر، لا تسري على فرع البنك الأجنبي المرخص له بالعمل في المملكة أي قرارات أو إجراءات صادرة عن السلطات المختصة في الدولة التي يقع فيها مركز إداراته الرئيسي سواء تعلقت تلك القرارات بالتصفية أو الإفلاس أو معالجة اوضاع البنك المتعثر.\n٢- للبنك المركزي وبعد التحقق من أن أياً من الإجراءات المنصوص عليها في الفقرة (أ) من هذه المادة غير مجحف بحق المتعاملين مع فرع البنك الأجنبي ولا يؤثر على الاستقرار المالي والمصرفي في المملكة أن يوافق على امتداد الآثار المترتبة على تلك الإجراءات لتشمل فرع البنك الأجنبي وفق الترتيبات التي يحددها البنك المركزي بالتنسيق مع تلك السلطات المختصة أو وفق الترتيبات المنصوص عليها في الاتفاقيات التي تربط المملكة مع تلك الدولة إن وجدت.","title":"معالجة البنك المتعثر","memo":"⭐ للمجلس عند تعرض بنك لمشاكل جوهرية: حل مجلس إدارته وتولي إدارته مدة لا تزيد على اثني عشر شهراً قابلة للتمديد لمرة واحدة\n⭐ إعادة هيكلة رأس المال، الدمج في بنك آخر بموافقته، إحالة الموجودات والمطلوبات لطرف ثالث دون موافقة المدين\n⭐ البنك التجسيري: تطلبه مؤسسة ضمان الودائع، ويعمل لمدة لا تزيد على ستة وثلاثين شهراً\n⭐ الطعن لدى المحكمة الإدارية ولا يوقف التنفيذ؛ ولا تسري على فرع البنك الأجنبي قرارات سلطات دولة مقره","qs":[{"q":"المدة القصوى لتولي إدارة البنك بعد حل مجلس إدارته وفق إجراءات معالجة البنك المتعثر هي:","o":["اثنا عشر شهراً قابلة للتمديد لمرة واحدة","أربعة وعشرون شهراً قابلة للتمديد حسب الضرورة","ستة أشهر غير قابلة للتمديد","ستة وثلاثون شهراً"],"a":0},{"q":"يمارس البنك التجسيري الأعمال المصرفية لمدة لا تزيد على:","o":["ستة وثلاثين شهراً","اثني عشر شهراً","أربعة وعشرين شهراً","ستين شهراً"],"a":0},{"q":"الجهة التي تطلب من البنك المركزي ترخيص بنك تجسيري هي:","o":["مؤسسة ضمان الودائع","مجلس إدارة البنك المتعثر","وزير المالية","جمعية البنوك"],"a":0},{"q":"يترتب على الطعن في القرارات المتخذة وفق أحكام معالجة البنك المتعثر أمام المحكمة الإدارية:","o":["عدم وقف تنفيذ تلك القرارات","وقف تنفيذها حكماً","وقف تنفيذها لمدة ثلاثين يوماً","إلغاؤها مؤقتاً لحين الفصل"],"a":0}]},{"n":"81","chapter":"اندماج البنوك","notes":[],"source":"للبنك المركزي أن يمنح حوافز لتشجيع الاندماج بما فيها تقديم القروض الميسرة وذلك بالشروط والضمانات التي يقررها.","title":"حوافز تشجيع الاندماج","memo":"⭐ للبنك المركزي منح حوافز لتشجيع الاندماج بما فيها القروض الميسرة بالشروط والضمانات التي يقررها","qs":[{"q":"من الحوافز التي يجوز للبنك المركزي منحها لتشجيع اندماج البنوك:","o":["تقديم القروض الميسرة","الإعفاء من الضريبة لمدة عشر سنوات","الإعفاء من التفتيش","الإعفاء من متطلبات رأس المال"],"a":0}]},{"n":"82","chapter":"اندماج البنوك","notes":[],"source":"أ- يجوز لأي بنك بموافقة مسبقة من البنك المركزي أن يشتري جميع أو بعض موجودات بنك آخر وحقوقه أو مطلوباته والتزاماته بما في ذلك:\n١- أي تسهيلات مصرفية منحها البنك لعملائه أو تعهدات أصدرها لصالح مستفيدين وجميع تأميناتها الشخصية والعينية وذلك دون حاجة للحصول على موافقة أي عميل أو كفيل أو راهن أو مستفيد أو أي شخص آخر ودون حاجة للتقيد بأي إجراءات تقييم أو خلافه قد ينص عليها أي تشريع آخر.\n٢- أي حقوق أو التزامات أخرى مهما كان نوعها بما فيها حقوق الإجارة وإذا كان بدل هذه الإجارة أقل من أجر المثل يعدل ليصبح مساويا لأجر المثل.\nب- يكون للشراء الحاصل بموجب أحكام الفقرة (أ) من هذه المادة حكم الاندماج لغايات الاستفادة من إعفاءات الاندماج ومزاياه المنصوص عليها في هذا القانون وقانون الشركات النافذ المفعول، ولهذه الغاية تسري على البنك البائع أحكام البنك المندمج وعلى البنك المشتري أحكام البنك الدامج أو الناتج عن الاندماج.","title":"شراء موجودات بنك آخر","memo":"⭐ يجوز لأي بنك بموافقة مسبقة من البنك المركزي شراء جميع أو بعض موجودات وحقوق أو مطلوبات والتزامات بنك آخر\n⭐ دون حاجة لموافقة العميل أو الكفيل أو الراهن ودون التقيد بإجراءات التقييم\n⭐ حقوق الإجارة: إذا كان البدل أقل من أجر المثل يعدل ليصبح مساوياً لأجر المثل\n⭐ للشراء حكم الاندماج للاستفادة من إعفاءاته ومزاياه","qs":[{"q":"يشترط لشراء بنك جميع أو بعض موجودات بنك آخر الحصول على:","o":["موافقة مسبقة من البنك المركزي","موافقة جميع عملاء البنك البائع","موافقة وزير الصناعة والتجارة","موافقة مؤسسة ضمان الودائع"],"a":0},{"q":"حالة عملية: اشترى بنك حقوق إجارة من بنك آخر وكان بدل الإجارة أقل من أجر المثل. وفق القانون:","o":["يعدل البدل ليصبح مساوياً لأجر المثل","يبقى البدل كما هو دون تعديل","يفسخ عقد الإجارة حكماً","يعدل البدل بقرار من المحكمة فقط"],"a":0},{"q":"يكون لشراء موجودات بنك آخر وفق القانون حكم:","o":["الاندماج لغايات الاستفادة من إعفاءاته ومزاياه","التصفية الاختيارية","البيع التجاري العادي","الحوالة المدنية"],"a":0}]},{"n":"83","chapter":"اندماج البنوك","notes":[],"source":"مع مراعاة الأحكام الخاصة بالسرية المصرفية، يحق لرؤساء مجالس إدارات البنوك الراغبة في الاندماج أو الشراء بموجب أحكام هذا القانون أو من يفوضونهم بتفويض خاص لهذه الغاية أن يتبادلوا فيما بينهم المعلومات الضرورية المتعلقة بأعمال بنوكهم لاستكمال دراسة الاندماج أو الشراء، ويعتبر هؤلاء الأشخاص مسؤولين شخصياً عن المحافظة على سرية المعلومات التي يطلعون عليها بهذا الخصوص تحت طائلة المساءلة القانونية.","title":"تبادل المعلومات لغايات الاندماج","memo":"⭐ لرؤساء مجالس إدارات البنوك الراغبة في الاندماج أو الشراء أو من يفوضونهم بتفويض خاص تبادل المعلومات الضرورية\n⭐ ويعتبرون مسؤولين شخصياً عن المحافظة على سريتها تحت طائلة المساءلة القانونية","qs":[{"q":"يحق تبادل المعلومات الضرورية بين البنوك الراغبة في الاندماج أو الشراء لـ:","o":["رؤساء مجالس إداراتها أو من يفوضونهم بتفويض خاص","أي موظف في البنكين","المساهمين الرئيسيين","مدققي الحسابات الخارجيين فقط"],"a":0},{"q":"مسؤولية الأشخاص الذين يتبادلون معلومات البنوك لدراسة الاندماج عن المحافظة على سريتها هي مسؤولية:","o":["شخصية تحت طائلة المساءلة القانونية","تقع على البنك المركزي","تقع على الهيئة العامة للبنك","تقع على مؤسسة ضمان الودائع وحدها"],"a":0}]},{"n":"84","chapter":"التصفية","notes":[],"source":"أ- على الرغم مما ورد في قانون الشركات أو أي قانون آخر، يكون البنك المركزي هو الجهة الوحيدة المختصة بإصدار القرار بتصفية أي بنك.\nب- يجوز للبنك المركزي إصدار القرار بتصفية البنك في أي من الحالات التالية:\n١- إذا ارتكب مخالفة أو اكثر قد تؤدي إلى تبديد موجوداته أو إلى المساس بحقوق المودعين.\n٢- إذا اصبح غير قادر على مقابلة الطلب على ودائعه أو الوفاء بأي من التزاماته.\n٣- إذا زاد مجموع خسائره على (%٧٥) من رأسماله المكتتب به.\n٤- إذا صدر قرار بإلغاء ترخيصه.\nج- لا يجوز للهيئة العامة لمساهمي البنك أن تصدر أي قرار بشأن تصفية البنك إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.\nد- ينشر قرار التصفية في الجريدة الرسمية وفي صحيفتين يوميتين محليتين خلال مدة لا تزيد على سبعة أيام من تاريخ صدوره.\nه- لا تطبق على البنك أحكام الإفلاس المشار إليها في قانون التجارة الساري المفعول أو أي قانون آخر قد يعدله أو يحل محله.","title":"قرار تصفية البنك","memo":"⭐ البنك المركزي الجهة الوحيدة المختصة بإصدار قرار تصفية أي بنك\n⭐ الحالات: مخالفة تؤدي لتبديد الموجودات أو المساس بحقوق المودعين، العجز عن الوفاء، خسائر تزيد على (٧٥%) من رأس المال المكتتب به، إلغاء الترخيص\n⭐ ينشر القرار في الجريدة الرسمية وصحيفتين يوميتين خلال مدة لا تزيد على سبعة أيام\n⭐ لا تطبق على البنك أحكام الإفلاس في قانون التجارة","qs":[{"q":"يجوز للبنك المركزي إصدار قرار بتصفية البنك إذا زاد مجموع خسائره على:","o":["٧٥% من رأسماله المكتتب به","٥٠% من رأسماله المكتتب به","١٠٠% من رأسماله المكتتب به","٢٥% من رأسماله المدفوع"],"a":0},{"q":"ينشر قرار تصفية البنك في الجريدة الرسمية وفي صحيفتين يوميتين محليتين خلال مدة لا تزيد على:","o":["سبعة أيام من تاريخ صدوره","ثلاثين يوماً من تاريخ صدوره","خمسة عشر يوماً من تاريخ صدوره","ثلاثة أيام من تاريخ صدوره"],"a":0},{"q":"الجهة الوحيدة المختصة بإصدار القرار بتصفية أي بنك هي:","o":["البنك المركزي","مراقب الشركات","المحكمة المختصة","الهيئة العامة لمساهمي البنك"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي تجيز للبنك المركزي تصفية البنك؟","o":["انخفاض أرباح البنك عن السنة السابقة","إذا أصبح غير قادر على مقابلة الطلب على ودائعه","إذا صدر قرار بإلغاء ترخيصه","إذا ارتكب مخالفة قد تؤدي إلى المساس بحقوق المودعين"],"a":0}]},{"n":"85","chapter":"التصفية","notes":[],"source":"على الرغم مما ورد في قانون الشركات ومع مراعاة أحكام الفقرة (ج) من المادة (١٠١) من هذا القانون إذا قرر البنك المركزي تصفية البنك وفقاً لأحكام المادة (٨٤) من هذا القانون تكون مؤسسة ضمان الودائع هي المصفي الوحيد لهذا البنك.","title":"المصفي الوحيد للبنك","memo":"⭐ إذا قرر البنك المركزي تصفية البنك تكون مؤسسة ضمان الودائع هي المصفي الوحيد (مع مراعاة م101/ج)","qs":[{"q":"إذا قرر البنك المركزي تصفية البنك وفق القانون، يكون المصفي الوحيد لهذا البنك:","o":["مؤسسة ضمان الودائع","البنك المركزي","مراقب الشركات","مصفٍ تعينه المحكمة"],"a":0},{"q":"يكون قرار تصفية البنك الذي تتولى مؤسسة ضمان الودائع تنفيذه صادراً عن:","o":["البنك المركزي وفقاً لأحكام المادة (٨٤)","الهيئة العامة للبنك وفقاً لقانون الشركات","مراقب الشركات","محكمة البداية المختصة"],"a":0}]},{"n":"86","chapter":"التصفية","notes":[],"source":"أ- يكون القرار الذي يصدره البنك المركزي لتصفية البنك قابلاً للطعن لدى محكمة العدل العليا خلال ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية ممن يتوافر فيه أي من الشروط التالية:\n١- أن يكون مالكا ما لا يقل عن (%١٠) من رأسمال البنك المكتتب به.\n٢- أن تكون له ودائع لا تقل نسبتها عن (%١٠) من إجمالي الودائع لدى البنك.\n٣- أن يكون له دين على البنك لا تقل نسبته عن (%١٠) من إجمالي الديون المطلوبة من البنك.\nب- إذا قررت محكمة العدل العليا إلغاء قرار التصفية فعلى البنك، قبل عودته لممارسة أعماله، التقيد بأي متطلبات أو شروط خاصة يقررها البنك المركزي.","title":"الطعن في قرار التصفية","memo":"⭐ يطعن لدى محكمة العدل العليا خلال ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية\n⭐ يحق الطعن لمن يملك (١٠%) على الأقل من رأس المال المكتتب به، أو ودائع لا تقل عن (١٠%) من إجمالي الودائع، أو ديناً لا يقل عن (١٠%) من إجمالي الديون\n⭐ إذا ألغت المحكمة القرار، يتقيد البنك قبل عودته بأي شروط يقررها البنك المركزي","qs":[{"q":"مدة الطعن في قرار البنك المركزي بتصفية البنك هي:","o":["ثلاثون يوماً من تاريخ نشره في الجريدة الرسمية","ستون يوماً من تاريخ صدوره","سبعة أيام من تاريخ نشره","خمسة عشر يوماً من تاريخ تبليغه"],"a":0},{"q":"يحق الطعن في قرار التصفية لمن يملك من رأسمال البنك المكتتب به ما لا يقل عن:","o":["١٠%","٥%","٢٥%","٧٥%"],"a":0},{"q":"حالة عملية: مودع تبلغ ودائعه ٤% من إجمالي الودائع لدى البنك وليس مساهماً ولا دائناً. وفق القانون:","o":["لا يحق له الطعن في قرار التصفية لعدم بلوغ ودائعه ١٠% من إجمالي الودائع","يحق له الطعن لأن جميع المودعين لهم حق الطعن","يحق له الطعن خلال ستين يوماً","يحق له الطعن بموافقة البنك المركزي"],"a":0}]},{"n":"87","chapter":"التصفية","notes":[],"source":"إذا قرر البنك المركزي إلغاء ترخيص فرع البنك الأجنبي أو قرر تصفيته، لا يجوز للشركة الأم أن تتصرف بأي من موجودات الفرع وأمواله أو تحويلها إلى خارج المملكة إلا بعد تسديد جميع الالتزامات المترتبة عليه داخل المملكة.","title":"موجودات فرع البنك الأجنبي","memo":"⭐ عند إلغاء ترخيص فرع البنك الأجنبي أو تصفيته لا يجوز للشركة الأم التصرف بموجوداته أو تحويلها للخارج إلا بعد تسديد جميع التزاماته داخل المملكة","qs":[{"q":"إذا قرر البنك المركزي تصفية فرع بنك أجنبي، فلا يجوز للشركة الأم تحويل موجودات الفرع إلى خارج المملكة إلا بعد:","o":["تسديد جميع الالتزامات المترتبة عليه داخل المملكة","موافقة السلطات الرقابية في دولة المقر","مرور سنة على قرار التصفية","تسديد نصف الالتزامات المترتبة عليه"],"a":0},{"q":"يسري حظر تصرف الشركة الأم بموجودات فرع البنك الأجنبي في حالة:","o":["إلغاء ترخيص الفرع أو تصفيته","تغيير مدير الفرع","فتح فرع جديد","تعديل رأسمال الشركة الأم"],"a":0}]},{"n":"88","chapter":"إجراءات التصويب والعقوبات","notes":[],"source":"أ- للبنك المركزي أن يتخذ أياً من الإجراءات أو أن يفرض أياً من العقوبات المنصوص عليها في الفقرة (ب) من هذه المادة وذلك في الحالات التي يتبين فيها أن البنك أو أياً من الإداريين فيه قد ارتكب أياً من المخالفات التالية:\n١- مخالفة أحكام هذا القانون أو أي من الأنظمة والتعليمات والأوامر الصادرة بمقتضاه.\n٢- قيام البنك أو إحدى الشركات التابعة له بعمليات غير سليمة وغير آمنة لمصلحة مساهميه أو دائنيه أو المودعين لديه.\nب- مع مراعاة أحكام الفقرة (د) من هذه المادة، إذا وقعت أي من المخالفات المنصوص عليها في الفقرة (أ) من هذه المادة، يجوز للمحافظ أن يتخذ إجراء أو أكثر أو أن يفرض عقوبة أو أكثر من الإجراءات والعقوبات التالية:\n١- توجيه تنبيه خطي.\n٢- الطلب من البنك تقديم برنامج مرض لما سيتخذه من إجراءات لإزالة المخالفة وتصويب الوضع.\n٣- الطلب من البنك وقف بعض عملياته أو منعه من توزيع الأرباح.\n٤- فرض غرامة على البنك لا تتجاوز خمسمائة ألف دينار أردني.\n٥- الطلب من البنك إيقاف أي من إدارييه من غير أعضاء مجلس الإدارة عن العمل بشكل مؤقت أو طلب فصله تبعا لخطورة المخالفة.\n٦- الطلب من البنك ملاحقة أي من الإداريين فيه وفق الأصول القانونية.\n٧- تنحية رئيس مجلس إدارة البنك أو أي من أعضائه.\n٨- حل مجلس إدارة البنك وتولي إدارته من قبل البنك المركزي لمدة لا تزيد على أربعة وعشرين شهراً، ويجوز له تمديدها حسب الضرورة.\n٩- إلغاء ترخيص البنك.\nج- على المحافظ أن يحصل على موافقة مسبقة من المجلس قبل اتخاذ أي من الإجراءات أو فرضه أي من العقوبات المنصوص عليها في البنود من (٤) إلى (٩) من الفقرة (ب) من هذه المادة.\nد- لكل ذي مصلحة الطعن في إجراءات أو قرارات البنك المركزي المنصوص عليها في الفقرة (ب) من هذه المادة أمام المحكمة الإدارية خلال ثلاثين يوماً من تاريخ اتخاذ الإجراء أو صدور القرار.\nه- إذا تقرر اتخاذ أي من الإجراءات أو أي من العقوبات المنصوص عليها في هذه المادة فإن ذلك لا يمنع من قيام المسؤولية المدنية والجزائية وفقاً لأحكام أي تشريع آخر.","title":"إجراءات التصويب والعقوبات","memo":"⭐ للمحافظ: تنبيه خطي، برنامج تصويب، وقف عمليات أو منع توزيع أرباح، غرامة لا تتجاوز (٥٠٠٠٠٠) دينار، إيقاف إداريين، تنحية رئيس/أعضاء المجلس، حل المجلس (٢٤ شهراً قابلة للتمديد)، إلغاء الترخيص\n⭐ يلزم موافقة مسبقة من المجلس للبنود من (٤) إلى (٩)\n⭐ الطعن أمام المحكمة الإدارية خلال ثلاثين يوماً من تاريخ اتخاذ الإجراء\n⭐ لا يمنع ذلك من قيام المسؤولية المدنية والجزائية","qs":[{"q":"الحد الأقصى للغرامة التي يجوز للمحافظ فرضها على البنك المخالف هو:","o":["خمسمائة ألف دينار","خمسون ألف دينار","مائة ألف دينار","مليون دينار"],"a":0},{"q":"إذا قرر المحافظ حل مجلس إدارة البنك وتولي البنك المركزي إدارته كعقوبة، فإن المدة لا تزيد على:","o":["أربعة وعشرين شهراً ويجوز تمديدها حسب الضرورة","اثني عشر شهراً قابلة للتمديد لمرة واحدة","ستة وثلاثين شهراً غير قابلة للتمديد","ستة أشهر"],"a":0},{"q":"أي من العقوبات التالية لا يحتاج المحافظ لفرضها إلى موافقة مسبقة من المجلس؟","o":["توجيه تنبيه خطي","فرض غرامة على البنك","إلغاء ترخيص البنك","تنحية رئيس مجلس إدارة البنك"],"a":0},{"q":"يحق لكل ذي مصلحة الطعن في إجراءات وعقوبات البنك المركزي المنصوص عليها في هذه المادة أمام المحكمة الإدارية خلال:","o":["ثلاثين يوماً من تاريخ اتخاذ الإجراء أو صدور القرار","ستين يوماً من تاريخ نشر القرار","خمسة عشر يوماً من تاريخ التبليغ","تسعين يوماً من تاريخ القرار"],"a":0}]},{"n":"89","chapter":"أحكام ختامية","notes":[],"source":"تبدأ السنة المالية للبنك في بداية كانون الثاني من السنة وتنتهي في نهاية كانون الأول من تلك السنة.","title":"السنة المالية للبنك","memo":"⭐ تبدأ السنة المالية للبنك في بداية كانون الثاني وتنتهي في نهاية كانون الأول","qs":[{"q":"تبدأ السنة المالية للبنك وتنتهي وفق القانون:","o":["من بداية كانون الثاني إلى نهاية كانون الأول","من بداية نيسان إلى نهاية آذار","من بداية تموز إلى نهاية حزيران","وفق ما يحدده النظام الأساسي لكل بنك"],"a":0}]},{"n":"90","chapter":"أحكام ختامية","notes":[],"source":"أ- تعتبر البنوك المرخصة من البنك المركزي بتاريخ نفاذ هذا القانون كأنها مرخصة بموجبه.\nب- ويعتبر البنك الإسلامي الأردني للتمويل والاستثمار والبنوك الإسلامية الأخرى المرخصة بتاريخ نفاذ هذا القانون كأنها مرخصة بموجبه.\nج-تستمر الشركات المالية المرخصة من البنك المركزي قبل تاريخ نفاذ هذا القانون في عملها وتخضع لجميع أحكامه.","title":"البنوك المرخصة قبل نفاذ القانون","memo":"⭐ البنوك المرخصة بتاريخ نفاذ القانون تعتبر كأنها مرخصة بموجبه، ومنها البنك الإسلامي الأردني للتمويل والاستثمار والبنوك الإسلامية الأخرى\n⭐ تستمر الشركات المالية المرخصة قبل نفاذه في عملها وتخضع لجميع أحكامه","qs":[{"q":"البنوك المرخصة من البنك المركزي بتاريخ نفاذ قانون البنوك:","o":["تعتبر كأنها مرخصة بموجبه","يجب عليها الحصول على ترخيص جديد","تمنح مهلة سنة لإعادة الترخيص","تخضع للقانون الملغى"],"a":0},{"q":"الشركات المالية المرخصة من البنك المركزي قبل تاريخ نفاذ القانون:","o":["تستمر في عملها وتخضع لجميع أحكامه","تلغى تراخيصها حكماً","تستمر في عملها دون أن تخضع لأحكامه","تتحول إلى بنوك إسلامية"],"a":0}]},{"n":"91","chapter":"أحكام ختامية","notes":[],"source":"تعتبر فروع البنك في المملكة ومكاتبه الخاصة بإدارة هذه الفروع بنكاً واحداً لغايات هذا القانون.","title":"فروع البنك بنك واحد","memo":"⭐ فروع البنك في المملكة ومكاتبه الخاصة بإدارتها تعتبر بنكاً واحداً لغايات القانون","qs":[{"q":"تعتبر فروع البنك في المملكة ومكاتبه الخاصة بإدارة هذه الفروع لغايات قانون البنوك:","o":["بنكاً واحداً","بنوكاً مستقلة بعدد الفروع","شركات تابعة للبنك","شركات مالية"],"a":0}]},{"n":"92","chapter":"أحكام ختامية","notes":[],"source":"أ- للبنك المركزي وبالتنسيق مع البنوك وضع نظام إلكتروني لتحويل الأموال بين البنوك وإجراء عمليات التقاص والتسوية ويحق للبنك المركزي إدارة هذا النظام وإجراء عمليات الدفع والقبض بوساطته.\nب- للبنوك أن تستخدم أنظمة الأرشفة الإلكترونية للاحتفاظ بسجلات إلكترونية بدلاً من أصول الدفاتر والسجلات والكشوفات والوثائق والمراسلات والبرقيات والإشعارات وأي أوراق متعلقة بأعمالها المالية للمدة المقررة في التشريعات النافذة، شريطة مراعاة أحكام قانون المعاملات الإلكترونية.\nج- على الرغم مما ورد في قانون الشركات، يجوز لأعضاء مجلس إدارة البنك حضور اجتماعاته بوساطة أي من وسائل الاتصال الهاتفي المرئي لمناقشة جدول أعمال الاجتماع على أن يصادق رئيس المجلس وأمين السر على محضر الاجتماع ونصابه القانوني.\nد- تعفى البنوك التي تستخدم في تنظيم عملياتها المالية الحاسب الآلي أو غيره من أجهزة التقنية الحديثة من تنظيم دفاتر التجارة التي يقتضيها قانون التجارة النافذ المفعول وتعتبر المعلومات المستقاة من تلك الأجهزة أو غيرها من الأساليب الحديثة بمثابة دفاتر تجارية شريطة مراعاة أحكام قانون المعاملات الإلكترونية.\nه-تعتبر جميع الأعمال المصرفية والنشاطات المالية تجارية بحكم ما هيتها الذاتية بغض النظر عن صفة العميل المتعاقد أو المتعامل مع البنك سواءً كان مدنياً أو تجارياً، وتسري عليها أحكام قانون التجارة الساري المفعول ويجوز إثباتها بطرق الإثبات كافة كما لا تخضع لأحكام نظام المرابحة.\nو-على الرغم من أحكام أي تشريع آخر، يجوز للبنك أن يحيل إلى شخص آخر أي حق له أو ائتمان منحه إلى عميله وتأميناته العينية والشخصية أو أن يقبل أي حوالة حق له وذلك دون حاجة للحصول على موافقة المدين أو العميل أو الراهن أو الكفيل إلا إذا وجد اتفاق يمنع ذلك.\nز-على الرغم من أحكام أي تشريع آخر، للبنك المركزي أن يصدر أوامر خاصة يمنع بموجبها البنوك من قبول الشيكات المسحوبة عليها إذا كانت غير صادرة على نماذجها أو إذا لم تتوفر فيها أي شروط خاصة أخرى تحددها أوامر البنك المركزي لتسهيل خدمة التقاص بين البنوك.","title":"أحكام التقنية والأعمال المصرفية","memo":"⭐ للبنك المركزي بالتنسيق مع البنوك وضع نظام إلكتروني لتحويل الأموال والتقاص والتسوية وإدارته\n⭐ حضور اجتماعات مجلس الإدارة بالاتصال الهاتفي المرئي، ويصادق رئيس المجلس وأمين السر على المحضر والنصاب\n⭐ الأعمال المصرفية تجارية بحكم ماهيتها، تثبت بطرق الإثبات كافة، ولا تخضع لنظام المرابحة\n⭐ يجوز للبنك حوالة حقوقه وائتماناته دون موافقة المدين أو الكفيل إلا إذا وجد اتفاق يمنع ذلك","qs":[{"q":"يجوز لأعضاء مجلس إدارة البنك حضور اجتماعاته بوسائل الاتصال الهاتفي المرئي، على أن يصادق على محضر الاجتماع ونصابه:","o":["رئيس المجلس وأمين السر","البنك المركزي","مراقب الشركات","جميع الأعضاء الحاضرين"],"a":0},{"q":"تعتبر الأعمال المصرفية والنشاطات المالية وفق القانون:","o":["تجارية بحكم ماهيتها الذاتية بغض النظر عن صفة العميل","مدنية إذا كان العميل مدنياً","تجارية إذا كان العميل تاجراً فقط","خاضعة لنظام المرابحة"],"a":0},{"q":"حالة عملية: أراد بنك أن يحيل إلى شخص آخر ائتماناً منحه لعميله مع تأميناته. وفق القانون يجوز ذلك:","o":["دون حاجة لموافقة المدين أو الكفيل إلا إذا وجد اتفاق يمنع ذلك","بشرط موافقة المدين الخطية","بشرط موافقة البنك المركزي المسبقة","بقرار من المحكمة المختصة"],"a":0},{"q":"البنوك التي تستخدم الحاسب الآلي في تنظيم عملياتها المالية:","o":["تعفى من تنظيم دفاتر التجارة التي يقتضيها قانون التجارة","تلتزم بتنظيم الدفاتر الورقية إضافة للإلكترونية","تعفى من تدقيق الحسابات","تعفى من أحكام قانون المعاملات الإلكترونية"],"a":0}]},{"n":"93","chapter":"أحكام ختامية","notes":[],"source":"أ- إذا علم البنك أن تنفيذ أي معاملة مصرفية أو أن تسلم أو دفع أي مبلغ يتعلق أو يمكن أن يتعلق بأي جريمة أو بأي عمل غير مشروع، فعليه أن يقوم فورا بإشعار البنك المركزي بذلك.\nب- إذا تسلم البنك المركزي الإشعار المنصوص عليه في الفقرة (أ) من هذه المادة أو إذا علم من مصدر آخر أنه قد طلب من البنك تنفيذ معاملة مصرفية أو تسلم أو دفع مبلغ يتعلق أو يمكن أن يتعلق بجريمة أو بعمل غير مشروع، فعلى البنك المركزي، وعلى الرغم من أحكام أي تشريع آخر، إصدار أمر إلى ذلك البنك بالامتناع عن تنفيذ تلك المعاملة أو عن تسلم أو دفع ذلك المبلغ لمدة أقصاها ثلاثون يوماً وعلى البنك المركزي إشعار أي جهة رسمية أو قضائية بذلك.\nج- لا يعتبر إفصاح البنك عن أي معلومات بموجب أحكام هذه المادة إخلالاً بواجب الالتزام بالسرية المصرفية، كما لا يتحمل البنك المركزي أو البنك أي مسؤولية نتيجة لذلك.","title":"المعاملات المشبوهة","memo":"⭐ إذا علم البنك أن معاملة تتعلق أو يمكن أن تتعلق بجريمة فعليه إشعار البنك المركزي فوراً\n⭐ يأمر البنك المركزي بالامتناع عن تنفيذها مدة أقصاها ثلاثون يوماً ويشعر الجهات الرسمية أو القضائية\n⭐ لا يعد الإفصاح إخلالاً بالسرية المصرفية ولا مسؤولية على البنك أو البنك المركزي","qs":[{"q":"إذا علم البنك أن تنفيذ معاملة مصرفية يمكن أن يتعلق بجريمة، فعليه أن يقوم فوراً بإشعار:","o":["البنك المركزي","مراقب الشركات","جمعية البنوك","مؤسسة ضمان الودائع"],"a":0},{"q":"المدة القصوى لأمر البنك المركزي للبنك بالامتناع عن تنفيذ المعاملة المشبوهة هي:","o":["ثلاثون يوماً","سبعة أيام","ستون يوماً","تسعون يوماً"],"a":0},{"q":"إفصاح البنك عن المعلومات المتعلقة بالمعاملات المشبوهة وفق القانون:","o":["لا يعتبر إخلالاً بواجب السرية المصرفية ولا يرتب مسؤولية على البنك","يعتبر إخلالاً بالسرية ويعاقب عليه","يتطلب موافقة العميل الخطية","يتطلب قراراً قضائياً مسبقاً"],"a":0}]},{"n":"94","chapter":"أحكام ختامية","notes":[],"source":"على مراقب الشركات التنسيق مع البنك المركزي للتحقق من أن غايات تأسيس أي شركة مالية وأنشطتها لا تتعارض مع أحكام هذا القانون.","title":"التنسيق بشأن تأسيس الشركات المالية","memo":"⭐ على مراقب الشركات التنسيق مع البنك المركزي للتحقق من أن غايات تأسيس أي شركة مالية وأنشطتها لا تتعارض مع القانون","qs":[{"q":"الجهة الملزمة بالتنسيق مع البنك المركزي للتحقق من أن غايات تأسيس الشركة المالية لا تتعارض مع قانون البنوك هي:","o":["مراقب الشركات","هيئة الأوراق المالية","وزير المالية","جمعية البنوك"],"a":0}]},{"n":"95","chapter":"أحكام ختامية","notes":[],"source":"أ- يؤسس بمقتضى أحكام هذا القانون جمعية تسمى (جمعية البنوك) تتمتع بالشخصية الاعتبارية.\nب- تتولى الجمعية التنسيق بين البنوك وتحقيق التعاون فيما بينها، وتحدد سائر مهام الجمعية وشروط العضوية فيها وأعمالها وتشكيل هيئتها العامة ومجلس إدارتها واجتماعات كل منهما وكذلك رسوم الانتساب إليها والاشتراك السنوي فيها وغرامات التأخير على كل منها بموجب نظام يصدر بمقتضى أحكام هذا القانون بناء على تنسيب من البنك المركزي.\nج- تعتبر الجمعية المنصوص عليها في الفقرة (أ) من هذه المادة الخلف القانوني والواقعي لجمعية البنوك في الأردن المسجلة استناداً لأحكام قانون الجمعيات والهيئات الاجتماعية رقم (٣٣) لسنة ١٩٦٦، وتؤول إليها جميع موجودات هذه الجمعية وأموالها المنقولة وغير المنقولة وحقوقها كما تتحمل الالتزامات المترتبة عليها.\nد- إلى أن يصدر النظام المشار إليه في الفقرة (ب) من هذه المادة ،يستمر العمل بالنظام الأساسي لجمعية البنوك في الأردن المعمول به بتاريخ نفاذ هذا القانون، كما يستمر مجلس إدارتها في تولي إدارة شؤون الجمعية إلى حين انتخاب مجلس إدارة جديد وفقاً لأحكام ذلك النظام.","title":"جمعية البنوك","memo":"⭐ تؤسس (جمعية البنوك) بشخصية اعتبارية، تتولى التنسيق والتعاون بين البنوك\n⭐ مهامها وعضويتها ورسومها تحدد بنظام بناءً على تنسيب البنك المركزي\n⭐ هي الخلف القانوني والواقعي لجمعية البنوك في الأردن المسجلة وفق قانون الجمعيات رقم (٣٣) لسنة ١٩٦٦","qs":[{"q":"تتولى جمعية البنوك المؤسسة بموجب قانون البنوك:","o":["التنسيق بين البنوك وتحقيق التعاون فيما بينها","الرقابة على البنوك وتفتيشها","تصفية البنوك المتعثرة","ترخيص البنوك الجديدة"],"a":0},{"q":"تحدد مهام جمعية البنوك وشروط العضوية فيها ورسوم الانتساب بموجب:","o":["نظام يصدر بناءً على تنسيب من البنك المركزي","تعليمات يصدرها وزير الصناعة والتجارة","قرار من مجلس إدارة الجمعية فقط","أوامر يصدرها المحافظ مباشرة"],"a":0},{"q":"إلى أن يصدر النظام الخاص بجمعية البنوك:","o":["يستمر العمل بالنظام الأساسي لجمعية البنوك في الأردن ويستمر مجلس إدارتها في إدارة شؤونها","تتولى وزارة التنمية الاجتماعية إدارة الجمعية","يتولى البنك المركزي إدارة الجمعية","يتوقف عمل الجمعية"],"a":0}]},{"n":"96","chapter":"أحكام ختامية","notes":[],"source":"أ- مع مراعاة أحكام أي تشريع آخر، لا يجوز لمدقق حسابات البنك أو لمحاميه أو لمستشاره القانوني بموجب وكالة عامة أو عقد سنوي أن يكون مديناً للبنك أو لإحدى الشركات التابعة أو كفيلاً لأحد مدينيهم.\nب- كما لا يجوز لمحامي البنك أو مستشاره القانوني أن يكون عضواً في مجلس إدارة البنك أو إحدى شركاته التابعة أو أن تكون له أي منفعة في البنك أو في إحدى الشركات التابعة.","title":"قيود على المدقق والمحامي","memo":"⭐ لا يجوز لمدقق حسابات البنك أو محاميه أو مستشاره القانوني (بوكالة عامة أو عقد سنوي) أن يكون مديناً للبنك أو شركاته التابعة أو كفيلاً لأحد مدينيهم\n⭐ لا يجوز لمحامي البنك أو مستشاره القانوني أن يكون عضواً في مجلس إدارة البنك أو شركاته التابعة أو أن تكون له منفعة فيه","qs":[{"q":"أي مما يلي يحظر على مدقق حسابات البنك وفق القانون؟","o":["أن يكون مديناً للبنك أو كفيلاً لأحد مدينيه","أن يكون له حساب جارٍ دائن لدى البنك","أن يدقق حسابات شركة أخرى","أن يحضر اجتماع الهيئة العامة"],"a":0},{"q":"حالة عملية: المستشار القانوني لبنك بموجب عقد سنوي رُشح لعضوية مجلس إدارة إحدى الشركات التابعة للبنك. وفق القانون:","o":["لا يجوز له ذلك","يجوز ذلك بموافقة البنك المركزي","يجوز ذلك إذا كانت الشركة غير مصرفية","يجوز ذلك بقرار من الهيئة العامة"],"a":0}]},{"n":"97","chapter":"أحكام ختامية","notes":[],"source":"أ- تحصل الغرامات المفروضة على البنك بمقتضى هذا القانون أو بمقتضى أي قانون آخر من قبل البنك المركزي.\nب- تقيد الغرامات على حساب البنك لدى البنك المركزي وتحول شهريا لحساب الخزينة.","title":"تحصيل الغرامات","memo":"⭐ يحصل البنك المركزي الغرامات المفروضة على البنك بمقتضى هذا القانون أو أي قانون آخر\n⭐ تقيد على حساب البنك لدى البنك المركزي وتحول شهرياً لحساب الخزينة","qs":[{"q":"الجهة التي تحصل الغرامات المفروضة على البنك بمقتضى قانون البنوك أو أي قانون آخر هي:","o":["البنك المركزي","وزارة المالية","دائرة الجمارك","مؤسسة ضمان الودائع"],"a":0},{"q":"تحول الغرامات المقيدة على حساب البنك لدى البنك المركزي إلى حساب الخزينة:","o":["شهرياً","سنوياً","كل ثلاثة أشهر","فور قيدها يومياً"],"a":0}]},{"n":"98","chapter":"أحكام ختامية","notes":[],"source":"على البنوك والشركات المالية توفيق أوضاعها سواءً ما تعلق بالإدارة أو التنظيم أو بأعمالها وأنشطتها وكذلك إجراء التعديلات اللازمة على عقود تأسيسها وأنظمتها بما يتفق مع أحكام هذا القانون، بقرارات تتخذها مجالس إداراتها دون حاجة إلى دعوة الهيئات العامة لإقرار تلك التعديلات، وعلى أن ينتهي توفيق الأوضاع خلال مدة لا تتجاوز سنتين من تاريخ نفاذ أحكام هذا القانون.","title":"توفيق أوضاع البنوك والشركات المالية","memo":"⭐ توفيق الأوضاع وتعديل عقود التأسيس بقرارات من مجالس الإدارات دون حاجة لدعوة الهيئات العامة\n⭐ خلال مدة لا تتجاوز سنتين من تاريخ نفاذ القانون","qs":[{"q":"المدة القصوى لتوفيق أوضاع البنوك والشركات المالية مع أحكام القانون هي:","o":["سنتان من تاريخ نفاذ القانون","سنة واحدة من تاريخ نفاذ القانون","ثلاث سنوات من تاريخ نفاذ القانون","خمس سنوات من تاريخ نفاذ القانون"],"a":0},{"q":"تجرى التعديلات اللازمة على عقود تأسيس البنوك وأنظمتها لتوفيق أوضاعها بقرارات من:","o":["مجالس إداراتها دون حاجة إلى دعوة الهيئات العامة","الهيئات العامة غير العادية","البنك المركزي مباشرة","مراقب الشركات"],"a":0}]},{"n":"99","chapter":"أحكام ختامية","notes":[],"source":"أ- لمجلس الوزراء بناءً على تنسيب البنك المركزي أن يضع الأنظمة اللازمة لتنفيذ أحكام هذا القانون.\nب- للبنك المركزي أن يصدر الأوامر التي يراها لازمة لتنفيذ أحكام هذا القانون بشكل إفرادي أو إجمالي.","title":"الأنظمة والأوامر التنفيذية","memo":"⭐ لمجلس الوزراء بناءً على تنسيب البنك المركزي وضع الأنظمة اللازمة لتنفيذ القانون\n⭐ للبنك المركزي إصدار الأوامر اللازمة بشكل إفرادي أو إجمالي","qs":[{"q":"يضع الأنظمة اللازمة لتنفيذ أحكام قانون البنوك:","o":["مجلس الوزراء بناءً على تنسيب البنك المركزي","البنك المركزي منفرداً","وزير المالية بناءً على تنسيب جمعية البنوك","مجلس الأمة"],"a":0},{"q":"يصدر البنك المركزي الأوامر اللازمة لتنفيذ أحكام القانون:","o":["بشكل إفرادي أو إجمالي","بشكل إجمالي فقط","بعد موافقة مجلس الوزراء فقط","بشكل إفرادي فقط"],"a":0}]},{"n":"100","chapter":"أحكام ختامية","notes":[],"source":"تطبق أحكام قانون الشركات الساري المفعول أو أي قانون آخر قد يحل محله على البنوك بالقدر والحدود التي لا تتعارض فيها تلك الأحكام مع أحكام هذا القانون والأنظمة والأوامر الصادرة بمقتضاه.","title":"تطبيق قانون الشركات على البنوك","memo":"⭐ تطبق أحكام قانون الشركات على البنوك بالقدر الذي لا يتعارض مع قانون البنوك والأنظمة والأوامر الصادرة بمقتضاه","qs":[{"q":"تطبق أحكام قانون الشركات على البنوك:","o":["بالقدر والحدود التي لا تتعارض مع أحكام قانون البنوك والأنظمة والأوامر الصادرة بمقتضاه","بشكل مطلق وتتقدم على قانون البنوك","فقط في حالات التصفية","لا تطبق على البنوك مطلقاً"],"a":0},{"q":"عند تعارض حكم في قانون الشركات مع أوامر البنك المركزي الصادرة بمقتضى قانون البنوك، فإن الذي يطبق على البنك هو:","o":["أوامر البنك المركزي الصادرة بمقتضى قانون البنوك","حكم قانون الشركات","ما تقرره الهيئة العامة للبنك","ما يقرره مراقب الشركات"],"a":0}]},{"n":"101","chapter":"أحكام ختامية","notes":[],"source":"أ- يلغى قانون البنوك رقم (٢٤) لسنة ١٩٧١ وتعديلاته، على أن تبقى جميع الأنظمة والأوامر والتعليمات الصادرة بموجبه سارية المفعول إلى أن تستبدل أو تعدل أو تلغى.\nب- يلغى قانون البنك الإسلامي الأردني للتمويل والاستثمار رقم (٦٢) لسنة ١٩٨٥.\nج- إذا تقرر تصفية أي بنك قبل صدور قانون خاص بإنشاء مؤسسة ضمان الودائع فيمارس البنك المركزي في هذه الحالة جميع الصلاحيات المنوطة بالمصفي بموجب أحكام القانون.","title":"الإلغاء والأحكام الانتقالية","memo":"⭐ يلغى قانون البنوك رقم (٢٤) لسنة ١٩٧١ مع بقاء أنظمته وأوامره سارية حتى تستبدل أو تعدل أو تلغى\n⭐ يلغى قانون البنك الإسلامي الأردني للتمويل والاستثمار رقم (٦٢) لسنة ١٩٨٥\n⭐ إذا تقررت تصفية بنك قبل صدور قانون مؤسسة ضمان الودائع يمارس البنك المركزي صلاحيات المصفي","qs":[{"q":"ألغى قانون البنوك رقم (٢٨) لسنة ٢٠٠٠ قانون البنوك السابق رقم:","o":["(٢٤) لسنة ١٩٧١","(٦٢) لسنة ١٩٨٥","(٣٣) لسنة ١٩٦٦","(٢٢) لسنة ١٩٩٧"],"a":0},{"q":"الأنظمة والأوامر والتعليمات الصادرة بموجب قانون البنوك الملغى:","o":["تبقى سارية المفعول إلى أن تستبدل أو تعدل أو تلغى","تلغى حكماً بنفاذ القانون الجديد","تبقى سارية لمدة سنتين فقط","تبقى سارية إذا صادق عليها مجلس الوزراء"],"a":0},{"q":"إذا تقرر تصفية أي بنك قبل صدور قانون خاص بإنشاء مؤسسة ضمان الودائع، فإن صلاحيات المصفي يمارسها:","o":["البنك المركزي","مراقب الشركات","مصفٍ تعينه المحكمة","وزير المالية"],"a":0}]},{"n":"102","chapter":"أحكام ختامية","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام القانون","qs":[]}]};
